    # Keep existing ACC role settings while correcting the role name.
    cur.execute(
        "SELECT id FROM management_roles WHERE role_name=? LIMIT 1",
        ("Academic Content Coordinator",)
    )
    academic_content_role = cur.fetchone()

    if academic_content_role:
        # If both names somehow exist, keep the correct one and remove the old duplicate.
        cur.execute(
            "DELETE FROM management_roles WHERE role_name=?",
            ("Admission Content Coordinator",)
        )
    else:
        cur.execute(
            """
            UPDATE management_roles
            SET role_name=?,
                updated_at=?
            WHERE role_name=?
            """,
            (
                "Academic Content Coordinator",
                now_utc_iso(),
                "Admission Content Coordinator"
            )
        )

    management_roles_seed = [
        "CEO",
        "COO",
        "CAO",
        "Admin",
        "Admission Coordinator",
        "Academic Content Coordinator",
        "Secretary",
        "Treasurer",
        "Social Media Manager",
        "Graphic Designer",
        "Academic Quality Manager",
        "Tutor Manager",
        "One-on-One Manager",
        "Human Resources (HR)"
    ]

    management_role_default_descriptions = {
        "One-on-One Manager": (
            "The One-on-One Manager oversees the planning, coordination and quality of EBTA one-on-one tutoring sessions.\n\n"
            "Main duties may include:\n"
            "- Reviewing and managing one-on-one tutoring requests.\n"
            "- Monitoring one-on-one tutors, their subjects and availability.\n"
            "- Assigning suitable tutors to learners and confirming session arrangements.\n"
            "- Adding or checking meeting links, meeting IDs and passcodes.\n"
            "- Monitoring scheduled, confirmed, completed and cancelled sessions.\n"
            "- Following up on outstanding tutor availability or session information.\n"
            "- Working with High Admin, AQM and other EBTA leaders when support or escalation is required.\n"
            "- Maintaining accurate records and protecting learner and tutor information.\n\n"
            "Requirements:\n"
            "- Strong organisation, communication and follow-up skills.\n"
            "- Reliable internet access and a suitable device.\n"
            "- Ability to work professionally with learners, parents, tutors and EBTA management.\n"
            "- Good attention to detail and ability to manage confidential information."
        ),
        "Graphic Designer": (
            "The Graphic Designer supports EBTA with professional visual content for academic, marketing and operational communication.\n\n"
            "Main duties may include:\n"
            "- Designing posters, learner announcements and social media graphics.\n"
            "- Creating certificates, event designs and promotional material.\n"
            "- Working with the Social Media Manager, COO and CEO on brand-aligned content.\n"
            "- Preparing clean, professional designs for EBTA campaigns, awards, tutor announcements and learner reminders.\n"
            "- Following EBTA colours, branding and communication standards.\n\n"
            "Requirements:\n"
            "- Good design skills using Canva, Adobe tools or similar design platforms.\n"
            "- Creativity, attention to detail and ability to meet deadlines.\n"
            "- Reliable internet access and a device suitable for design work.\n"
            "- Ability to communicate professionally and accept feedback from EBTA leadership."
        )
    }

    for role in management_roles_seed:
        cur.execute("""
            INSERT OR IGNORE INTO management_roles(
                role_name,
                is_open,
                description,
                created_at,
                updated_at
            )
            VALUES(?,?,?,?,?)
        """, (
            role,
            0,
            management_role_default_descriptions.get(role, ""),
            now_utc_iso(),
            now_utc_iso()
        ))

        default_description = management_role_default_descriptions.get(role, "")
        if default_description:
            cur.execute("""
                UPDATE management_roles
                SET description=?,
                    updated_at=?
                WHERE role_name=?
                  AND (description IS NULL OR TRIM(description) = '')
            """, (
                default_description,
                now_utc_iso(),
                role
            ))
    
