    # ================= LEARNING GAMES / STUDY ARCADE =================
    cur.execute("""
    CREATE TABLE IF NOT EXISTS learning_game_questions(
        id INTEGER PRIMARY KEY AUTOINCREMENT,

        subject_id INTEGER NOT NULL,
        grade TEXT NOT NULL,

        topic TEXT NOT NULL,
        game_type TEXT NOT NULL,
        difficulty TEXT NOT NULL DEFAULT 'Easy',

        question_text TEXT NOT NULL,
        options_json TEXT NOT NULL,
        correct_index INTEGER NOT NULL,
        explanation TEXT,

        points INTEGER NOT NULL DEFAULT 1,

        created_by_tutor_id INTEGER,
        status TEXT NOT NULL DEFAULT 'ACTIVE',

        created_at TEXT NOT NULL,
        updated_at TEXT,

        FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE,
        FOREIGN KEY(created_by_tutor_id) REFERENCES tutors(id) ON DELETE SET NULL
    );
    """)

    cur.execute("""
    CREATE TABLE IF NOT EXISTS learning_game_results(
        id INTEGER PRIMARY KEY AUTOINCREMENT,

        student_id INTEGER NOT NULL,
        subject_id INTEGER NOT NULL,
        grade TEXT NOT NULL,

        game_type TEXT NOT NULL,
        difficulty TEXT NOT NULL,

        score INTEGER NOT NULL DEFAULT 0,
        total_questions INTEGER NOT NULL DEFAULT 0,
        percentage REAL NOT NULL DEFAULT 0,

        badge TEXT,
        time_taken_seconds INTEGER NOT NULL DEFAULT 0,

        topic_summary_json TEXT,
        answer_details_json TEXT,

        played_at TEXT NOT NULL,

        FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,
        FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE
    );
    """)

    # Stores the maximum points for each game attempt. This prevents hard/boss-battle
    # games from showing percentages above 100% when questions carry more than 1 point.
    ensure_column(conn, "learning_game_results", "total_points", "INTEGER NOT NULL DEFAULT 0")

    # Repair older learning-game results that were calculated as score / question count.
    # The old calculation could show 120%, 240%, 300%, etc. when a learner earned
    # multiple points per question. We recalculate using the stored answer details
    # and each question's point value. If older details are missing, we safely cap.
    try:
        cur.execute("""
            SELECT id, score, total_questions, percentage, answer_details_json
            FROM learning_game_results
            WHERE COALESCE(total_points, 0) = 0
               OR COALESCE(percentage, 0) > 100
               OR COALESCE(percentage, 0) < 0
        """)
        game_result_rows = cur.fetchall()

        for game_row in game_result_rows:
            try:
                raw_details = json.loads(game_row["answer_details_json"] or "[]")
            except Exception:
                raw_details = []

            question_ids_for_result = []
            for detail in raw_details:
                try:
                    qid = int(detail.get("question_id"))
                    if qid not in question_ids_for_result:
                        question_ids_for_result.append(qid)
                except Exception:
                    pass

            points_by_question = {}
            if question_ids_for_result:
                qmarks = ",".join("?" for _ in question_ids_for_result)
                cur.execute(f"""
                    SELECT id, points
                    FROM learning_game_questions
                    WHERE id IN ({qmarks})
                """, question_ids_for_result)
                points_by_question = {
                    int(point_row["id"]): max(int(point_row["points"] or 1), 1)
                    for point_row in cur.fetchall()
                }

            total_points_for_result = 0
            if raw_details:
                for detail in raw_details:
                    try:
                        qid = int(detail.get("question_id"))
                    except Exception:
                        qid = 0
                    total_points_for_result += points_by_question.get(qid, 1)

            if total_points_for_result <= 0:
                try:
                    total_points_for_result = int(game_row["total_questions"] or 0)
                except Exception:
                    total_points_for_result = 0

            try:
                earned_points = float(game_row["score"] or 0)
            except Exception:
                earned_points = 0

            if total_points_for_result > 0:
                fixed_percentage = round((earned_points / float(total_points_for_result)) * 100, 1)
            else:
                fixed_percentage = 0

            if fixed_percentage < 0:
                fixed_percentage = 0
            if fixed_percentage > 100:
                fixed_percentage = 100

            if fixed_percentage >= 95:
                fixed_badge = "EBTA Legend"
            elif fixed_percentage >= 85:
                fixed_badge = "Top Achiever"
            elif fixed_percentage >= 75:
                fixed_badge = "Brain Champion"
            elif fixed_percentage >= 65:
                fixed_badge = "Rising Star"
            elif fixed_percentage >= 50:
                fixed_badge = "Keep Going"
            else:
                fixed_badge = "Revision Warrior"

            cur.execute("""
                UPDATE learning_game_results
                SET total_points=?,
                    percentage=?,
                    badge=?
                WHERE id=?
            """, (
                total_points_for_result,
                fixed_percentage,
                fixed_badge,
                game_row["id"]
            ))
    except Exception:
        pass

    cur.execute("CREATE INDEX IF NOT EXISTS idx_learning_game_questions_subject ON learning_game_questions(subject_id)")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_learning_game_questions_grade ON learning_game_questions(grade)")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_learning_game_questions_game_type ON learning_game_questions(game_type)")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_learning_game_questions_tutor ON learning_game_questions(created_by_tutor_id)")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_learning_game_questions_status ON learning_game_questions(status)")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_learning_game_results_student ON learning_game_results(student_id)")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_learning_game_results_subject ON learning_game_results(subject_id)")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_learning_game_results_grade ON learning_game_results(grade)")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_learning_game_results_played ON learning_game_results(played_at)")

    # ---- Seed starter CAPS-aligned learning game questions ----
    # This prevents learners from seeing "No Questions Yet" before tutors add their own question banks.
    # It creates a light starter bank for every subject, every game type and every difficulty.
    # It only seeds a subject/game/difficulty combination when that exact combination has zero active questions.

    def starter_questions_for_subject(subject_name, grade, game_type, difficulty):
        """
        CAPS-aligned starter questions for Learning Games.

        This version intentionally avoids repeating the same basic question across
        game modes. Each game mode asks the concept differently:
        - Speed Quiz: direct skill check
        - Match the Concept: concept meaning / method
        - Boss Battle: scenario-based application
        - Career Quest: real-life or study/career application
        """

        name = str(subject_name or "").strip()
        grade_code = str(grade or "").strip()

        if grade_code.startswith("G"):
            grade_text = grade_code.replace("G", "Grade ")
        else:
            grade_text = grade_code or "Grade"

        try:
            grade_num = int(str(grade_code).replace("G", "").strip())
        except Exception:
            grade_num = 0

        difficulty = str(difficulty or "Medium").strip().title()
        game_type = str(game_type or "Speed Quiz").strip()

        def item(topic, question, correct, wrong1, wrong2, wrong3, explanation):
            return {
                "topic": topic,
                "question": question,
                "correct": correct,
                "wrong1": wrong1,
                "wrong2": wrong2,
                "wrong3": wrong3,
                "explanation": explanation,
            }

        def common_study_bank():
            return [
                item("Active revision", f"A {grade_text} learner keeps getting the same type of {name} question wrong. What is the best next step?",
                     "Identify the error pattern, correct it, then practise similar questions", "Memorise only the final answers", "Stop practising that topic", "Wait until the test to try again",
                     "CAPS learning improves when learners correct misconceptions and practise similar tasks."),
                item("Question analysis", f"Before answering a longer {name} question, what should a learner do first?",
                     "Underline the instruction words and identify what is being asked", "Choose the longest option", "Skip the context completely", "Answer before reading all the information",
                     "Understanding the instruction and context helps learners answer accurately."),
                item("Feedback use", f"A tutor gives feedback after a {name} activity. Which response shows good learning behaviour?",
                     "Use the feedback to redo the incorrect parts and improve the method", "Ignore the feedback if the mark is low", "Only look at the mark", "Delete the activity",
                     "Feedback supports improvement when learners act on it."),
                item("Exam preparation", f"Which revision plan best supports success in {grade_text} {name}?",
                     "Short repeated revision sessions with practice questions and corrections", "One rushed session the night before", "Reading notes once without practice", "Only studying topics already mastered",
                     "Regular revision with practice and correction supports long-term understanding."),
            ]

