    if not existing_game_version or existing_game_version["value"] != GAME_QUESTION_BANK_VERSION:
        # Archive only EBTA system starter questions. Tutor-created questions are preserved.
        cur.execute("""
            UPDATE learning_game_questions
            SET status='ARCHIVED',
                updated_at=?
            WHERE created_by_tutor_id IS NULL
              AND status='ACTIVE'
        """, (now_utc_iso(),))

        if existing_game_version:
            cur.execute("""
                UPDATE settings
                SET value=?
                WHERE key='learning_games_question_bank_version'
            """, (GAME_QUESTION_BANK_VERSION,))
        else:
            cur.execute("""
                INSERT INTO settings(key,value)
                VALUES(?,?)
            """, ("learning_games_question_bank_version", GAME_QUESTION_BANK_VERSION))


    cur.execute("SELECT id, name, grade FROM subjects ORDER BY id")
    all_game_subjects = cur.fetchall()

    game_seed_types = ["Speed Quiz", "Match the Concept", "Boss Battle", "Career Quest"]
    game_seed_difficulties = ["Easy", "Medium", "Hard"]

    for game_subject in all_game_subjects:
        subject_id = game_subject["id"]
        subject_name = game_subject["name"]
        subject_grade = game_subject["grade"]

        for seed_game_type in game_seed_types:
            for seed_difficulty in game_seed_difficulties:
                cur.execute("""
                    SELECT COUNT(*) AS c
                    FROM learning_game_questions
                    WHERE subject_id=?
                      AND grade=?
                      AND game_type=?
                      AND difficulty=?
                      AND status='ACTIVE'
                """, (subject_id, subject_grade, seed_game_type, seed_difficulty))

                existing_count = cur.fetchone()["c"] or 0

                if existing_count > 0:
                    continue

                game_questions = starter_questions_for_subject(
                    subject_name,
                    subject_grade,
                    seed_game_type,
                    seed_difficulty
                )

                for topic, question_text, options, correct_index, explanation, points in game_questions:
                    cur.execute("""
                        INSERT INTO learning_game_questions(
                            subject_id,
                            grade,
                            topic,
                            game_type,
                            difficulty,
                            question_text,
                            options_json,
                            correct_index,
                            explanation,
                            points,
                            created_by_tutor_id,
                            status,
                            created_at,
                            updated_at
                        )
                        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                    """, (
                        subject_id,
                        subject_grade,
                        topic,
                        seed_game_type,
                        seed_difficulty,
                        question_text,
                        json.dumps(options),
                        correct_index,
                        explanation,
                        points,
                        None,
                        "ACTIVE",
                        now_utc_iso(),
                        now_utc_iso()
                    ))

