def get_student_active_subjects(conn, student_id):
    """
    Returns active subjects for a learner based on the learner's selected month.
    """
    month = get_active_month('student') if session.get('student_id') else get_setting("current_month")

    cur = conn.cursor()
    cur.execute("""
        SELECT DISTINCT
            s.id,
            s.name,
            s.grade
        FROM enrollments e
        JOIN subjects s ON s.id=e.subject_id
        WHERE e.student_id=?
          AND e.month=?
          AND e.status='ACTIVE'
        ORDER BY CAST(REPLACE(s.grade,'G','') AS INTEGER), s.name
    """, (student_id, month))

    return cur.fetchall()


def seconds_to_game_time(seconds):
    try:
        seconds = int(seconds or 0)
    except Exception:
        seconds = 0
    minutes = seconds // 60
    seconds = seconds % 60
    return f"{minutes}m {seconds}s"

def grade_label(g): return g.replace("G","Grade ")

def short_display_name(full_name, max_len=18):
    """
    Shortens long learner names for tables.
    Example:
    'Ahlumile Mathongo' -> 'Ahlumile M.'
    'NYAMUFWIIMAKHADO@GMAIL.COM' -> 'NYAMUFWIIMAKHADO...'
    """

    full_name = str(full_name or "Learner").strip()

    if not full_name:
        return "Learner"

    # If it looks like an email or one very long word, use dots
    if "@" in full_name or len(full_name.split()) == 1:
        return full_name if len(full_name) <= max_len else full_name[:max_len - 3] + "..."

    parts = full_name.split()

    first_name = parts[0]
    initials = " ".join([p[0].upper() + "." for p in parts[1:3] if p])

    shortened = f"{first_name} {initials}".strip()

    if len(shortened) > max_len:
        shortened = shortened[:max_len - 3] + "..."

    return shortened

def fee_for_grade(g):
    """
    EBTA subject fee based on grade.
    Adjust these amounts here if prices change later.
    """
    if g == "G13":
        return 350
    if g == "G12":
        return 250
    return 200


def generate_short_code(prefix="EBTA", size=6):
    """
    Generates a short readable code.
    Example: D50-K7P9QW
    """
    alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"
    return prefix + "-" + "".join(secrets.choice(alphabet) for _ in range(size))


def ensure_student_referral_code(conn, student_id):
    """
    Every student must have one permanent referral code.
    """
    cur = conn.cursor()

    cur.execute("""
        SELECT referral_code
        FROM students
        WHERE id=?
        LIMIT 1
    """, (student_id,))

    row = cur.fetchone()

    if row and row["referral_code"]:
        return row["referral_code"]

    while True:
        code = generate_short_code("REF", 6)

        cur.execute("""
            SELECT id
            FROM students
            WHERE referral_code=?
            LIMIT 1
        """, (code,))

        if not cur.fetchone():
            break

    cur.execute("""
        UPDATE students
        SET referral_code=?
        WHERE id=?
    """, (code, student_id))

    return code


