def tutor_can_view_student(tutor_id, student_id):
    """
    Tutor may only view students enrolled in their assigned subjects.
    """
    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT 1
        FROM enrollments e
        JOIN tutor_subjects ts ON ts.subject_id = e.subject_id
        WHERE ts.tutor_id=?
          AND e.student_id=?
          AND e.status='ACTIVE'
        LIMIT 1
    """, (tutor_id, student_id))

    allowed = cur.fetchone() is not None

    conn.close()
    return allowed


