def b64url_encode(b): return base64.urlsafe_b64encode(b).decode('ascii').rstrip('=')
def b64url_decode(s):
    pad = '=' * (-len(s)%4)
    return base64.urlsafe_b64decode(s+pad)

def month_last_day(year:int, month:int) -> int:
    return calendar.monthrange(year, month)[1]

def rating_window_open(current_month: str) -> bool:
    """
    Rating window:
    Opens on the 24th of the selected month.
    Closes on the 5th of the following month.

    Example:
    2026-05 ratings open from 24 May 2026 to 5 June 2026.
    """
    try:
        y, m = map(int, current_month.split("-")[:2])
    except Exception:
        return False

    today = datetime.datetime.now(ZoneInfo("Africa/Johannesburg")).date()

    start_date = datetime.date(y, m, 24)

    if m == 12:
        end_date = datetime.date(y + 1, 1, 5)
    else:
        end_date = datetime.date(y, m + 1, 5)

    return start_date <= today <= end_date
    
def rating_window_label(current_month: str) -> str:
    """
    Shows the rating period in a friendly format.
    Example: 24 May 2026 to 5 June 2026.
    """
    try:
        y, m = map(int, current_month.split("-")[:2])
    except Exception:
        return "24th to the 5th of the next month"

    start_date = datetime.date(y, m, 24)

    if m == 12:
        end_date = datetime.date(y + 1, 1, 5)
    else:
        end_date = datetime.date(y, m + 1, 5)

    return f"{start_date.strftime('%d %b %Y')} to {end_date.strftime('%d %b %Y')}"



def leadership_reviews_ratings_data(month, search_text=""):
    """
    Combined monthly reviews/ratings used by High Admin, CAO and CEO.

    Sources:
    - Students -> class/subject ratings
    - Students -> general EBTA reviews and improvement suggestions
    - Tutors -> ratings of Tutor Managers
    - Tutor Managers -> tutor ratings captured in the weekly tracker
    """
    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT
            lr.id,
            lr.student_id,
            st.full_name AS student_name,
            st.grade AS student_grade,
            sub.name AS subject_name,
            sub.grade AS subject_grade,
            lr.rating,
            lr.comment,
            lr.created_at,
            COALESCE(
                GROUP_CONCAT(
                    DISTINCT t.full_name
                ),
                'Unassigned'
            ) AS tutor_names
        FROM lesson_ratings lr

        JOIN students st
          ON st.id=lr.student_id

        JOIN subjects sub
          ON sub.id=lr.subject_id

        LEFT JOIN tutor_subjects ts
          ON ts.subject_id=lr.subject_id

        LEFT JOIN tutors t
          ON t.id=ts.tutor_id
         AND COALESCE(t.is_active,1)=1
         AND t.deleted_at IS NULL

        WHERE lr.month=?

        GROUP BY lr.id

        ORDER BY lr.created_at DESC
    """, (
        month,
    ))

    student_class_ratings = [
        dict(row)
        for row in cur.fetchall()
    ]

    cur.execute("""
        SELECT
            ser.id,
            ser.student_id,
            st.full_name AS student_name,
            st.grade AS student_grade,
            ser.overall_rating,
            ser.review,
            ser.suggestion,
            ser.created_at,
            ser.updated_at
        FROM student_ebta_reviews ser

        JOIN students st
          ON st.id=ser.student_id

        WHERE ser.month=?

        ORDER BY
            COALESCE(
                ser.updated_at,
                ser.created_at
            ) DESC
    """, (
        month,
    ))

    student_ebta_reviews = [
        dict(row)
        for row in cur.fetchall()
    ]

    cur.execute("""
        SELECT
            tmr.id,
            tmr.rating,
            tmr.comment,
            tmr.created_at,
            tmr.updated_at,

            t.id AS tutor_id,
            t.full_name AS tutor_name,

            tm.id AS manager_id,
            tm.full_name AS manager_name

        FROM tutor_manager_ratings tmr

        JOIN tutors t
          ON t.id=tmr.tutor_id

        JOIN tutor_managers tm
          ON tm.id=tmr.manager_id

        WHERE tmr.month=?

        ORDER BY
            COALESCE(
                tmr.updated_at,
                tmr.created_at
            ) DESC
    """, (
        month,
    ))

    tutor_to_manager_ratings = [
        dict(row)
        for row in cur.fetchall()
    ]

    cur.execute("""
        SELECT
            tw.id,
            tw.session_date,
            tw.subject,
            tw.grade,
            tw.manager_rating AS rating,
            tw.manager_comments AS comment,
            tw.created_at,

            t.id AS tutor_id,
            t.full_name AS tutor_name,

            tm.id AS manager_id,
            tm.full_name AS manager_name

        FROM tutor_weekly_tracker tw

        JOIN tutors t
          ON t.id=tw.tutor_id

        LEFT JOIN tutor_managers tm
          ON tm.id=tw.manager_id

        WHERE tw.manager_rating IS NOT NULL
          AND TRIM(
                CAST(
                    tw.manager_rating
                    AS TEXT
                )
              ) <> ''
          AND substr(
                COALESCE(
                    NULLIF(
                        TRIM(
                            tw.session_date
                        ),
                        ''
                    ),
                    tw.created_at
                ),
                1,
                7
              )=?

        ORDER BY
            tw.session_date DESC,
            tw.created_at DESC
    """, (
        month,
    ))

    manager_to_tutor_ratings = [
        dict(row)
        for row in cur.fetchall()
    ]

    conn.close()

    q = str(
        search_text
        or ""
    ).strip().lower()

    if q:
        def row_matches(row):
            return q in " ".join(
                str(value or "")
                for value in row.values()
            ).lower()

        student_class_ratings = [
            row
            for row in student_class_ratings
            if row_matches(
                row
            )
        ]

        student_ebta_reviews = [
            row
            for row in student_ebta_reviews
            if row_matches(
                row
            )
        ]

        tutor_to_manager_ratings = [
            row
            for row in tutor_to_manager_ratings
            if row_matches(
                row
            )
        ]

        manager_to_tutor_ratings = [
            row
            for row in manager_to_tutor_ratings
            if row_matches(
                row
            )
        ]

    def average(rows, key="rating"):
        values = []

        for row in rows:
            raw = row.get(
                key
            )

            if raw in (
                None,
                ""
            ):
                continue

            try:
                values.append(
                    float(
                        raw
                    )
                )
            except Exception:
                continue

        if not values:
            return None

        return round(
            sum(values)
            / len(values),
            1
        )

    return {
        "month": month,
        "student_class_ratings": student_class_ratings,
        "student_ebta_reviews": student_ebta_reviews,
        "tutor_to_manager_ratings": tutor_to_manager_ratings,
        "manager_to_tutor_ratings": manager_to_tutor_ratings,

        "student_class_avg": average(
            student_class_ratings
        ),

        "student_ebta_avg": average(
            student_ebta_reviews,
            "overall_rating"
        ),

        "tutor_manager_avg": average(
            tutor_to_manager_ratings
        ),

        "manager_tutor_avg": average(
            manager_to_tutor_ratings
        ),
    }


