def enrollment_exists(conn, student_id, subject_id, month):
    cur = conn.cursor()
    cur.execute(
        """
        SELECT 1 FROM enrollments
        WHERE student_id=? AND subject_id=? AND month=?
        LIMIT 1
        """,
        (student_id, subject_id, month)
    )
    return cur.fetchone() is not None
    
    
    
def is_first_time_student(conn, student_id):
    """
    Returns True if the student has no previous enrollment records.
    This is used to make referral points count for new students only.
    """
    cur = conn.cursor()

    cur.execute("""
        SELECT COUNT(*) AS c
        FROM enrollments
        WHERE student_id=?
    """, (student_id,))

    row = cur.fetchone()

    return (row["c"] or 0) == 0


def pretty_month_label(month_str: str) -> str:
    """Convert 'YYYY-MM' to 'Month YYYY' (e.g., '2025-10' -> 'October 2025')."""
    try:
        y, m = map(int, month_str.split('-')[:2])
        return datetime.date(y, m, 1).strftime('%B %Y')
    except Exception:
        return month_str
        
        
def normalize_enrollment_month_count(value):
    """
    Keeps parent-selected enrollment duration safe.
    The portal currently allows 1 to 12 months in one enrolment period.
    """
    try:
        n = int(value)
    except Exception:
        n = 1

    if n < 1:
        n = 1
    if n > 12:
        n = 12

    return n


def add_months_to_ym(month_str, offset=0):
    """Add months to a YYYY-MM value and return YYYY-MM."""
    try:
        y, m = map(int, str(month_str).split('-')[:2])
    except Exception:
        base = get_setting('current_month', datetime.date.today().strftime('%Y-%m'))
        y, m = map(int, str(base).split('-')[:2])

    absolute = (y * 12 + (m - 1)) + int(offset or 0)
    new_y = absolute // 12
    new_m = (absolute % 12) + 1

    return f"{new_y:04d}-{new_m:02d}"


def enrollment_month_sequence(start_month=None, month_count=1):
    """Return consecutive enrolment months from the selected start month."""
    if not start_month:
        start_month = get_setting('current_month', datetime.date.today().strftime('%Y-%m'))

    count = normalize_enrollment_month_count(month_count)

    return [add_months_to_ym(start_month, i) for i in range(count)]


def allowed_enrollment_start_months(base_month=None, limit=12):
    """Start months parents can select on the public enrolment form."""
    if not base_month:
        base_month = get_setting('current_month', datetime.date.today().strftime('%Y-%m'))

    try:
        limit = int(limit)
    except Exception:
        limit = 12

    limit = max(1, min(limit, 12))

    return enrollment_month_sequence(base_month, limit)


def active_enrollment_period_summary(conn, student_id, subject_id=None, from_month=None):
    """
    Summarises current/future ACTIVE enrolment months only.
    This ignores old history so staff can quickly see when a learner's paid period ends.
    """
    if not from_month:
        from_month = get_setting('current_month', datetime.date.today().strftime('%Y-%m'))

    cur = conn.cursor()
    params = [student_id, from_month]
    subject_filter = ""

    if subject_id:
        subject_filter = "AND subject_id=?"
        params.append(subject_id)

    cur.execute(f"""
        SELECT DISTINCT month
        FROM enrollments
        WHERE student_id=?
          AND UPPER(status)='ACTIVE'
          AND month>=?
          {subject_filter}
        ORDER BY month
    """, params)

    months = [r["month"] for r in cur.fetchall()]

    return {
        "months": months,
        "count": len(months),
        "start_month": months[0] if months else None,
        "end_month": months[-1] if months else None,
    }


def active_enrollment_period_badge(conn, student_id, subject_id=None, from_month=None):
    summary = active_enrollment_period_summary(conn, student_id, subject_id, from_month)

    if summary["count"] <= 0:
        return "<span class='mini muted'>No active current/future months</span>"

    months_text = ", ".join(pretty_month_label(m) for m in summary["months"][:6])
    if summary["count"] > 6:
        months_text += f" + {summary['count'] - 6} more"

    return f"""
    <div>
        <span class="chip active">{summary['count']} active month(s)</span>
        <div class="mini muted" style="margin-top:4px;line-height:1.45">
            Until: <strong>{pretty_month_label(summary['end_month'])}</strong><br>
            {escape(months_text)}
        </div>
    </div>
    """


def active_enrollment_period_badge_for_student_subject(student_id, subject_id=None, from_month=None):
    conn = get_db()
    try:
        return active_enrollment_period_badge(conn, student_id, subject_id, from_month)
    finally:
        conn.close()


def student_active_period_card(conn, student_id, from_month=None):
    """Card for the learner portal showing active current/future months."""
    if not from_month:
        from_month = get_setting('current_month', datetime.date.today().strftime('%Y-%m'))

    cur = conn.cursor()
    cur.execute("""
        SELECT
            e.month,
            COUNT(DISTINCT e.subject_id) AS subject_count
        FROM enrollments e
        WHERE e.student_id=?
          AND UPPER(e.status)='ACTIVE'
          AND e.month>=?
        GROUP BY e.month
        ORDER BY e.month
    """, (student_id, from_month))

    rows = cur.fetchall()

    if not rows:
        return ""

    month_chips = "".join(
        f"<span class='chip active'>{pretty_month_label(r['month'])} • {int(r['subject_count'] or 0)} subject(s)</span>"
        for r in rows
    )

    end_month = rows[-1]["month"]

    return f"""
    <div class="card soft" style="border-left:5px solid #1b5e20;margin-bottom:14px">
        <h3 style="margin-bottom:6px">My Active Enrolment Period</h3>
        <p class="mini muted" style="margin-bottom:10px">
            You are currently active until <strong>{pretty_month_label(end_month)}</strong>.
            These are your current and upcoming paid months.
        </p>
        <div style="display:flex;gap:8px;flex-wrap:wrap">
            {month_chips}
        </div>
    </div>
    """
        
        
TERMS = [
    ("T1", "Term 1"),
    ("T2", "Term 2"),
    ("T3", "Term 3"),
    ("T4", "Term 4"),
]


def make_term_key(year, term_code):
    """
    Stores term marks in the existing aqm_student_marks.month column.
    Example: 2026 + T1 = 2026-T1
    """
    year = str(year).strip()
    term_code = str(term_code).strip().upper()

    if term_code not in ["T1", "T2", "T3", "T4"]:
        term_code = "T1"

    if not year.isdigit():
        year = str(datetime.datetime.now(ZoneInfo("Africa/Johannesburg")).year)

    return f"{year}-{term_code}"


def split_term_key(term_key):
    """
    Converts 2026-T1 into year=2026 and term_code=T1.
    """
    try:
        year, term_code = str(term_key).split("-", 1)
        term_code = term_code.upper()
        if term_code not in ["T1", "T2", "T3", "T4"]:
            term_code = "T1"
        return year, term_code
    except Exception:
        return str(datetime.datetime.now(ZoneInfo("Africa/Johannesburg")).year), "T1"


def term_label(term_key):
    """
    Converts 2026-T1 into 2026 Term 1.
    """
    year, term_code = split_term_key(term_key)

    labels = {
        "T1": "Term 1",
        "T2": "Term 2",
        "T3": "Term 3",
        "T4": "Term 4",
    }

    return f"{year} {labels.get(term_code, 'Term 1')}"

        
def record_material_view(material_id, student_id):
    conn = get_db()
    cur = conn.cursor()

    now = now_utc_iso()
    ip = request.remote_addr
    ua = request.headers.get("User-Agent", "")[:300]

    cur.execute("""
        INSERT INTO material_views(
            material_id,
            student_id,
            first_viewed_at,
            last_viewed_at,
            view_count,
            ip_address,
            user_agent
        )
        VALUES(?,?,?,?,?,?,?)
        ON CONFLICT(material_id, student_id)
        DO UPDATE SET
            last_viewed_at = excluded.last_viewed_at,
            view_count = material_views.view_count + 1,
            ip_address = excluded.ip_address,
            user_agent = excluded.user_agent
    """, (
        material_id,
        student_id,
        now,
        now,
        1,
        ip,
        ua
    ))

    conn.commit()
    conn.close()


def expected_class_dates_for_subject(cur, subject_id, tutor_id, month, expected_classes):
    """
    Returns expected class dates for a subject in a month based on the tutor's active session day.
    EBTA rule:
    Grade 8 to Grade 12 = 4 classes per month
    Grade 13 = 6 classes per month
    """

    try:
        year, month_num = map(int, month.split("-"))
    except:
        return []

    cur.execute("""
        SELECT day_of_week
        FROM sessions
        WHERE subject_id = ?
          AND tutor_id = ?
          AND active = 1
        ORDER BY day_of_week, start_time
    """, (subject_id, tutor_id))

    session_rows = cur.fetchall()

    if not session_rows:
        return []

    session_days = {r["day_of_week"] for r in session_rows}

    last_day = calendar.monthrange(year, month_num)[1]
    expected_dates = []

    for day in range(1, last_day + 1):
        d = datetime.date(year, month_num, day)

        # Python weekday: Monday=0, Sunday=6
        # Your system DOW: Sunday=0, Monday=1, ..., Saturday=6
        system_day = (d.weekday() + 1) % 7

        if system_day in session_days:
            expected_dates.append(d.isoformat())

    # Very important:
    # Only return the number of dates allowed by EBTA monthly rule.
    return expected_dates[:expected_classes]



# ===================== Notifications (Email & SMS) ==============
def send_email_notification(to_email: str, subject: str, body: str):
    # Best-effort email sender.
    # Uses SMTP settings from environment if configured, otherwise logs into the messages table.
    # Env vars for real sending:
    #   EBTA_SMTP_HOST, EBTA_SMTP_PORT, EBTA_SMTP_USER, EBTA_SMTP_PASS, EBTA_SMTP_FROM (optional, falls back to user).
    if not to_email:
        return
    host = os.environ.get("EBTA_SMTP_HOST")
    port = int(os.environ.get("EBTA_SMTP_PORT", "587"))
    user = os.environ.get("EBTA_SMTP_USER")
    pwd = os.environ.get("EBTA_SMTP_PASS")
    sender = os.environ.get("EBTA_SMTP_FROM", user)

    # If SMTP is not configured, just log the outgoing email in the admin Messages page
    if not (host and user and pwd and sender):
        try:
            conn = get_db()
            cur = conn.cursor()
            payload = f"TO:{to_email} | SUBJECT:{subject} | BODY:{body}"
            cur.execute(
                "INSERT INTO messages(kind,payload,created_at,resolved) VALUES(?,?,?,0)",
                ("email_log", payload, now_utc_iso()),
            )
            conn.commit()
            conn.close()
        except Exception:
            pass
        return

    try:
        import smtplib
        from email.message import EmailMessage



        msg = EmailMessage()
        msg["Subject"] = subject
        msg["From"] = sender
        msg["To"] = to_email
        msg.set_content(body)

        with smtplib.SMTP(host, port, timeout=30) as s:
            s.ehlo()
            s.starttls()
            s.ehlo()
            s.login(user, pwd)
            s.send_message(msg)
    except Exception as e:
        # Log error so admin can see what went wrong
        try:
            conn = get_db()
            cur = conn.cursor()
            payload = f"TO:{to_email} | SUBJECT:{subject} | ERROR:{e}"
            cur.execute(
                "INSERT INTO messages(kind,payload,created_at,resolved) VALUES(?,?,?,0)",
                ("email_error", payload, now_utc_iso()),
            )
            conn.commit()
            conn.close()
        except Exception:
            pass


def send_sms_notification(to_phone: str, body: str):
    # Best-effort SMS sender with automatic SA phone normalization

    if not to_phone:
        return

    # --- Normalize South African phone number ---
    phone = str(to_phone).strip()

    # remove spaces, dashes, brackets
    phone = phone.replace(" ", "").replace("-", "").replace("(", "").replace(")", "")

    # convert 0821234567 → +27821234567
    if phone.startswith("0") and len(phone) == 10:
        phone = "+27" + phone[1:]

    # convert 27821234567 → +27821234567
    elif phone.startswith("27") and len(phone) == 11:
        phone = "+" + phone

    # already correct format
    elif phone.startswith("+"):
        pass

    else:
        # invalid format → log error
        try:
            conn = get_db()
            cur = conn.cursor()
            payload = f"INVALID_PHONE:{to_phone}"
            cur.execute(
                "INSERT INTO messages(kind,payload,created_at,resolved) VALUES(?,?,?,0)",
                ("sms_error", payload, now_utc_iso()),
            )
            conn.commit()
            conn.close()
        except:
            pass
        return  

    to_phone = phone

    account_sid = os.environ.get("EBTA_TWILIO_SID")
    auth_token = os.environ.get("EBTA_TWILIO_TOKEN")
    from_number = os.environ.get("EBTA_TWILIO_FROM")

    # If Twilio not configured, log SMS
    if not (account_sid and auth_token and from_number):
        try:
            conn = get_db()
            cur = conn.cursor()
            payload = f"TO:{to_phone} | BODY:{body}"
            cur.execute(
                "INSERT INTO messages(kind,payload,created_at,resolved) VALUES(?,?,?,0)",
                ("sms_log", payload, now_utc_iso()),
            )
            conn.commit()
            conn.close()
        except:
            pass
        return

    # Send via Twilio
    try:
        from twilio.rest import Client

        client = Client(account_sid, auth_token)

        client.messages.create(
            from_=from_number,
            to=to_phone,
            body=body
        )

        # optional success log
        conn = get_db()
        cur = conn.cursor()
        payload = f"SENT TO:{to_phone}"
        cur.execute(
            "INSERT INTO messages(kind,payload,created_at,resolved) VALUES(?,?,?,0)",
            ("sms_sent", payload, now_utc_iso()),
        )
        conn.commit()
        conn.close()

    except Exception as e:
        try:
            conn = get_db()
            cur = conn.cursor()
            payload = f"TO:{to_phone} | ERROR:{e}"
            cur.execute(
                "INSERT INTO messages(kind,payload,created_at,resolved) VALUES(?,?,?,0)",
                ("sms_error", payload, now_utc_iso()),
            )
            conn.commit()
            conn.close()
        except:
            pass

