@app.post('/student/assignment/<int:mid>/submit')
def student_submit_assignment(mid:int):

    r = require_student()
    if r:
        return r

    sid = is_student()

    conn = get_db()
    cur = conn.cursor()

    # Get assignment
    cur.execute("""
        SELECT id, subject_id, month, open_date, due_date,
               is_assignment, kind
        FROM materials
        WHERE id=?
    """, (mid,))

    m = cur.fetchone()

    if not m or (m["kind"] != "assignment" and m["is_assignment"] != 1):
        conn.close()
        return page("Error", card_msg("Invalid assignment."))

    assignment_month = m["month"]

    # Check student was ACTIVE in that assignment month
    cur.execute("""
        SELECT 1
        FROM enrollments
        WHERE student_id=?
          AND subject_id=?
          AND month=?
          AND status='ACTIVE'
        LIMIT 1
    """, (sid, m["subject_id"], assignment_month))

    enrolled = cur.fetchone()

    if not enrolled:
        conn.close()
        return page("Error", card_msg(
            f"You were not enrolled for this subject in {pretty_month_label(assignment_month)}."
        ))

    # Check open date
    if m["open_date"]:
        try:
            open_value = datetime.datetime.strptime(m["open_date"], "%Y-%m-%d").date()
            if portal_today_date() < open_value:
                conn.close()
                return page("Not Open Yet", card_msg("This assignment is not open yet."))
        except Exception:
            pass

    # Check due date
    if m["due_date"]:
        try:
            due = datetime.datetime.strptime(m["due_date"], "%Y-%m-%d").date()

            if portal_today_date() > due:
                conn.close()
                return page("Closed", card_msg("Submission window has closed."))

        except Exception:
            pass

    files = request.files.getlist("file")

    path, file_count = save_uploaded_files_as_single_file(
        files=files,
        target_dir=SUBMISSIONS_DIR,
        prefix=f"student_{sid}_assignment_{mid}",
        public_url_prefix=None
    )

    if not path:
        conn.close()
        return page("Error", card_msg("Please select at least one file."))

    now = now_utc_iso()

    # Remove old submitted file if the learner is replacing an existing submission
    cur.execute("""
        SELECT file_path
        FROM submissions
        WHERE material_id=? AND student_id=?
    """, (mid, sid))

    old = cur.fetchone()

    if old and old["file_path"]:
        old_path = old["file_path"]

        if old_path.startswith("/submission-files/"):
            old_path = str(SUBMISSIONS_DIR / os.path.basename(old_path))

        try:
            if os.path.exists(old_path):
                os.remove(old_path)
        except Exception as e:
            print("Old submission delete error:", e)

    cur.execute("""
        INSERT OR REPLACE INTO submissions
        (material_id, student_id, file_path, submitted_at)
        VALUES (?, ?, ?, ?)
    """, (mid, sid, path, now))

    conn.commit()
    conn.close()

    if file_count > 1:
        return page("Submitted", card_msg(f"Assignment submitted successfully. {file_count} files were saved as one ZIP file."))

    return page("Submitted", card_msg("Assignment submitted successfully."))

# Student → Tutor message
@app.post('/student/message')
def student_send_message():
    r=require_student()
    if r: return r
    sid=is_student()
    combo=request.form.get('combo','')
    body=request.form.get('body','').strip()
    if not (combo and body): return page("Error", card_msg("Choose a tutor and write a message."))
    try:
        tutor_id_str, subject_id_str = combo.split('|',1)
        tutor_id=int(tutor_id_str); subject_id=int(subject_id_str)
    except Exception:
        return page("Error", card_msg("Bad selection."))
    conn=get_db(); cur=conn.cursor()
    # verify student is ACTIVE in subject and tutor teaches that subject
    month=get_setting('current_month')
    cur.execute("SELECT 1 FROM enrollments WHERE student_id=? AND subject_id=? AND month=? AND status='ACTIVE'", (sid,subject_id,month))
    if not cur.fetchone():
        conn.close(); return page("Error", card_msg("You are not ACTIVE in that subject."))
    cur.execute("SELECT 1 FROM tutor_subjects WHERE tutor_id=? AND subject_id=?", (tutor_id,subject_id))
    if not cur.fetchone():
        conn.close(); return page("Error", card_msg("Tutor not assigned to that subject."))
    cur.execute("INSERT INTO direct_messages(from_role,from_id,to_role,to_id,subject_id,body,created_at) VALUES('student',?,?,?,?,?,?)",
                (sid,'tutor',tutor_id,subject_id,body,now_utc_iso()))
    conn.commit(); conn.close()
    return redirect(url_for('student_home'))
    
    
@app.get("/student/messages/thread")
def student_message_thread():

    r = require_student()
    if r: return r

    sid = is_student()

    tutor_id = request.args.get("tutor_id")
    subject_id = request.args.get("subject_id")

    if not tutor_id or not subject_id:
        return ""

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT *
        FROM direct_messages
        WHERE subject_id=?
        AND (
            (from_role='student' AND from_id=? AND to_role='tutor' AND to_id=?)
            OR
            (from_role='tutor' AND from_id=? AND to_role='student' AND to_id=?)
        )
        ORDER BY created_at ASC
    """, (subject_id, sid, tutor_id, tutor_id, sid))

    msgs = cur.fetchall()

    conn.close()

    html = ""

    for m in msgs:

        cls = "me" if m["from_role"] == "student" else "them"

        time = m["created_at"][:16].replace("T"," ")

        html += f"""
        <div class="bubble {cls}">
            {m['body']}
            <div class="time">{time}</div>
        </div>
        """

    return html


# Student: submit monthly ratings
@app.post('/student/ratings')
def student_submit_ratings():
    r = require_student()
    if r:
        return r

    sid = is_student()

    month = (
        request.form.get(
            "month",
            ""
        ).strip()
        or get_active_month(
            "student"
        )
        or get_setting(
            "current_month"
        )
    )

    if not rating_window_open(
        month
    ):
        return page(
            "Closed",
            card_msg(
                f"The rating window for {pretty_month_label(month)} is not open. "
                f"It opens from {rating_window_label(month)}."
            )
        )

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT subject_id
        FROM enrollments
        WHERE student_id=?
          AND month=?
          AND status='ACTIVE'
    """, (
        sid,
        month
    ))

    subids = [
        row["subject_id"]
        for row in cur.fetchall()
    ]

    now = now_utc_iso()

    for subid in subids:
        rkey = f"rating_{subid}"
        ckey = f"comment_{subid}"

        raw = request.form.get(
            rkey,
            ""
        ).strip()

        if not raw:
            continue

        try:
            rating = int(
                raw
            )
        except Exception:
            continue

        if rating < 1 or rating > 5:
            continue

        comment = (
            request.form.get(
                ckey,
                ""
            ).strip()
            or None
        )

        cur.execute("""
            INSERT INTO lesson_ratings(
                student_id,
                subject_id,
                month,
                rating,
                comment,
                created_at
            )
            VALUES(?,?,?,?,?,?)
            ON CONFLICT(
                student_id,
                subject_id,
                month
            )
            DO UPDATE SET
                rating=excluded.rating,
                comment=excluded.comment,
                created_at=excluded.created_at
        """, (
            sid,
            subid,
            month,
            rating,
            comment,
            now
        ))

    # Optional overall EBTA review.
    ebta_rating_raw = request.form.get(
        "ebta_overall_rating",
        ""
    ).strip()

    ebta_review = request.form.get(
        "ebta_review",
        ""
    ).strip()

    ebta_suggestion = request.form.get(
        "ebta_suggestion",
        ""
    ).strip()

    ebta_rating = None

    if ebta_rating_raw:
        try:
            parsed_rating = int(
                ebta_rating_raw
            )

            if 1 <= parsed_rating <= 5:
                ebta_rating = parsed_rating

        except Exception:
            ebta_rating = None

    if (
        ebta_rating is not None
        or ebta_review
        or ebta_suggestion
    ):
        cur.execute("""
            INSERT INTO student_ebta_reviews(
                student_id,
                month,
                overall_rating,
                review,
                suggestion,
                created_at,
                updated_at
            )
            VALUES(?,?,?,?,?,?,?)
            ON CONFLICT(
                student_id,
                month
            )
            DO UPDATE SET
                overall_rating=excluded.overall_rating,
                review=excluded.review,
                suggestion=excluded.suggestion,
                updated_at=excluded.updated_at
        """, (
            sid,
            month,
            ebta_rating,
            ebta_review or None,
            ebta_suggestion or None,
            now,
            now
        ))

    conn.commit()
    conn.close()

    return page(
        "Thanks!",
        card_msg(
            "Your ratings and feedback were saved."
        )
    )

@app.post('/student/activity/ping')
def student_activity_ping():

    r = require_student()
    if r:
        return ("", 204)

    sid = is_student()

    try:
        seconds = int(request.form.get("seconds", 0))
    except Exception:
        seconds = 0

    # Safety cap so one ping cannot add too much time
    if seconds < 0:
        seconds = 0

    if seconds > 300:
        seconds = 300

    now = datetime.datetime.now(ZoneInfo("Africa/Johannesburg"))
    today = now.date().isoformat()
    month = now.strftime("%Y-%m")

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        INSERT INTO student_portal_activity(
            student_id,
            activity_date,
            month,
            total_seconds,
            last_seen_at,
            created_at,
            updated_at
        )
        VALUES(?,?,?,?,?,?,?)
        ON CONFLICT(student_id, activity_date)
        DO UPDATE SET
            total_seconds = total_seconds + excluded.total_seconds,
            last_seen_at = excluded.last_seen_at,
            updated_at = excluded.updated_at
    """, (
        sid,
        today,
        month,
        seconds,
        now_utc_iso(),
        now_utc_iso(),
        now_utc_iso()
    ))

    conn.commit()
    conn.close()

    return ("", 204)
    
    
def percent_value(part, total):
    try:
        part = float(part or 0)
        total = float(total or 0)

        if total <= 0:
            return 0

        return round((part / total) * 100)
    except Exception:
        return 0
        

def ebta_expected_monthly_sessions_for_grade(grade):
    """
    EBTA monthly attendance-log target.

    Grade 8 to Grade 12: 4 expected sessions per month.
    Grade 13: 6 expected sessions per month.
    """
    grade = str(grade or "").strip().upper()

    if grade == "G13":
        return 6

    return 4


def ebta_expected_monthly_sessions_for_subjects(subject_rows):
    """
    Calculates the expected monthly attendance logs for a tutor
    based on their assigned subjects.

    If a tutor has:
    - one Grade 8 to 12 subject, target = 4
    - one Grade 13 subject, target = 6
    - multiple subjects, targets are added together
    """
    total = 0

    for subject in subject_rows:
        total += ebta_expected_monthly_sessions_for_grade(subject["grade"])

    return total


def student_progress_band(rate):
    rate = int(rate or 0)

    if rate >= 75:
        return "active", "On Track"

    if rate >= 50:
        return "pending", "Needs Attention"

    return "lapsed", "High Risk"


def student_progress_data(student_id, month):
    """
    Builds academic progress data for the learner for one month.
    This uses existing EBTA tables and does not change student data.
    """

    conn = get_db()
    cur = conn.cursor()

    today = datetime.datetime.now(ZoneInfo("Africa/Johannesburg")).date()
    today_iso = today.isoformat()
    next_7_iso = (today + datetime.timedelta(days=7)).isoformat()

    # Active subjects for selected month
    cur.execute("""
        SELECT
            e.subject_id,
            s.name AS subject_name,
            s.grade
        FROM enrollments e
        JOIN subjects s ON s.id=e.subject_id
        WHERE e.student_id=?
          AND e.month=?
          AND UPPER(e.status)='ACTIVE'
        ORDER BY CAST(REPLACE(s.grade,'G','') AS INTEGER), s.name
    """, (student_id, month))

    active_subjects = cur.fetchall()
    active_subject_ids = [r["subject_id"] for r in active_subjects]

    if not active_subject_ids:
        conn.close()

        return {
            "month": month,
            "active_subjects": [],
            "total_assignments": 0,
            "completed_assignments": 0,
            "pending_assignments": 0,
            "due_soon": 0,
            "overdue": 0,
            "assignment_rate": 0,
            "total_materials": 0,
            "viewed_materials": 0,
            "not_viewed_materials": 0,
            "material_view_rate": 0,
            "attendance_total": 0,
            "attendance_present": 0,
            "attendance_rate": 0,
            "reports_uploaded": 0,
            "portal_seconds": 0,
            "portal_minutes": 0,
            "portal_hours_label": "0 min",
            "subject_rows": [],
            "recommendations": ["You are not actively enrolled for this month yet."],
            "overall_rate": 0,
            "overall_status": "Not Active",
            "overall_class": "lapsed"
        }

    placeholders = ",".join("?" * len(active_subject_ids))

    # Assignments
    cur.execute(f"""
        SELECT COUNT(*) AS c
        FROM materials m
        WHERE m.subject_id IN ({placeholders})
          AND m.month LIKE ?
          AND (m.is_assignment=1 OR m.kind='assignment')
          AND (m.open_date IS NULL OR TRIM(m.open_date)='' OR m.open_date <= ?)
    """, (*active_subject_ids, month + "%", today_iso))

    total_assignments = cur.fetchone()["c"] or 0

    cur.execute(f"""
        SELECT COUNT(DISTINCT m.id) AS c
        FROM materials m
        JOIN submissions sub ON sub.material_id=m.id AND sub.student_id=?
        WHERE m.subject_id IN ({placeholders})
          AND m.month LIKE ?
          AND (m.is_assignment=1 OR m.kind='assignment')
          AND (m.open_date IS NULL OR TRIM(m.open_date)='' OR m.open_date <= ?)
    """, (student_id, *active_subject_ids, month + "%", today_iso))

    completed_assignments = cur.fetchone()["c"] or 0
    pending_assignments = max(0, total_assignments - completed_assignments)

    cur.execute(f"""
        SELECT COUNT(*) AS c
        FROM materials m
        WHERE m.subject_id IN ({placeholders})
          AND m.month LIKE ?
          AND (m.is_assignment=1 OR m.kind='assignment')
          AND (m.open_date IS NULL OR TRIM(m.open_date)='' OR m.open_date <= ?)
          AND m.due_date IS NOT NULL
          AND m.due_date >= ?
          AND m.due_date <= ?
          AND NOT EXISTS (
              SELECT 1
              FROM submissions sub
              WHERE sub.material_id=m.id
                AND sub.student_id=?
          )
    """, (*active_subject_ids, month + "%", today_iso, today_iso, next_7_iso, student_id))

    due_soon = cur.fetchone()["c"] or 0

    cur.execute(f"""
        SELECT COUNT(*) AS c
        FROM materials m
        WHERE m.subject_id IN ({placeholders})
          AND m.month LIKE ?
          AND (m.is_assignment=1 OR m.kind='assignment')
          AND (m.open_date IS NULL OR TRIM(m.open_date)='' OR m.open_date <= ?)
          AND m.due_date IS NOT NULL
          AND m.due_date < ?
          AND NOT EXISTS (
              SELECT 1
              FROM submissions sub
              WHERE sub.material_id=m.id
                AND sub.student_id=?
          )
    """, (*active_subject_ids, month + "%", today_iso, today_iso, student_id))

    overdue = cur.fetchone()["c"] or 0

    assignment_rate = percent_value(completed_assignments, total_assignments)

    # Materials viewed, excluding assignments
    cur.execute(f"""
        SELECT COUNT(*) AS c
        FROM materials m
        WHERE m.subject_id IN ({placeholders})
          AND m.month LIKE ?
          AND COALESCE(m.is_assignment,0)=0
          AND m.kind!='assignment'
    """, (*active_subject_ids, month + "%"))

    total_materials = cur.fetchone()["c"] or 0

    cur.execute(f"""
        SELECT COUNT(DISTINCT m.id) AS c
        FROM materials m
        JOIN material_views mv ON mv.material_id=m.id AND mv.student_id=?
        WHERE m.subject_id IN ({placeholders})
          AND m.month LIKE ?
          AND COALESCE(m.is_assignment,0)=0
          AND m.kind!='assignment'
    """, (student_id, *active_subject_ids, month + "%"))

    viewed_materials = cur.fetchone()["c"] or 0
    not_viewed_materials = max(0, total_materials - viewed_materials)
    material_view_rate = percent_value(viewed_materials, total_materials)

    # Attendance
    cur.execute(f"""
        SELECT COUNT(DISTINCT ats.id) AS c
        FROM attendance_sessions ats
        WHERE ats.subject_id IN ({placeholders})
          AND ats.month=?
    """, (*active_subject_ids, month))

    attendance_total = cur.fetchone()["c"] or 0

    cur.execute(f"""
        SELECT COUNT(DISTINCT ats.id) AS c
        FROM attendance_sessions ats
        JOIN attendance a
          ON a.session_id=ats.session_id
         AND a.date=ats.date
         AND a.student_id=?
        WHERE ats.subject_id IN ({placeholders})
          AND ats.month=?
    """, (student_id, *active_subject_ids, month))

    attendance_present = cur.fetchone()["c"] or 0
    attendance_rate = percent_value(attendance_present, attendance_total)

    # Reports uploaded by learner
    cur.execute("""
        SELECT COUNT(*) AS c
        FROM student_reports
        WHERE student_id=?
          AND substr(upload_date,1,7)=?
    """, (student_id, month))

    reports_uploaded = cur.fetchone()["c"] or 0

    # Portal activity, lightweight monthly sum
    cur.execute("""
        SELECT COALESCE(SUM(total_seconds),0) AS total_seconds
        FROM student_portal_activity
        WHERE student_id=?
          AND month=?
    """, (student_id, month))

    portal_seconds = int(cur.fetchone()["total_seconds"] or 0)
    portal_minutes = portal_seconds // 60

    if portal_minutes >= 60:
        portal_hours_label = f"{portal_minutes // 60}h {portal_minutes % 60}min"
    else:
        portal_hours_label = f"{portal_minutes} min"

    # Per-subject breakdown
    subject_rows = []

    for subject in active_subjects:
        subject_id = subject["subject_id"]

        cur.execute("""
            SELECT COUNT(*) AS c
            FROM materials
            WHERE subject_id=?
              AND month LIKE ?
              AND (is_assignment=1 OR kind='assignment')
              AND (open_date IS NULL OR TRIM(open_date)='' OR open_date <= ?)
        """, (subject_id, month + "%", today_iso))

        sub_total_assignments = cur.fetchone()["c"] or 0

        cur.execute("""
            SELECT COUNT(DISTINCT m.id) AS c
            FROM materials m
            JOIN submissions sub ON sub.material_id=m.id AND sub.student_id=?
            WHERE m.subject_id=?
              AND m.month LIKE ?
              AND (m.is_assignment=1 OR m.kind='assignment')
              AND (m.open_date IS NULL OR TRIM(m.open_date)='' OR m.open_date <= ?)
        """, (student_id, subject_id, month + "%", today_iso))

        sub_completed_assignments = cur.fetchone()["c"] or 0
        sub_assignment_rate = percent_value(sub_completed_assignments, sub_total_assignments)

        cur.execute("""
            SELECT COUNT(*) AS c
            FROM materials
            WHERE subject_id=?
              AND month LIKE ?
              AND COALESCE(is_assignment,0)=0
              AND kind!='assignment'
        """, (subject_id, month + "%"))

        sub_total_materials = cur.fetchone()["c"] or 0

        cur.execute("""
            SELECT COUNT(DISTINCT m.id) AS c
            FROM materials m
            JOIN material_views mv ON mv.material_id=m.id AND mv.student_id=?
            WHERE m.subject_id=?
              AND m.month LIKE ?
              AND COALESCE(m.is_assignment,0)=0
              AND m.kind!='assignment'
        """, (student_id, subject_id, month + "%"))

        sub_viewed_materials = cur.fetchone()["c"] or 0
        sub_material_rate = percent_value(sub_viewed_materials, sub_total_materials)

        cur.execute("""
            SELECT COUNT(DISTINCT ats.id) AS c
            FROM attendance_sessions ats
            WHERE ats.subject_id=?
              AND ats.month=?
        """, (subject_id, month))

        sub_attendance_total = cur.fetchone()["c"] or 0

        cur.execute("""
            SELECT COUNT(DISTINCT ats.id) AS c
            FROM attendance_sessions ats
            JOIN attendance a
              ON a.session_id=ats.session_id
             AND a.date=ats.date
             AND a.student_id=?
            WHERE ats.subject_id=?
              AND ats.month=?
        """, (student_id, subject_id, month))

        sub_attendance_present = cur.fetchone()["c"] or 0
        sub_attendance_rate = percent_value(sub_attendance_present, sub_attendance_total)

        cur.execute("""
            SELECT mark
            FROM academic_report_marks
            WHERE student_id=?
              AND subject_id=?
              AND month=?
            LIMIT 1
        """, (student_id, subject_id, month))

        report_mark_row = cur.fetchone()
        report_mark = report_mark_row["mark"] if report_mark_row else None

        cur.execute("""
            SELECT mark
            FROM aqm_student_marks
            WHERE student_id=?
              AND subject_id=?
              AND month=?
            LIMIT 1
        """, (student_id, subject_id, month))

        aqm_mark_row = cur.fetchone()
        aqm_mark = aqm_mark_row["mark"] if aqm_mark_row else None

        risk_points = 0
        focus = []

        if sub_total_assignments > 0 and sub_assignment_rate < 60:
            risk_points += 1
            focus.append("complete pending assessments")

        if sub_total_materials > 0 and sub_material_rate < 60:
            risk_points += 1
            focus.append("view learning materials")

        if sub_attendance_total > 0 and sub_attendance_rate < 60:
            risk_points += 1
            focus.append("improve attendance")

        available_marks = [m for m in [report_mark, aqm_mark] if m is not None]

        if available_marks:
            avg_mark = round(sum(available_marks) / len(available_marks))
            if avg_mark < 50:
                risk_points += 1
                focus.append("ask for help with marks below 50%")
        else:
            avg_mark = None

        if risk_points >= 2:
            risk_level = "HIGH"
        elif risk_points == 1:
            risk_level = "MEDIUM"
        else:
            risk_level = "LOW"

        subject_rows.append({
            "subject_id": subject_id,
            "subject_name": subject["subject_name"],
            "grade": subject["grade"],
            "assignment_rate": sub_assignment_rate,
            "material_rate": sub_material_rate,
            "attendance_rate": sub_attendance_rate,
            "report_mark": report_mark,
            "aqm_mark": aqm_mark,
            "avg_mark": avg_mark,
            "risk_level": risk_level,
            "focus": ", ".join(focus) if focus else "keep going"
        })

    # Recommendations
    recommendations = []

    if pending_assignments > 0:
        recommendations.append(f"Complete {pending_assignments} pending assessment(s).")

    if due_soon > 0:
        recommendations.append(f"{due_soon} assessment(s) are due soon. Submit before the deadline.")

    if overdue > 0:
        recommendations.append(f"{overdue} assessment(s) are overdue. Ask your tutor if late submission is still possible.")

    if not_viewed_materials > 0:
        recommendations.append(f"View {not_viewed_materials} learning material(s) not yet opened.")

    if attendance_total > 0 and attendance_rate < 75:
        recommendations.append("Attend more live sessions to improve your attendance rate.")

    if reports_uploaded == 0:
        recommendations.append("Upload your latest school report so EBTA can track your academic progress.")

    high_risk_subjects = [x for x in subject_rows if x["risk_level"] == "HIGH"]

    if high_risk_subjects:
        names = ", ".join([x["subject_name"] for x in high_risk_subjects[:3]])
        recommendations.append(f"Seek clarity in: {names}.")

    if not recommendations:
        recommendations.append("You are doing well. Keep completing tasks, viewing materials and attending sessions.")

    # Overall score
    components = []

    if total_assignments > 0:
        components.append(assignment_rate)

    if total_materials > 0:
        components.append(material_view_rate)

    if attendance_total > 0:
        components.append(attendance_rate)

    if reports_uploaded > 0:
        components.append(100)
    else:
        components.append(0)

    overall_rate = round(sum(components) / len(components)) if components else 0
    overall_class, overall_status = student_progress_band(overall_rate)

    conn.close()

    return {
        "month": month,
        "active_subjects": active_subjects,
        "total_assignments": total_assignments,
        "completed_assignments": completed_assignments,
        "pending_assignments": pending_assignments,
        "due_soon": due_soon,
        "overdue": overdue,
        "assignment_rate": assignment_rate,
        "total_materials": total_materials,
        "viewed_materials": viewed_materials,
        "not_viewed_materials": not_viewed_materials,
        "material_view_rate": material_view_rate,
        "attendance_total": attendance_total,
        "attendance_present": attendance_present,
        "attendance_rate": attendance_rate,
        "reports_uploaded": reports_uploaded,
        "portal_seconds": portal_seconds,
        "portal_minutes": portal_minutes,
        "portal_hours_label": portal_hours_label,
        "subject_rows": subject_rows,
        "recommendations": recommendations,
        "overall_rate": overall_rate,
        "overall_status": overall_status,
        "overall_class": overall_class
    }
    
    
@app.get('/student/progress')
def student_academic_progress():

    r = require_student()
    if r:
        return r

    sid = is_student()
    month = get_active_month('student')

    data = student_progress_data(sid, month)

    subject_rows_html = ""
    subject_cards_html = ""

