@app.post('/tutor/profile/update')
def tutor_update_profile():

    r = require_tutor()
    if r:
        return r

    tid = is_tutor()

    full_name = request.form.get("full_name", "").strip()
    qualification = request.form.get("qualification", "").strip()
    achievements = request.form.get("achievements", "").strip()
    about = request.form.get("about", "").strip()

    if not full_name:
        return page("Missing Name", card_msg("Full name is required."))

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        UPDATE tutors
        SET full_name=?,
            qualification=?,
            achievements=?,
            about=?
        WHERE id=?
    """, (
        full_name,
        qualification,
        achievements,
        about,
        tid
    ))

    conn.commit()
    conn.close()

    session["tutor_name"] = full_name

    return redirect(url_for("tutor_profile_page"))


@app.post('/tutor/upload-profile-picture')
def tutor_upload_profile_picture():

    r = require_tutor()
    if r:
        return r

    tid = is_tutor()
    file = request.files.get("profile_picture")

    if not file or not file.filename:
        return redirect(url_for("tutor_profile_page"))

    if not is_valid_profile_picture(file.filename):
        return page("Invalid File", card_msg("Please upload a PNG, JPG, JPEG, WEBP, GIF, or BMP image."))

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT full_name
        FROM tutors
        WHERE id=?
        LIMIT 1
    """, (tid,))

    tutor = cur.fetchone()

    if not tutor:
        conn.close()
        return redirect(url_for("tutor_login"))

    ext = os.path.splitext(file.filename.lower())[1]
    safe_tutor_name = secure_name(tutor["full_name"] or "Tutor")

    tutor_folder = PROFILE_PICS_DIR / "tutors"
    tutor_folder.mkdir(parents=True, exist_ok=True)

    filename = f"{safe_tutor_name}_{tid}{ext}"
    file_path = tutor_folder / filename

    file.save(file_path)

    cur.execute("""
        UPDATE tutors
        SET profile_picture_path=?,
            profile_picture_uploaded_at=?
        WHERE id=?
    """, (str(file_path), now_utc_iso(), tid))

    conn.commit()
    conn.close()

    return redirect(url_for("tutor_profile_page"))
  

@app.get('/tutor/student-profile/<int:student_id>')
def tutor_view_student_profile(student_id):

    r = require_tutor()
    if r:
        return r

    tid = is_tutor()

    if not tutor_can_view_student(tid, student_id):
        return page("Access Denied", card_msg("You are not allowed to view this learner profile."))

    month = get_active_month("tutor")

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT
            id,
            full_name,
            phone_whatsapp,
            guardian_name,
            guardian_phone,
            email,
            grade,
            school,
            province,
            profile_picture_path,
            profile_picture_uploaded_at,
            created_at
        FROM students
        WHERE id=?
        LIMIT 1
    """, (student_id,))

    student = cur.fetchone()

    cur.execute("""
        SELECT DISTINCT sub.name, sub.grade, e.status, e.month
        FROM enrollments e
        JOIN subjects sub ON sub.id=e.subject_id
        JOIN tutor_subjects ts ON ts.subject_id=e.subject_id
        WHERE e.student_id=?
          AND ts.tutor_id=?
        ORDER BY e.month DESC, CAST(REPLACE(sub.grade,'G','') AS INTEGER), sub.name
    """, (student_id, tid))

    subjects = cur.fetchall()

    cur.execute("""
        SELECT
            COUNT(*) AS submitted_count,
            ROUND(AVG(mark),1) AS avg_mark
        FROM submissions subm
        JOIN materials m ON m.id=subm.material_id
        JOIN tutor_subjects ts ON ts.subject_id=m.subject_id
        WHERE subm.student_id=?
          AND ts.tutor_id=?
          AND m.month=?
    """, (student_id, tid, month))

    submission_stats = cur.fetchone()

    cur.execute("""
        SELECT COUNT(*) AS attendance_count
        FROM attendance a
        JOIN sessions se ON se.id=a.session_id
        WHERE a.student_id=?
          AND se.tutor_id=?
          AND strftime('%Y-%m', a.date)=?
    """, (student_id, tid, month))

    attendance_count = cur.fetchone()["attendance_count"] or 0

    conn.close()

    if not student:
        return page("Not Found", card_msg("Learner profile not found."))

    profile_pic_html = student_profile_image_html(student_id, student["full_name"], 120)

    subject_chips = "".join([
        f"""
        <span class="chip">
            {grade_label(s['grade'])} - {escape(s['name'])} ({escape(s['status'])})
        </span>
        """
        for s in subjects
    ]) or "<span class='mini muted'>No linked subjects found.</span>"

    body = f"""
    <section class="card">

        <div class="toolbar" style="margin-bottom:14px">
            <a class="btn mini secondary" href="{url_for('tutor_home')}#students">
                ← Back to Students
            </a>
        </div>

        <div class="card soft" style="border-left:5px solid #1b5e20;margin-bottom:14px">
            <div style="display:flex;gap:18px;align-items:center;flex-wrap:wrap">

                {profile_pic_html}

                <div style="flex:1;min-width:240px">
                    <h1 style="margin-bottom:4px">
                        {escape(student['full_name'] or 'Learner Profile')}
                    </h1>

                    <div class="mini muted">
                        {grade_label(student['grade'])} learner profile for tutor support.
                    </div>

                    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:10px">
                        <span class="chip">
                            WhatsApp: {escape(student['phone_whatsapp'] or '—')}
                        </span>
                    </div>
                </div>
            </div>
        </div>

        <div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:14px">

            <div class="card soft">
                <h2>Contact Details</h2>

                <p>
                    <strong>Learner WhatsApp:</strong> {escape(student['phone_whatsapp'] or '—')}<br>
                    <strong>Email:</strong> {escape(student['email'] or '—')}<br>
                    <strong>Guardian:</strong> {escape(student['guardian_name'] or '—')}<br>
                    <strong>Guardian Phone:</strong> {escape(student['guardian_phone'] or '—')}
                </p>
            </div>

            <div class="card soft">
                <h2>Academic Summary</h2>

                <p>
                    <strong>Selected Month:</strong> {pretty_month_label(month)}<br>
                    <strong>Attendance Records:</strong> {attendance_count}<br>
                    <strong>Submissions:</strong> {submission_stats['submitted_count'] or 0}<br>
                    <strong>Average Mark:</strong> {submission_stats['avg_mark'] or '—'}%
                </p>
            </div>

            <div class="card soft" style="grid-column:1/-1">
                <h2>Subjects Linked to You</h2>

                <div style="display:flex;gap:6px;flex-wrap:wrap">
                    {subject_chips}
                </div>
            </div>

        </div>

    </section>
    """

    return page("Learner Profile", body)


