@app.get('/tutor/uploads')
def tutor_uploads_library():

    r = require_tutor()
    if r:
        return r

    tid = is_tutor()
    month = get_active_month('tutor')

    q = request.args.get("q", "").strip()
    kind = request.args.get("kind", "all").strip()

    if kind not in ["all", "assignments", "recordings", "documents"]:
        kind = "all"

    try:
        page_num = int(request.args.get("page", 1))
    except:
        page_num = 1

    if page_num < 1:
        page_num = 1

    per_page = 10
    offset = (page_num - 1) * per_page

    conn = get_db()
    cur = conn.cursor()

    where = [
        "m.tutor_id = ?",
        "m.month LIKE ?"
    ]

    params = [tid, month + "%"]

    if q:
        search = f"%{q}%"
        where.append("""
            (
                m.title LIKE ?
                OR s.name LIKE ?
                OR s.grade LIKE ?
                OR m.kind LIKE ?
            )
        """)
        params += [search, search, search, search]

    if kind == "assignments":
        where.append("(m.is_assignment = 1 OR m.kind = 'assignment')")

    elif kind == "recordings":
        where.append("(m.youtube_url IS NOT NULL AND TRIM(m.youtube_url) != '')")

    elif kind == "documents":
        where.append("""
            (
                (m.youtube_url IS NULL OR TRIM(m.youtube_url) = '')
                AND COALESCE(m.is_assignment, 0) = 0
                AND m.kind != 'assignment'
            )
        """)

    where_sql = "WHERE " + " AND ".join(where)

    cur.execute(f"""
        SELECT COUNT(*) AS c
        FROM materials m
        JOIN subjects s ON s.id = m.subject_id
        {where_sql}
    """, params)

    total_records = cur.fetchone()["c"] or 0
    total_pages = max(1, (total_records + per_page - 1) // per_page)

    if page_num > total_pages:
        page_num = total_pages
        offset = (page_num - 1) * per_page

    data_params = list(params)
    data_params.extend([per_page, offset])

    cur.execute(f"""
        SELECT
            m.*,
            s.name AS subject_name,
            s.grade
        FROM materials m
        JOIN subjects s ON s.id = m.subject_id
        {where_sql}
        ORDER BY m.created_at DESC
        LIMIT ? OFFSET ?
    """, data_params)

    rows = cur.fetchall()

    def can_delete(ts, admin_unlocked):
        if admin_unlocked == 1:
            return True

        try:
            created = datetime.datetime.fromisoformat(ts)
            now = datetime.datetime.now(created.tzinfo) if created.tzinfo else datetime.datetime.now()
            return (now - created) <= datetime.timedelta(hours=24)
        except Exception:
            return False

    trs = ""

    for m in rows:
        when = (m["created_at"] or "")[:16].replace("T", " ")

        is_assignment = (m["is_assignment"] == 1 or m["kind"] == "assignment")
        is_recording = bool(m["youtube_url"])

        if is_assignment:
            type_chip = "<span class='chip pending'>Assignment</span>"
            icon = "📝"
        elif is_recording:
            type_chip = "<span class='chip active'>Recording</span>"
            icon = "🎥"
        else:
            type_chip = "<span class='chip'>Document</span>"
            icon = "📄"

        link = "—"

        if m["file_path"]:
            link = f"""
            <a class="btn mini secondary" target="_blank" href="{m['file_path']}">
                Download
            </a>
            """
        elif m["youtube_url"]:
            link = f"""
            <a class="btn mini secondary" target="_blank" href="{m['youtube_url']}">
                Watch
            </a>
            """

        cur.execute("""
            SELECT COUNT(DISTINCT student_id) AS c
            FROM material_views
            WHERE material_id = ?
        """, (m["id"],))

        viewed_total = cur.fetchone()["c"] or 0

        views_btn = f"""
        <a class="btn mini secondary"
           href="/tutor/material/{m['id']}/views">
            Views
        </a>
        """

        if can_delete(m["created_at"], m["admin_unlocked"]):
            action = f"""
            <form method="post"
                  action="{url_for('tutor_delete_material', mid=m['id'])}"
                  style="display:inline"
                  onsubmit="return confirm('Delete this upload?')">
                <button class="btn danger mini">Delete</button>
            </form>
            """
        else:
            action = "<span class='muted mini'>Locked</span>"

        trs += f"""
        <tr>
            <td>
                {type_chip}
                <div class="mini muted">{escape(m['kind'] or '—')}</div>
            </td>

            <td>
                <strong>{icon} {escape(m['title'] or 'Untitled')}</strong>
                <div class="mini muted">
                    {grade_label(m['grade'])} — {escape(m['subject_name'])}
                </div>
            </td>

            <td>{link}</td>

            <td>
                <span class="chip">{viewed_total}</span>
            </td>

            <td>{escape(when)}</td>

            <td>
                <div style="display:flex;gap:6px;flex-wrap:wrap">
                    {views_btn}
                    {action}
                </div>
            </td>
        </tr>
        """

    conn.close()

    kind_options = f"""
        <option value="all" {'selected' if kind == 'all' else ''}>All Uploads</option>
        <option value="assignments" {'selected' if kind == 'assignments' else ''}>Assignments</option>
        <option value="recordings" {'selected' if kind == 'recordings' else ''}>Recordings</option>
        <option value="documents" {'selected' if kind == 'documents' else ''}>Documents</option>
    """

    body = f"""

    <section class="card">
        <div style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap">
            <div>
                <h1>Upload Library</h1>
                <p class="muted">
                    Manage your uploaded assignments, recordings, documents and resources for {pretty_month_label(month)}.
                </p>
            </div>

            <a class="btn secondary" href="{url_for('tutor_home')}">
                Back to Dashboard
            </a>
        </div>

        <form method="get" class="toolbar" style="margin-top:14px">
            <input name="q"
                   value="{escape(q)}"
                   placeholder="Search title, subject, grade or type">

            <select name="kind">
                {kind_options}
            </select>

            <button class="btn mini">Search</button>

            <a class="btn mini secondary" href="{url_for('tutor_uploads_library')}">
                Clear
            </a>
        </form>

        <div class="mini muted" style="margin:10px 0">
            Showing {len(rows)} of {total_records} upload(s).
        </div>

        {pagination_controls("/tutor/uploads", page_num, total_pages, {"q": q, "kind": kind})}

        <div class="scroll-x">
            <table>
                <thead>
                    <tr>
                        <th>Type</th>
                        <th>Upload</th>
                        <th>File / Link</th>
                        <th>Views</th>
                        <th>Uploaded</th>
                        <th>Action</th>
                    </tr>
                </thead>

                <tbody>
                    {trs or "<tr><td colspan='6'>No uploads found.</td></tr>"}
                </tbody>
            </table>
        </div>

        {pagination_controls("/tutor/uploads", page_num, total_pages, {"q": q, "kind": kind})}
    </section>
    """

    return page("Tutor Upload Library", body)


@app.get('/tutor/material/<int:mid>/views')
def tutor_material_views(mid):

    r = require_tutor()
    if r: return r

    tid = is_tutor()

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT m.*, s.name AS subject_name, s.grade
        FROM materials m
        JOIN subjects s ON s.id = m.subject_id
        WHERE m.id = ?
          AND m.tutor_id = ?
    """, (mid, tid))

    material = cur.fetchone()

    if not material:
        conn.close()
        return page("Not allowed", card_msg("Material not found or not allowed."))

    cur.execute("""
        SELECT st.id, st.full_name, st.phone_whatsapp
        FROM enrollments e
        JOIN students st ON st.id = e.student_id
        WHERE e.subject_id = ?
          AND substr(e.month,1,7) = substr(?,1,7)
          AND e.status = 'ACTIVE'
        ORDER BY st.full_name
    """, (material["subject_id"], material["month"]))

    learners = cur.fetchall()

    cur.execute("""
        SELECT mv.*, st.full_name, st.phone_whatsapp
        FROM material_views mv
        JOIN students st ON st.id = mv.student_id
        WHERE mv.material_id = ?
        ORDER BY mv.last_viewed_at DESC
    """, (mid,))

    view_rows = cur.fetchall()

    conn.close()

    viewed_map = {v["student_id"]: v for v in view_rows}

    viewed_count = len(viewed_map)
    total_learners = len(learners)
    not_viewed_count = max(total_learners - viewed_count, 0)

    rows = ""

    for learner in learners:
        view = viewed_map.get(learner["id"])

        if view:
            status = "<span class='chip active'>Viewed</span>"
            first_viewed = view["first_viewed_at"][:16].replace("T", " ")
            last_viewed = view["last_viewed_at"][:16].replace("T", " ")
            view_count = view["view_count"]
        else:
            status = "<span class='chip lapsed'>Not viewed</span>"
            first_viewed = "—"
            last_viewed = "—"
            view_count = "0"

        rows += f"""
        <tr>
            <td>
                {escape(learner['full_name'])}
                <div class="mini muted">{escape(learner['phone_whatsapp'] or '')}</div>
            </td>
            <td>{status}</td>
            <td>{first_viewed}</td>
            <td>{last_viewed}</td>
            <td>{view_count}</td>
        </tr>
        """

    body = f"""
    <div class="card" style="border-left:5px solid #2563eb">

        <a class="btn mini secondary" href="/tutor">
            ← Back to Tutor Portal
        </a>

        <h2 style="margin-top:12px">Resource Views</h2>

        <div class="mini muted" style="margin-bottom:12px">
            {grade_label(material['grade'])} — {escape(material['subject_name'])}
            <br>
            Resource: <b>{escape(material['title'])}</b>
        </div>

        <div class="stats" style="margin-bottom:14px">
            <div class="stat">
                <div class="k">{total_learners}</div>
                <div class="t">Active Learners</div>
            </div>

            <div class="stat">
                <div class="k">{viewed_count}</div>
                <div class="t">Viewed</div>
            </div>

            <div class="stat">
                <div class="k">{not_viewed_count}</div>
                <div class="t">Not Viewed</div>
            </div>
        </div>

        <div class="scroll-x">
            <table>
                <thead>
                    <tr>
                        <th>Learner</th>
                        <th>Status</th>
                        <th>First Viewed</th>
                        <th>Last Viewed</th>
                        <th>View Count</th>
                    </tr>
                </thead>
                <tbody>
                    {rows or "<tr><td colspan='5'>No active learners found.</td></tr>"}
                </tbody>
            </table>
        </div>
    </div>
    """

    return page("Resource Views", body)    
    
    
@app.post('/tutor/publish_all_marks/<int:mid>')
def publish_all_marks(mid):

    r = require_tutor()
    if r:
        return r

    tid = is_tutor()

    conn = get_db()
    cur = conn.cursor()

    # Make sure this tutor owns the assignment
    cur.execute("""
        SELECT id
        FROM materials
        WHERE id=?
          AND tutor_id=?
          AND (is_assignment=1 OR kind='assignment')
        LIMIT 1
    """, (mid, tid))

    assignment = cur.fetchone()

    if not assignment:
        conn.close()
        return page("Access Denied", card_msg("You are not allowed to publish this assignment."))

    cur.execute("""
        UPDATE submissions
        SET is_published = 1,
            evaluated_at = COALESCE(evaluated_at, ?)
        WHERE material_id = ?
          AND (
                mark IS NOT NULL
                OR feedback IS NOT NULL
                OR marked_file_path IS NOT NULL
          )
    """, (now_utc_iso(), mid))

    conn.commit()
    conn.close()

    return redirect(url_for('tutor_assignment_manage', mid=mid, saved=1))



@app.post('/tutor/upload')
def tutor_upload():

    r = require_tutor()
    if r:
        return r

    tid = is_tutor()
    month = get_active_month('tutor')

    subject_id = request.form.get('subject_id', '').strip()
    title = request.form.get('title', '').strip()
    youtube = request.form.get('youtube', '').strip()
    delivery_mode = request.form.get('delivery_mode', 'GROUP').strip().upper()
    if delivery_mode not in ('GROUP', 'ONE_ON_ONE', 'BOTH'):
        delivery_mode = 'GROUP'

    files = request.files.getlist('file')

    is_assignment = 1 if request.form.get('is_assignment') == 'on' else 0
    open_date = request.form.get('open_date', '').strip() or None
    due = request.form.get('due', '').strip() or None

    if not is_assignment:
        open_date = None

    if is_assignment and open_date and due:
        try:
            open_value = datetime.datetime.strptime(open_date, "%Y-%m-%d").date()
            due_value = datetime.datetime.strptime(due, "%Y-%m-%d").date()
        except Exception:
            return page("Error", card_msg("Please enter valid assignment dates."))

        if open_value > due_value:
            return page("Error", card_msg("The assignment open date cannot be after the due date."))

    max_points = request.form.get('max_points', '').strip()

    try:
        max_points = int(max_points) if max_points else 100
    except Exception:
        max_points = 100

    if max_points < 1:
        max_points = 1

    if max_points > 1000:
        max_points = 1000

    if not subject_id or not title:
        return page("Error", card_msg("Subject and title required."))

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT s.uploads_locked, COALESCE(ts.delivery_mode, 'GROUP') AS assignment_mode
        FROM tutor_subjects ts
        JOIN subjects s ON s.id = ts.subject_id
        WHERE ts.tutor_id=? AND ts.subject_id=?
    """, (tid, subject_id))

    row = cur.fetchone()

    if not row:
        conn.close()
        return page("Error", card_msg("This subject is not assigned to you."))

    assignment_mode = (row["assignment_mode"] or "GROUP").upper()
    if delivery_mode == "GROUP" and assignment_mode not in ("GROUP", "BOTH"):
        conn.close()
        return page("Access Denied", card_msg("This subject is assigned to you for One-on-One sessions only."))
    if delivery_mode == "ONE_ON_ONE" and assignment_mode not in ("ONE_ON_ONE", "BOTH"):
        conn.close()
        return page("Access Denied", card_msg("This subject is assigned to you for group sessions only."))

    if row["uploads_locked"] == 1:
        conn.close()
        return page(
            "Uploads Locked",
            card_msg("Uploads and assignments are currently locked for this subject. Contact Admin.")
        )

    file_path, file_count = save_uploaded_files_as_single_file(
        files=files,
        target_dir=MATERIALS_DIR,
        prefix=f"tutor_{tid}_subject_{subject_id}",
        public_url_prefix="/materials-files"
    )

    if not file_path and not youtube:
        conn.close()
        return page("Error", card_msg("Attach at least one file or provide a recording/link."))

    now = now_utc_iso()

    if is_assignment:
        kind = "assignment"
    elif file_path:
        kind = "file"
    else:
        kind = "youtube"

    # If many files were uploaded, make the title clearer
    saved_title = title

    if file_count > 1:
        saved_title = f"{title} ({file_count} files)"

    cur.execute("""
        INSERT INTO materials(
            subject_id,
            tutor_id,
            month,
            title,
            kind,
            file_path,
            youtube_url,
            created_at,
            is_assignment,
            open_date,
            due_date,
            max_points,
            delivery_mode
        )
        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)
    """, (
        subject_id,
        tid,
        month,
        saved_title,
        kind,
        file_path,
        youtube if youtube else None,
        now,
        is_assignment,
        open_date,
        due,
        max_points,
        delivery_mode
    ))

    conn.commit()
    conn.close()

    return redirect(url_for('tutor_home'))
    
    
@app.post('/tutor/assignment/<int:mid>/upload-marked/<int:sid>')
def tutor_upload_marked_script(mid, sid):

    r = require_tutor()
    if r: return r

    tid = is_tutor()
    files = request.files.getlist("marked_file")

    valid_files = [
        f for f in files
        if f and f.filename and f.filename.strip()
    ]

    if not valid_files:
        return redirect(url_for("tutor_assignment_manage", mid=mid))

    conn = get_db()
    cur = conn.cursor()

    # Make sure this assignment belongs to the logged-in tutor
    cur.execute("""
        SELECT id
        FROM materials
        WHERE id = ?
          AND tutor_id = ?
          AND (is_assignment = 1 OR kind = 'assignment')
    """, (mid, tid))

    assignment = cur.fetchone()

    if not assignment:
        conn.close()
        return page("Error", card_msg("Assignment not found or not allowed."))

    # Make sure the learner actually submitted
    cur.execute("""
        SELECT id
        FROM submissions
        WHERE material_id = ?
          AND student_id = ?
    """, (mid, sid))

    sub = cur.fetchone()

    if not sub:
        conn.close()
        return page("Error", card_msg("This learner has not submitted yet."))

    path, file_count = save_uploaded_files_as_single_file(
        files=valid_files,
        target_dir=SUBMISSIONS_DIR,
        prefix=f"marked_{mid}_{sid}",
        public_url_prefix=None
    )
    
    if not path:
        conn.close()
        return redirect(url_for("tutor_assignment_manage", mid=mid))

    cur.execute("""
        UPDATE submissions
        SET marked_file_path = ?,
            evaluated_at = ?,
            is_published = CASE
                WHEN mark IS NOT NULL THEN 1
                ELSE is_published
            END
        WHERE id = ?
    """, (str(path), now_utc_iso(), sub["id"]))

    conn.commit()
    conn.close()

    return redirect(url_for("tutor_assignment_manage", mid=mid, saved=1))
    

@app.post('/tutor/materials/<int:mid>/delete')
def tutor_delete_material(mid:int):
    r=require_tutor()
    if r: return r
    tid=is_tutor()
    conn=get_db(); cur=conn.cursor()
    cur.execute("SELECT tutor_id,created_at FROM materials WHERE id=?", (mid,))
    m=cur.fetchone()
    if not m or m['tutor_id']!=tid:
        conn.close(); return page("Error", card_msg("Not found."))
    try:
        created=datetime.datetime.fromisoformat(m['created_at'])
        if (datetime.datetime.now(datetime.timezone.utc)-created) > datetime.timedelta(hours=24):
            conn.close(); return page("Locked", card_msg("You can only delete within 24 hours."))
    except Exception:
        pass
    cur.execute("DELETE FROM materials WHERE id=?", (mid,))
    conn.commit(); conn.close()
    return redirect(url_for('tutor_home'))

# Tutor: manage one assignment (submissions + grading)
@app.get('/tutor/assignment/<int:mid>')
def tutor_assignment_manage(mid: int):

    r = require_tutor()
    if r: return r

    tid = is_tutor()
    saved = request.args.get('saved')

    conn = get_db()
    cur = conn.cursor()

    # Confirm this assignment belongs to this tutor
    cur.execute("""
        SELECT m.*, s.name AS subject_name, s.grade
        FROM materials m
        JOIN subjects s ON s.id = m.subject_id
        WHERE m.id = ?
          AND m.tutor_id = ?
    """, (mid, tid))

    m = cur.fetchone()

    if not m:
        conn.close()
        return page("Not found", card_msg("Assignment not found."))

    total = m['max_points'] if m['max_points'] else 100

    # Active students in this subject/month
    month = get_active_month('tutor')

    cur.execute("""
        SELECT st.id, st.full_name
        FROM enrollments e
        JOIN students st ON st.id = e.student_id
        WHERE e.subject_id = ?
          AND e.month = ?
          AND e.status = 'ACTIVE'
        ORDER BY st.full_name
    """, (m['subject_id'], month))

    studs = cur.fetchall()
    rows = []

    for st in studs:

        cur.execute("""
            SELECT 
                id,
                file_path,
                submitted_at,
                mark,
                feedback,
                marked_file_path,
                is_published
            FROM submissions
            WHERE material_id = ?
              AND student_id = ?
        """, (mid, st['id']))

        sub = cur.fetchone()

        if sub:

            file_exists = sub['file_path'] and os.path.exists(sub['file_path'])

            if file_exists:
                view_section = f"""
                <a class='btn success mini'
                   target='_blank'
                   href='/tutor/view_submission/{sub['id']}'>
                    View Submission
                </a>
                """
            else:
                view_section = """
                <span class='mini' style="color:#b91c1c;font-weight:600">
                    File missing
                </span>
                """

            marked_script_btn = ""

            if sub["marked_file_path"] and os.path.exists(sub["marked_file_path"]):
                marked_script_btn = f"""
                <a class="btn success mini"
                   target="_blank"
                   href="/tutor/view_marked_script/{mid}/{st['id']}">
                    View Marked Script
                </a>
                """

            upload_marked_form = f"""
            <form method="post"
                  action="/tutor/assignment/{mid}/upload-marked/{st['id']}"
                  enctype="multipart/form-data"
                  style="margin-top:8px">

                <input type="file"
                       name="marked_file"
                       accept=".pdf,.png,.jpg,.jpeg,.doc,.docx"
                       multiple
                       required
                       class="mini">

                <button class="btn mini success" style="margin-top:6px">
                    Upload Marked Script
                </button>
            </form>
            """

            mark = '' if sub['mark'] is None else str(sub['mark'])

            published_status = (
                "<span class='chip active'>Published</span>"
                if sub["is_published"] == 1
                else "<span class='chip pending'>Not Published</span>"
            )

            rows.append(f"""
            <tr>
                <td>
                    {st['full_name']}
                    <div class="mini muted" style="margin-top:4px">
                        {published_status}
                    </div>
                </td>

                <td data-label="Tutor" style="min-width:260px">
                    <div style="display:flex;flex-direction:column;gap:8px">
                        {view_section}
                        {marked_script_btn}
                        {upload_marked_form}

                        <div class='mini muted'>
                            Submitted: {sub['submitted_at'][:16].replace('T',' ')}
                        </div>
                    </div>
                </td>

                <td>
                    <form method='post'
                          action='{url_for('tutor_assignment_grade', mid=mid, sid=st['id'])}'
                          class='inlineform'>

                        <input type='number'
                               name='mark'
                               min='0'
                               max='{total}'
                               placeholder='0..{total}'
                               value='{mark if mark else ""}'
                               style='width:100px'>

                        <input name='feedback'
                               placeholder='Feedback'
                               value='{escape(sub['feedback'] or "")}'>

                        <button class='btn mini'>
                            Save
                        </button>
                    </form>
                </td>
            </tr>
            """)

        else:
            rows.append(f"""
            <tr>
                <td>{st['full_name']}</td>
                <td><span class='muted'>No submission</span></td>
                <td>—</td>
            </tr>
            """)

    table = (
        "<div class='empty'>No students.</div>"
        if not rows
        else f"""
        <div class='scroll-x'>
            <table>
                <thead>
                    <tr>
                        <th>Student</th>
                        <th>Submission / Marked Script</th>
                        <th>Grade (0..{total})</th>
                    </tr>
                </thead>
                <tbody>
                    {''.join(rows)}
                </tbody>
            </table>
        </div>
        """
    )

    conn.close()

    js_alert = "<script>showPopup('Grade saved', 'success');</script>" if saved else ""

    body = fr"""
    <a class='links' href='{url_for('tutor_home')}'>← Back</a>

    <section class='grid'>
        <div class='card'>
            <h1>{m['title']}</h1>

            <p class='muted'>
                {grade_label(m['grade'])} — {m['subject_name']}
                • Opens: {m['open_date'] or 'Immediately'}
                • Due: {m['due_date'] or '—'}
                • Total: {total}
            </p>

            <div class="card soft" style="margin-top:10px;border-left:5px solid #f59e0b">
                <form method="post"
                      action="{url_for('tutor_extend_due_date', mid=mid)}"
                      class="inlineform"
                      style="display:flex;gap:10px;align-items:end;flex-wrap:wrap">

                    <div>
                        <label class="mini muted">Open date</label>
                        <input type="date"
                               name="open_date"
                               value="{m['open_date'] or ''}">
                    </div>

                    <div>
                        <label class="mini muted">Due date</label>
                        <input type="date"
                               name="due_date"
                               value="{m['due_date'] or ''}"
                               required>
                    </div>

                    <button class="btn success mini">
                        Update Availability
                    </button>
                </form>
            </div>

            <div style="margin:10px 0;">
                <form method="post" action="{url_for('publish_all_marks', mid=mid)}">
                    <button class="btn success">
                        Publish All Marks
                    </button>
                </form>
            </div>

            {table}
        </div>
    </section>
    """

    return page("Manage Assignment", body, extra_js=js_alert)
    
    
@app.get('/tutor/view_marked_script/<int:mid>/<int:sid>')
def tutor_view_marked_script(mid, sid):

    r = require_tutor()
    if r:
        return r

    tid = is_tutor()

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT sub.marked_file_path
        FROM submissions sub
        JOIN materials m ON m.id = sub.material_id
        WHERE sub.material_id = ?
          AND sub.student_id = ?
          AND m.tutor_id = ?
          AND sub.marked_file_path IS NOT NULL
        LIMIT 1
    """, (mid, sid, tid))

