@app.post('/admin/tutors/<int:tid>/delete')
@require_high_admin
def admin_tutor_delete(tid: int):

    r = require_admin()
    if r:
        return r

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT id, full_name, phone
        FROM tutors
        WHERE id=?
        LIMIT 1
    """, (tid,))

    tutor = cur.fetchone()

    if not tutor:
        conn.close()
        return page("Error", card_msg("Tutor not found."))

    # Get sessions linked to this tutor.
    cur.execute("""
        SELECT id
        FROM sessions
        WHERE tutor_id=?
    """, (tid,))

    session_ids = [row["id"] for row in cur.fetchall()]

    if session_ids:
        placeholders = ",".join("?" * len(session_ids))

        # Remove attendance linked to the tutor's sessions first.
        cur.execute(f"""
            DELETE FROM attendance
            WHERE session_id IN ({placeholders})
        """, session_ids)

        cur.execute(f"""
            DELETE FROM attendance_sessions
            WHERE session_id IN ({placeholders})
        """, session_ids)

        # Remove the tutor's active sessions.
        cur.execute(f"""
            DELETE FROM sessions
            WHERE id IN ({placeholders})
        """, session_ids)

    # Remove subject assignments.
    cur.execute("""
        DELETE FROM tutor_subjects
        WHERE tutor_id=?
    """, (tid,))

    # Remove tutor-manager assignments.
    cur.execute("""
        DELETE FROM manager_tutors
        WHERE tutor_id=?
    """, (tid,))

    # IMPORTANT:
    # Do NOT delete materials.
    # Do NOT delete submissions.
    # Do NOT delete the tutor row.
    # We only deactivate the tutor.
    cur.execute("""
        UPDATE tutors
        SET is_active=0,
            deleted_at=?
        WHERE id=?
    """, (
        now_utc_iso(),
        tid
    ))

    conn.commit()
    conn.close()

    return redirect(url_for("admin_tutors"))

@app.post('/admin/tutors/<int:tid>/add-subject')
def admin_tutor_add_subject(tid:int):
    r = require_admin()
    if r:
        return r

    subject_id = request.form.get('subject_id','').strip()
    if not subject_id:
        return page("Error", card_msg("Select a subject."))

    conn = get_db()
    cur = conn.cursor()
    try:
        delivery_mode = request.form.get("delivery_mode", "GROUP").strip().upper()
        if delivery_mode not in ("GROUP", "ONE_ON_ONE", "BOTH"):
            delivery_mode = "GROUP"

        cur.execute("""
            INSERT INTO tutor_subjects(tutor_id, subject_id, delivery_mode)
            VALUES(?,?,?)
            ON CONFLICT(tutor_id, subject_id)
            DO UPDATE SET delivery_mode=excluded.delivery_mode
        """, (tid, subject_id, delivery_mode))

        # Session details now come automatically from the subject.
        sync_subject_session_templates(
            conn,
            subject_id=int(subject_id),
            tutor_id=tid
        )

        conn.commit()
    finally:
        conn.close()

    return redirect(url_for('admin_tutors', assignment_saved='1'))
   

@app.post('/admin/tutors/<int:tid>/subjects/<int:subject_id>/remove')
@require_high_admin
def admin_tutor_remove_subject(tid: int, subject_id: int):

    r = require_admin()
    if r:
        return r

    conn = get_db()
    cur = conn.cursor()

    # Confirm tutor exists
    cur.execute("""
        SELECT id
        FROM tutors
        WHERE id=?
        LIMIT 1
    """, (tid,))

    tutor = cur.fetchone()

    if not tutor:
        conn.close()
        return page("Error", card_msg("Tutor not found."))

    # Confirm subject exists
    cur.execute("""
        SELECT id
        FROM subjects
        WHERE id=?
        LIMIT 1
    """, (subject_id,))

    subject = cur.fetchone()

    if not subject:
        conn.close()
        return page("Error", card_msg("Subject not found."))

    # Get all sessions linked to this tutor and subject.
    cur.execute("""
        SELECT id
        FROM sessions
        WHERE tutor_id=?
          AND subject_id=?
    """, (tid, subject_id))

    session_ids = [row["id"] for row in cur.fetchall()]

    if session_ids:
        placeholders = ",".join("?" * len(session_ids))

        # Delete attendance records linked to those sessions first.
        cur.execute(f"""
            DELETE FROM attendance
            WHERE session_id IN ({placeholders})
        """, session_ids)

        # Delete attendance session summaries linked to those sessions.
        cur.execute(f"""
            DELETE FROM attendance_sessions
            WHERE session_id IN ({placeholders})
        """, session_ids)

        # Delete the actual tutor sessions for that subject.
        cur.execute(f"""
            DELETE FROM sessions
            WHERE id IN ({placeholders})
        """, session_ids)

    # Remove the tutor-subject assignment.
    cur.execute("""
        DELETE FROM tutor_subjects
        WHERE tutor_id=?
          AND subject_id=?
    """, (tid, subject_id))

    conn.commit()
    conn.close()

    return redirect(url_for("admin_tutors"))
   
    
