@app.get('/admin/followups/add')
def admin_followup_add():
    r = require_admin()
    if r:
        return r
    
    ISSUE_TYPES = [
        "Missing R50 Registration Fee",
        "Payment Missing",
        "Fake Upload",
        "Returning Student Owing",
        "PoP Issues",
        "Other"
    ]

    FOLLOWUP_ROLES = [
        "Admin",
        "Admission COD",
        "Leadership"
    ]

    conn = get_db()
    cur = conn.cursor()
    cur.execute("SELECT DISTINCT name FROM subjects ORDER BY name")
    subjects = [row["name"] for row in cur.fetchall()]
    conn.close()

    subject_options = "".join(
        f"<option value='{escape(s)}'>{escape(s)}</option>"
        for s in subjects
    )

