@app.post('/admin/followups/create')
def admin_followup_create():
    r = require_admin()
    if r: return r

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
    INSERT INTO followups(
        full_name, phone, grade, subjects,
        issue_type,
        followup_status,
        payment_date,
        date_communicated,
        notes,
        captured_by,
        updated_by,
        updated_at,
        created_at
    )
    VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)
    """, (
        request.form.get("full_name"),
        request.form.get("phone"),
        request.form.get("grade"),
        ", ".join(request.form.getlist("subjects")),
        request.form.get("issue_type"),
        "OPEN",
        request.form.get("payment_date"),
        request.form.get("date_communicated"),
        request.form.get("notes"),
        request.form.get("captured_by"),
        request.form.get("captured_by"),
        now_utc_iso(),
        now_utc_iso()
    ))

    conn.commit()
    conn.close()

    return redirect(request.referrer or url_for('admin_followups'))
    

@app.post('/admin/followups/update/<int:fid>')
def admin_followup_update(fid):

    r = require_admin()
    if r:
        return r

    conn = get_db()
    cur = conn.cursor()

    updated_by = request.form.get("updated_by") or "Admin"
    new_note = request.form.get("new_note", "").strip()

    # Get existing notes and subjects first so they are not overwritten accidentally
    cur.execute("""
        SELECT notes, subjects
        FROM followups
        WHERE id=?
        LIMIT 1
    """, (fid,))

    existing = cur.fetchone()

    existing_notes = ""
    if existing and existing["notes"]:
        existing_notes = existing["notes"].strip()

    final_notes = existing_notes

    # Append the new note only if something was typed
    if new_note:
        timestamp = now_utc_iso()[:16].replace("T", " ")
        note_entry = f"[{timestamp}] {updated_by}: {new_note}"

        if final_notes:
            final_notes = final_notes + "\n\n" + note_entry
        else:
            final_notes = note_entry

    existing_subjects = ""
    if existing and existing["subjects"]:
        existing_subjects = existing["subjects"].strip()

    posted_subjects = [s.strip() for s in request.form.getlist("subjects") if s.strip()]

    # Remove duplicates while keeping the same order
    clean_subjects = []
    seen_subjects = set()

    for sub in posted_subjects:
        key = sub.lower()

        if key not in seen_subjects:
            clean_subjects.append(sub)
            seen_subjects.add(key)

    if clean_subjects:
        final_subjects = ", ".join(clean_subjects)
    else:
        final_subjects = existing_subjects

    cur.execute("""
    UPDATE followups SET
        full_name=?,
        phone=?,
        grade=?,
        subjects=?,
        issue_type=?,
        followup_status=?,
        payment_date=?,
        date_communicated=?,
        notes=?,
        captured_by=?,
        updated_by=?,
        updated_at=?
    WHERE id=?
    """, (
        request.form.get("full_name"),
        request.form.get("phone"),
        request.form.get("grade"),
        final_subjects,
        request.form.get("issue_type"),
        request.form.get("followup_status"),
        request.form.get("payment_date"),
        request.form.get("date_communicated"),
        final_notes,
        request.form.get("captured_by"),
        updated_by,
        now_utc_iso(),
        fid
    ))

    conn.commit()
    conn.close()

    return redirect(request.referrer or url_for('admin_followups'))
   

@app.get("/admin/followups/export")
def export_followups():
    r = require_admin()
    if r: return r

    conn = get_db()
    cur = conn.cursor()

    cur.execute("SELECT * FROM followups ORDER BY created_at DESC")
    rows = cur.fetchall()
    conn.close()

    import csv
    from io import StringIO

    si = StringIO()
    writer = csv.writer(si)

    writer.writerow([
        "Name","Phone","Grade","Subjects",
        "Issue Type","Status",
        "Payment Date","Communicated",
        "Captured By","Updated By","Notes"
    ])

    for row in rows:
        writer.writerow([
            row["full_name"],
            row["phone"],
            row["grade"],
            row["subjects"],
            row["issue_type"],
            row["followup_status"],
            row["payment_date"],
            row["date_communicated"],
            row["captured_by"],
            row["updated_by"],
            row["notes"]
        ])

    output = make_response(si.getvalue())
    output.headers["Content-Disposition"] = "attachment; filename=followups.csv"
    output.headers["Content-type"] = "text/csv"
    return output

@app.post('/admin/followups/delete/<int:fid>')
def admin_followup_delete(fid):

    r = require_admin()
    if r:
        return r

    # 🔒 Only HIGH ADMIN allowed
    if not is_high_admin():
        return redirect(url_for('admin_followups'))

    conn = get_db()
    cur = conn.cursor()

    cur.execute("DELETE FROM followups WHERE id=?", (fid,))

    conn.commit()
    conn.close()

    return redirect(url_for('admin_followups'))


@app.get('/admin/tutor-tracker')
@require_high_admin
def admin_tutor_tracker():

    r = require_admin()
    if r:
        return r

    conn = get_db()
    cur = conn.cursor()

    # load tutors
    cur.execute("""
        SELECT id, full_name
        FROM tutors
        ORDER BY full_name
    """)
    tutors = cur.fetchall()

    today = datetime.date.today()

    dates = [today - datetime.timedelta(days=i) for i in range(7)]

    header = "<th>Date</th>"
    for t in tutors:
        header += f"<th>{t['full_name']}</th>"

    rows = ""

    for d in dates:

        date_str = d.strftime("%Y-%m-%d")
        row = f"<td>{date_str}</td>"

        for t in tutors:

            cur.execute("""
                SELECT session_held
                FROM tutor_weekly_tracker
                WHERE tutor_id=? AND session_date=?
                ORDER BY id DESC
                LIMIT 1
            """, (t["id"], date_str))

            entry = cur.fetchone()

            status = "Not Logged"
            color = ""

            if entry:
                if entry["session_held"] == 1:
                    status = "Logged"
                    color = "style='background:#dcfce7'"
                else:
                    status = "Missed"
                    color = "style='background:#fee2e2'"

            row += f"""
            <td {color}>
                <a href="/admin/tutor-tracker/edit?tutor_id={t['id']}&date={date_str}">
                {status}
                </a>
            </td>
            """

        rows += f"<tr>{row}</tr>"

    # load managers
    cur.execute("""
        SELECT id, full_name, phone, pin
        FROM tutor_managers
        ORDER BY full_name
    """)
    managers = cur.fetchall()

    manager_rows = ""

    for m in managers:

        manager_rows += f"""
        <tr>
        <td>{m['full_name']}</td>
        <td>{m['phone']}</td>
        <td>{m['pin']}</td>

        <td style="display:flex;gap:6px">

        <a class="btn mini"
        href="/admin/managers/edit/{m['id']}">
        Edit
        </a>

        <form method="post"
        action="/admin/managers/reset-pin/{m['id']}">
        <button class="btn mini warn">
        Reset PIN
        </button>
        </form>

        <form method="post"
        action="/admin/managers/delete/{m['id']}"
        onsubmit="return confirm('Delete this manager?')">
        <button class="btn mini danger">
        Delete
        </button>
        </form>

        </td>
        </tr>
        """

    # assignment grid
    assignment_rows = ""

    for m in managers:

        assignment_rows += f"<tr><td>{m['full_name']}</td>"

        for t in tutors:

            cur.execute("""
            SELECT 1 FROM manager_tutors
            WHERE manager_id=? AND tutor_id=?
            """,(m["id"], t["id"]))

            assigned = cur.fetchone()

            checked = "checked" if assigned else ""

            assignment_rows += f"""
            <td style='text-align:center'>
            <input type="checkbox"
            onchange="assignTutor({m['id']},{t['id']},this.checked)"
            {checked}>
            </td>
            """

        assignment_rows += "</tr>"

    conn.close()

    assignment_table = f"""

    <section class='card'>

    <h1>Manager Tutor Assignment</h1>

    <div class="scroll-x">

    <table>

    <thead>
    <tr>
    <th>Manager</th>
    {''.join(f"<th>{t['full_name']}</th>" for t in tutors)}
    </tr>
    </thead>

    <tbody>
    {assignment_rows}
    </tbody>

    </table>

    </div>

    </section>
    """

    body = f"""
    {admin_nav()}

    <section class='card'>

        <h1>Tutor Weekly Tracker</h1>

        <div class='scroll-x'>

            <table>

                <thead>
                    <tr>{header}</tr>
                </thead>

                <tbody>
                    {rows}
                </tbody>

            </table>

        </div>

    </section>

    <section class='card'>

        <h1>Tutor Managers</h1>

        <form method="post" action="/admin/managers/add">

            <div style="display:grid;grid-template-columns:1fr 1fr auto;gap:10px">

                <input name="name" placeholder="Manager Name" required>

                <input name="phone" placeholder="Phone Number" required>

                <button class="btn">Create Manager</button>

            </div>

        </form>

        <br>

        <table>

            <thead>
                <tr>
                    <th>Name</th>
                    <th>Phone</th>
                    <th>PIN</th>
                    <th>Actions</th>
                </tr>
            </thead>

            <tbody>
                {manager_rows}
            </tbody>

        </table>

    </section>

    {assignment_table}

    <script>
    function assignTutor(manager,tutor,state){{

        fetch("/admin/assign-tutor",{{

        method:"POST",

        headers:{{
        "Content-Type":"application/x-www-form-urlencoded"
        }},

        body:`manager_id=${{manager}}&tutor_id=${{tutor}}&state=${{state?1:0}}`

        }})
    }}
    </script>
    """

    return page("Tutor Tracker", body)
    
    
