@app.post("/admin/assign-tutor")
@require_high_admin
def assign_tutor():

    manager_id = request.form.get("manager_id")
    tutor_id = request.form.get("tutor_id")
    state = request.form.get("state")

    conn = get_db()
    cur = conn.cursor()

    if state == "1":

        cur.execute("""
        INSERT OR IGNORE INTO manager_tutors(manager_id,tutor_id)
        VALUES(?,?)
        """,(manager_id,tutor_id))

    else:

        cur.execute("""
        DELETE FROM manager_tutors
        WHERE manager_id=? AND tutor_id=?
        """,(manager_id,tutor_id))

    conn.commit()
    conn.close()

    return "ok"


@app.get("/admin/tutor-operations")
@require_high_admin
def admin_tutor_operations():

    conn = get_db()
    cur = conn.cursor()

    # ---------------- monitoring window ----------------
    today = datetime.date.today()
    weekday = today.weekday()

    monitor_window = weekday in [0,1,2,3]  # Monday–Thursday

    last_sunday = today - datetime.timedelta(days=weekday + 1)
    last_saturday = last_sunday - datetime.timedelta(days=1)
    last_friday = last_sunday - datetime.timedelta(days=2)

    weekend_dates = [
        last_friday.strftime("%Y-%m-%d"),
        last_saturday.strftime("%Y-%m-%d"),
        last_sunday.strftime("%Y-%m-%d")
    ]

    # ---------------- pagination ----------------
    page_num = int(request.args.get("page", 1))
    per_page = 30
    offset = (page_num - 1) * per_page

    # ---------------- filters ----------------
    search = request.args.get("search", "")
    manager = request.args.get("manager", "")
    grade = request.args.get("grade", "")
    subject = request.args.get("subject", "")
    status = request.args.get("status", "")

    conditions = []
    params = []

    if search:
        conditions.append("t.full_name LIKE ?")
        params.append(f"%{search}%")

    if manager:
        conditions.append("tm.id=?")
        params.append(manager)

    if grade:
        conditions.append("s.grade=?")
        params.append(grade)

    if subject:
        conditions.append("s.name=?")
        params.append(subject)

    where_clause = ""
    if conditions:
        where_clause = "WHERE " + " AND ".join(conditions)

    # ---------------- load data ----------------
    cur.execute(f"""
        SELECT
            tw.id as tracker_id,
            t.id as tutor_id,
            t.full_name AS tutor,
            tm.full_name AS manager,
            s.grade,
            s.name AS subject,
            tw.session_date,
            tw.session_held,
            tw.students_attended,
            tw.recording_link,
            tw.manager_rating

        FROM tutors t

        LEFT JOIN manager_tutors mt
        ON mt.tutor_id = t.id

        LEFT JOIN tutor_managers tm
        ON tm.id = mt.manager_id

        LEFT JOIN tutor_subjects ts
        ON ts.tutor_id = t.id

        LEFT JOIN subjects s
        ON s.id = ts.subject_id

        LEFT JOIN tutor_weekly_tracker tw
        ON tw.tutor_id = t.id
        AND tw.session_date IN (?,?,?)

        {where_clause}

        ORDER BY
            CASE WHEN tw.session_date IS NULL THEN 1 ELSE 0 END,
            tw.session_date DESC
    """, weekend_dates + params)

    rows = cur.fetchall()
    conn.close()

    # ---------------- apply status filter ----------------
    filtered_rows = []

    for r in rows:

        is_not_logged = not r["session_date"]
        is_missed_session = r["session_held"] == 0
        is_missing_recording = r["session_held"] == 1 and not r["recording_link"]

        if status == "not_logged" and not is_not_logged:
            continue

        if status == "no_session" and not is_missed_session:
            continue

        if status == "no_recording" and not is_missing_recording:
            continue

        filtered_rows.append(r)

    # pagination after filtering
    total = len(filtered_rows)
    total_pages = max(1, (total + per_page - 1) // per_page)

    rows = filtered_rows[offset:offset + per_page]

    # ---------------- build table ----------------
    table_rows = ""

    for r in rows:

        row_style = ""

        is_not_logged = not r["session_date"]
        is_missed_session = r["session_held"] == 0
        is_missing_recording = r["session_held"] == 1 and not r["recording_link"]

        if is_not_logged:
            row_style = "style='background:#fde047'"

        elif is_missed_session:
            row_style = "style='background:#fca5a5'"

        elif is_missing_recording:
            row_style = "style='background:#fdba74'"

        session_status = "-"
        if r["session_held"] == 1:
            session_status = "✓"
        elif r["session_held"] == 0:
            session_status = "✕"

        recording = "✓" if r["recording_link"] else "-"

        rating = "-"
        if r["manager_rating"]:
            rating = f"{r['manager_rating']}/5"

        delete_button = ""
        if r["tracker_id"]:
            delete_button = f"""
            <form method="post"
            action="{url_for('admin_delete_tracker_session')}"
            onsubmit="return confirm('Delete this session log permanently?')">

            <input type="hidden" name="tracker_id" value="{r['tracker_id']}">

            <button class="btn danger mini">
            Delete
            </button>

            </form>
            """

        table_rows += f"""
        <tr {row_style}>
        <td>{r['session_date'] or 'Not Logged'}</td>
        <td>{r['tutor']}</td>
        <td>{r['manager'] or 'Unassigned'}</td>
        <td>{r['grade'] or '-'}</td>
        <td>{r['subject'] or '-'}</td>
        <td>{session_status}</td>
        <td>{r['students_attended'] or '-'}</td>
        <td>{recording}</td>
        <td>{rating}</td>
        <td>{delete_button}</td>
        </tr>
        """

    # ---------------- pagination ----------------
    pagination = "<div class='toolbar'>"

    for p in range(1, total_pages + 1):
        pagination += f"<a class='btn mini' href='?page={p}&status={status}&search={search}'>{p}</a>"

    pagination += "</div>"

    # ---------------- filter UI ----------------
    filter_bar = f"""
    <form method="get" class="toolbar">

    <input name="search" placeholder="Search tutor" value="{search}">

    <select name="status">

    <option value="">All</option>

    <option value="not_logged" {"selected" if status=="not_logged" else ""}>
    Not Logged
    </option>

    <option value="no_session" {"selected" if status=="no_session" else ""}>
    Missed Sessions
    </option>

    <option value="no_recording" {"selected" if status=="no_recording" else ""}>
    Missing Recordings
    </option>

    </select>

    <button class="btn mini">Apply Filter</button>

    </form>
    """

    body = f"""

    {admin_nav()}

    <section class='card'>

    <h1>Tutor Operations Dashboard</h1>

    <p class='muted'>
    Yellow rows indicate tutors whose weekend sessions were not logged by their manager.
    </p>

    {filter_bar}

    <div class="scroll-x">

    <table>

    <thead>
    <tr>
    <th>Date</th>
    <th>Tutor</th>
    <th>Manager</th>
    <th>Grade</th>
    <th>Subject</th>
    <th>Session</th>
    <th>Students</th>
    <th>Recording</th>
    <th>Rating</th>
    <th>Delete</th>
    </tr>
    </thead>

    <tbody>
    {table_rows}
    </tbody>

    </table>

    </div>

    {pagination}

    </section>
    """

    return page("Tutor Operations", body)
    
    
