@app.get('/manager/whatsapp-groups')
def manager_whatsapp_groups():

    r = require_manager()
    if r:
        return r

    manager_id = session.get("manager_id")
    month = request.args.get("month") or get_setting("current_month")

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT DISTINCT
            s.grade,
            s.name AS subject_name,
            g.invite_link,
            g.month,
            t.full_name AS tutor_name
        FROM manager_tutors mt
        JOIN tutors t ON t.id = mt.tutor_id
        JOIN tutor_subjects ts ON ts.tutor_id = t.id
        JOIN subjects s ON s.id = ts.subject_id
        JOIN groups g ON g.subject_id = s.id
        WHERE mt.manager_id = ?
          AND g.month = 'ALL'
          AND COALESCE(g.is_visible, 1) = 1
          AND g.invite_link IS NOT NULL
          AND TRIM(g.invite_link) != ''
        ORDER BY s.grade, s.name, t.full_name
    """, (manager_id,))

    rows = cur.fetchall()
    conn.close()

    group_cards = ""

    for row in rows:
        grade_text = grade_label(row["grade"])
        subject_name = row["subject_name"] or ""
        tutor_name = row["tutor_name"] or "Assigned tutor"
        invite_link = row["invite_link"] or ""

        group_cards += f"""
        <div class="card soft" style="
            border-left:5px solid #25D366;
            margin-bottom:12px;
        ">
            <div style="
                display:flex;
                justify-content:space-between;
                gap:12px;
                flex-wrap:wrap;
                align-items:center;
            ">
                <div>
                    <h3 style="margin:0 0 4px 0;">
                        {escape(grade_text)} - {escape(subject_name)}
                    </h3>

                    <div class="mini muted">
                        Tutor: {escape(tutor_name)}
                    </div>

                    <div class="mini muted">
                        Link type: Persistent group link
                    </div>
                </div>

                <a class="btn"
                   href="{escape(invite_link, quote=True)}"
                   target="_blank"
                   rel="noopener"
                   style="background:#25D366;color:white;">
                    Join WhatsApp Group
                </a>
            </div>
        </div>
        """

    if not group_cards:
        group_cards = """
        <div class="card soft" style="border-left:5px solid #f59e0b;">
            <h3>No WhatsApp group links found</h3>
            <p class="mini muted">
                There are no visible WhatsApp group links for the subjects managed by you.
            </p>
        </div>
        """

    body = f"""
    {manager_nav()}

    <section class="card">
        <h1>WhatsApp Groups</h1>

        <p class="mini muted">
            These are the WhatsApp groups for the subjects linked to the tutors you are managing.
            Only your assigned subjects are shown here.
        </p>

        <div style="margin-top:14px;">
            {group_cards}
        </div>
    </section>
    """

    return page("Tutor Manager WhatsApp Groups", body)    
    
@app.get('/manager/tracker/history')
def manager_tracker_history():

    r = require_manager()
    if r:
        return r

    page_num = int(request.args.get("page", 1))
    f_tutor = request.args.get("tutor", "")
    f_date = request.args.get("date", "")

    limit = 25
    offset = (page_num - 1) * limit

    conn = get_db()
    cur = conn.cursor()

    # -----------------------
    # Load filter lists
    # -----------------------

    cur.execute("""
        SELECT DISTINCT t.full_name
        FROM tutors t
        JOIN manager_tutors mt ON mt.tutor_id=t.id
        WHERE mt.manager_id=?
        ORDER BY t.full_name
    """,(session["manager_id"],))

    tutors=[r["full_name"] for r in cur.fetchall()]

    cur.execute("SELECT DISTINCT grade FROM tutor_weekly_tracker ORDER BY grade")
    grades=[r["grade"] for r in cur.fetchall()]

    cur.execute("SELECT DISTINCT subject FROM tutor_weekly_tracker ORDER BY subject")
    subjects=[r["subject"] for r in cur.fetchall()]

    # -----------------------
    # Build filters
    # -----------------------

    where=["mt.manager_id=?"]
    params=[session["manager_id"]]

    if f_tutor:
        where.append("t.full_name=?")
        params.append(f_tutor)

    if f_date:
        where.append("tw.session_date=?")
        params.append(f_date)

    where_sql="WHERE " + " AND ".join(where)

    # -----------------------
    # Count total rows
    # -----------------------

    cur.execute(f"""
        SELECT COUNT(*) AS c
        FROM tutor_weekly_tracker tw
        JOIN tutors t ON tw.tutor_id=t.id
        JOIN manager_tutors mt ON mt.tutor_id=t.id
        {where_sql}
    """,params)

    total=cur.fetchone()["c"]
    total_pages=max(1,(total+limit-1)//limit)

    # -----------------------
    # Fetch page
    # -----------------------

    data_params=params+[limit,offset]

    cur.execute(f"""
    SELECT
        tw.id,
        tw.tutor_id,   -- ADD THIS
        tw.session_date,
        tw.start_time,
        tw.end_time,
        tw.students_attended,
        tw.recording_link,
        tw.grade,
        tw.subject,
        t.full_name AS tutor

    FROM tutor_weekly_tracker tw
    JOIN tutors t ON tw.tutor_id = t.id
    JOIN manager_tutors mt ON mt.tutor_id = t.id

    {where_sql}

    ORDER BY tw.session_date DESC
    LIMIT ? OFFSET ?
    """,data_params)

    rows=cur.fetchall()
    conn.close()

    table_rows=""

    for r in rows:

        edit_url = url_for('manager_tracker_edit', tutor_id=r['tutor_id'], date=r['session_date'])
        delete_url = url_for('manager_tracker_delete', tracker_id=r['id'])

        table_rows += f"""
        <tr>
        <td>{r['session_date']}</td>
        <td>{r['tutor']}</td>
        <td>{r['start_time'] or '-'}</td>
        <td>{r['end_time'] or '-'}</td>
        <td>{r['students_attended'] or '-'}</td>
        <td>{'✓' if r['recording_link'] else '-'}</td>

        <td>

            <a href="{edit_url}" class="btn mini">Edit</a>

            <form method="POST"
                  action="{delete_url}"
                  onsubmit="return confirm('Are you sure you want to delete this session?');"
                  style="display:inline;">

                <button type="submit" class="btn danger mini">Delete</button>

            </form>

        </td>

        </tr>
        """

    # -----------------------
    # Pagination links
    # -----------------------

    query_string=""

    if f_tutor:
        query_string+=f"&tutor={f_tutor}"

    if f_date:
        query_string+=f"&date={f_date}"

    start=max(1,page_num-3)
    end=min(total_pages,page_num+3)

    page_links=[]

    if page_num>1:
        page_links.append(f"<a class='links' href='?page=1{query_string}'>« First</a>")
        page_links.append(f"<a class='links' href='?page={page_num-1}{query_string}'>‹ Prev</a>")

    for p in range(start,end+1):

        if p==page_num:
            page_links.append(
            f"<span class='current' style='padding:4px 8px;background:#0f172a;color:white;border-radius:6px'>{p}</span>"
            )
        else:
            page_links.append(
            f"<a class='links' href='?page={p}{query_string}'>{p}</a>"
            )

    if page_num<total_pages:
        page_links.append(f"<a class='links' href='?page={page_num+1}{query_string}'>Next ›</a>")
        page_links.append(f"<a class='links' href='?page={total_pages}{query_string}'>Last »</a>")

    nav=f"""
    <div class='pager' style="display:flex;gap:8px;margin:10px 0">

    <span class="mini muted">
    Page {page_num} of {total_pages}
    </span>

    {"".join(page_links)}

    </div>
    """

    body=f"""

    {manager_nav()}

    <section class='card'>

    <h1>Session History</h1>

    <div class='toolbar'>

        <form method="get" style="display:flex;gap:8px;flex-wrap:wrap">

            <select name="tutor">
                <option value="">All Tutors</option>
                {''.join(f"<option value='{t}' {'selected' if t==f_tutor else ''}>{t}</option>" for t in tutors)}
            </select>

            <input type="date" name="date" value="{f_date}">

            <button class="btn mini">Filter</button>

        </form>

    </div>

    {nav}

    <table>

    <thead>
    <tr>
    <th>Date</th>
    <th>Tutor</th>
    <th>Start</th>
    <th>End</th>
    <th>Students</th>
    <th>Recording</th>
    <th>Edit/Delete</th>
    </tr>
    </thead>

    <tbody>
    {table_rows or "<tr><td colspan='7'>No sessions found.</td></tr>"}
    </tbody>

    </table>

    {nav}

    </section>
    """

    return page("Session History", body)
    

