@require_high_admin
def admin_add_treasurer():

    r = require_admin()
    if r: return r

    if not is_high_admin():
        return page("Access Denied", card_msg("Only high admin can add treasurers."))

    full_name = request.form.get("full_name", "").strip()
    phone = request.form.get("phone", "").strip()
    email = request.form.get("email", "").strip()

    if not full_name or not phone:
        return page("Error", card_msg("Full name and phone are required."))

    conn = get_db()
    cur = conn.cursor()

    pin = f"{random.randint(0, 99999):05d}"

    try:
        cur.execute("""
            INSERT INTO treasurers(
                full_name,
                phone,
                email,
                pin,
                is_active,
                created_at,
                updated_at
            )
            VALUES(?,?,?,?,1,?,?)
        """, (
            full_name,
            phone,
            email,
            pin,
            now_utc_iso(),
            now_utc_iso()
        ))

        conn.commit()
        new_treasurer_id = cur.lastrowid

    except sqlite3.IntegrityError:
        conn.close()
        return page("Error", card_msg("A treasurer with this phone number already exists."))

    conn.close()

    created_at_display = now_utc_iso()[:16].replace("T", " ")

    return page(
        "Treasurer Created",
        f"""
        {admin_nav()}

        <section class="card">
            <h1>Treasurer Created Successfully</h1>

            <p class="muted">
                The treasurer account has been created successfully. Share the login details privately with the treasurer.
            </p>

            <div class="grid" style="grid-template-columns:1fr 1fr;gap:12px;margin-top:14px">

                <div class="card soft">
                    <h2>Treasurer Information</h2>

                    <p><b>Name:</b> {escape(full_name)}</p>
                    <p><b>Phone:</b> {escape(phone)}</p>
                    <p><b>Email:</b> {escape(email or '—')}</p>
                    <p><b>Status:</b> <span class="chip active">Active</span></p>
                    <p><b>Created:</b> {created_at_display}</p>
                </div>

                <div class="card soft" style="border-left:5px solid #f59e0b">
                    <h2>Login Details</h2>

                    <p><b>Login Phone:</b> {escape(phone)}</p>

                    <p>
                        <b>PIN:</b>
                        <span class="chip" style="
                            font-size:24px;
                            padding:14px 20px;
                            letter-spacing:2px;
                            font-weight:800;
                        ">
                            {pin}
                        </span>
                    </p>

                    <p class="mini muted">
                        The treasurer will use this phone number and PIN to log in.
                    </p>
                </div>

            </div>

            <div class="toolbar" style="margin-top:14px">
                <a class="btn secondary" href="/admin/treasurer/{new_treasurer_id}">
                    View Full Profile
                </a>

                <a class="btn" href="/admin/treasurers">
                    Back to Treasurers
                </a>
            </div>
        </section>
        """
    )


@app.post('/admin/treasurer/<int:tid>/reset-pin')
@require_high_admin
def admin_treasurer_reset_pin(tid):

    r = require_admin()
    if r: return r

    if not is_high_admin():
        return page("Access Denied", card_msg("Only high admin can reset treasurer PINs."))

    new_pin = f"{random.randint(0, 99999):05d}"

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        UPDATE treasurers
        SET pin=?,
            updated_at=?
        WHERE id=?
    """, (new_pin, now_utc_iso(), tid))

    conn.commit()
    conn.close()

    return page(
        "PIN Reset",
        f"""
        {admin_nav()}
        <div class="card">
            <h1>Treasurer PIN Reset</h1>
            <p>New PIN: <span class="chip">{new_pin}</span></p>
            <a class="btn" href="/admin/treasurers">Back to Treasurers</a>
        </div>
        """
    )


@app.post('/admin/treasurer/<int:tid>/toggle')
@require_high_admin
def admin_treasurer_toggle(tid):

    r = require_admin()
    if r: return r

    if not is_high_admin():
        return page("Access Denied", card_msg("Only high admin can update treasurers."))

    conn = get_db()
    cur = conn.cursor()

    cur.execute("SELECT is_active FROM treasurers WHERE id=?", (tid,))
    row = cur.fetchone()

    if row:
        new_status = 0 if row["is_active"] == 1 else 1

        cur.execute("""
            UPDATE treasurers
            SET is_active=?,
                updated_at=?
            WHERE id=?
        """, (new_status, now_utc_iso(), tid))

        conn.commit()

    conn.close()

    return redirect(url_for("admin_treasurers"))
    
    
