                cao_link("Manager Ratings", "cao_tutor_manager_ratings", "cao_tutor_managers_enabled", icon="⭐"),
                cao_link("Reviews & Ratings", "cao_reviews_ratings", icon="💬"),
                cao_link("AQM Team", "cao_aqm_team", "cao_aqm_enabled", icon="✅"),
