@app.get('/cao/tutor-manager-ratings')
def cao_tutor_manager_ratings():

    r = require_cao_permission("cao_tutor_managers_enabled", "tutor manager ratings")
    if r:
        return r

    month = request.args.get("month", "").strip() or cao_selected_month()
    q = request.args.get("q", "").strip()

    conn = get_db()
    cur = conn.cursor()

    params = [month]
    where = ["tmr.month=?"]

    if q:
        search = f"%{q}%"
        where.append("""
            (
                tm.full_name LIKE ?
                OR t.full_name LIKE ?
                OR t.phone LIKE ?
                OR tm.phone LIKE ?
                OR tmr.comment LIKE ?
            )
        """)
        params += [search, search, search, search, search]

    where_sql = "WHERE " + " AND ".join(where)

    cur.execute(f"""
        SELECT
            tmr.id,
            tmr.month,
            tmr.rating,
            tmr.comment,
            tmr.created_at,
            tmr.updated_at,

            tm.id AS manager_id,
            tm.full_name AS manager_name,
            tm.phone AS manager_phone,

            t.id AS tutor_id,
            t.full_name AS tutor_name,
            t.phone AS tutor_phone
        FROM tutor_manager_ratings tmr
        JOIN tutor_managers tm ON tm.id = tmr.manager_id
        JOIN tutors t ON t.id = tmr.tutor_id
        {where_sql}
        ORDER BY tm.full_name, t.full_name
    """, params)

    ratings = cur.fetchall()

    cur.execute("""
        SELECT
            tm.id AS manager_id,
            tm.full_name AS manager_name,
            tm.phone AS manager_phone,
            COUNT(tmr.id) AS rating_count,
            AVG(tmr.rating) AS avg_rating
        FROM tutor_managers tm
        LEFT JOIN tutor_manager_ratings tmr
            ON tmr.manager_id = tm.id
           AND tmr.month = ?
        GROUP BY tm.id
        ORDER BY tm.full_name
    """, (month,))

    manager_summaries = cur.fetchall()

    conn.close()

    summary_rows = ""

    total_rating_sum = 0
    total_rating_count = 0

    for s in manager_summaries:
        avg_rating = s["avg_rating"] if s["avg_rating"] is not None else None
        rating_count = int(s["rating_count"] or 0)

        if avg_rating is not None:
            total_rating_sum += float(avg_rating) * rating_count
            total_rating_count += rating_count

        avg_html = tutor_manager_rating_chip(avg_rating)

        summary_rows += f"""
        <tr>
            <td>
                <strong>{escape(s["manager_name"] or "—")}</strong>
                <div class="mini muted">{escape(s["manager_phone"] or "—")}</div>
            </td>

            <td>{avg_html}</td>

            <td>{rating_count}</td>
        </tr>
        """

    overall_avg = round(total_rating_sum / total_rating_count, 1) if total_rating_count else None
    overall_avg_label = f"{overall_avg}/5" if overall_avg is not None else "Not rated yet"

    detail_rows = ""

    for r0 in ratings:
        detail_rows += f"""
        <tr>
            <td>
                <strong>{escape(r0["manager_name"] or "—")}</strong>
                <div class="mini muted">{escape(r0["manager_phone"] or "—")}</div>
            </td>

            <td>
                <strong>{escape(r0["tutor_name"] or "—")}</strong>
                <div class="mini muted">{escape(r0["tutor_phone"] or "—")}</div>
            </td>

            <td>{r0["rating"]}/5</td>

            <td>{escape(r0["comment"] or "—")}</td>

            <td>{escape((r0["updated_at"] or r0["created_at"] or "")[:16].replace("T", " "))}</td>
        </tr>
        """

    body = f"""
    {cao_nav()}

    <section class="card">

        <h1>Tutor Manager Ratings</h1>

        <p class="muted">
            CAO can view the full tutor manager rating records, including which tutor submitted each rating.
            Tutor managers only see anonymous feedback.
        </p>

        <form method="get" class="toolbar">
            <input type="month" name="month" value="{escape(month)}">

            <input name="q"
                   value="{escape(q)}"
                   placeholder="Search manager, tutor, phone or comment">

            <button class="btn mini">Search</button>

            <a class="btn mini secondary" href="{url_for('cao_tutor_manager_ratings')}">
                Clear
            </a>
        </form>

        <div class="stats" style="margin-top:12px">
            {stat("Overall Manager Rating", overall_avg_label)}
            {stat("Total Ratings", total_rating_count)}
            {stat("Managers Listed", len(manager_summaries))}
        </div>

        <div class="card soft" style="margin-top:14px">
            <h2>Overall Rating Per Tutor Manager</h2>

            <div class="scroll-x">
                <table>
                    <thead>
                        <tr>
                            <th>Tutor Manager</th>
                            <th>Average Rating</th>
                            <th>Number of Ratings</th>
                        </tr>
                    </thead>

                    <tbody>
                        {summary_rows or "<tr><td colspan='3'>No tutor manager rating summary found.</td></tr>"}
                    </tbody>
                </table>
            </div>
        </div>

        <div class="card soft" style="margin-top:14px">
            <h2>Detailed Tutor Manager Ratings</h2>

            <div class="scroll-x">
                <table>
                    <thead>
                        <tr>
                            <th>Tutor Manager</th>
                            <th>Rated By Tutor</th>
                            <th>Rating</th>
                            <th>Comment</th>
                            <th>Date</th>
                        </tr>
                    </thead>

                    <tbody>
                        {detail_rows or "<tr><td colspan='5'>No detailed ratings found for this month.</td></tr>"}
                    </tbody>
                </table>
            </div>
        </div>

    </section>
    """

    return page("Tutor Manager Ratings", body)    
    
    
@app.get('/cao/tutor-manager-performance/export')
def cao_tutor_manager_performance_export():

    r = require_cao_permission("cao_tutor_managers_enabled", "tutor manager work progress export")
    if r:
        return r

    try:
        from openpyxl import Workbook
        from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
        from openpyxl.utils import get_column_letter
    except Exception:
        return page(
            "Export Error",
            card_msg("openpyxl is not installed. Please add openpyxl to requirements.txt and redeploy.")
        )

    month = request.args.get("month", "").strip() or cao_selected_month()
    q = request.args.get("q", "").strip()
    status_filter = request.args.get("status", "").strip()

    where = []
    params = []

    if q:
        search = f"%{q}%"
        where.append("(tm.full_name LIKE ? OR tm.phone LIKE ?)")
        params += [search, search]

    where_sql = "WHERE " + " AND ".join(where) if where else ""

    conn = get_db()
    cur = conn.cursor()

    cur.execute(f"""
        SELECT
            tm.id,
            tm.full_name,
            tm.phone
        FROM tutor_managers tm
        {where_sql}
        ORDER BY tm.full_name
    """, params)

    managers = cur.fetchall()
    conn.close()

    export_rows = []

    for manager in managers:
        progress = tutor_manager_work_progress_data(manager["id"], month)

        if not progress:
            continue

        if status_filter and progress["status"] != status_filter:
            continue

        export_rows.append({
            "Tutor Manager": progress["full_name"],
            "Phone": progress["phone"] or "",
            "Month": month,
            "Manager Score %": progress["manager_score"],
            "Status": progress["status"],
            "Assigned Tutors": progress["assigned_tutors"],
            "Tutors Followed Up": progress["tutors_followed_up"],
            "Follow-Up Coverage %": progress["followup_coverage"],
            "Avg Managed Tutor Progress %": progress["avg_managed_progress"],
            "Managed Tutors On Track": progress["on_track"],
            "Managed Tutors Needs Attention": progress["needs_attention"],
            "Managed Tutors High Risk": progress["high_risk"],
            "Tracker Logs": progress["tracker_logs"],
            "Manager Comments": progress["comments_count"],
            "Sessions Held": progress["sessions_held"],
            "Sessions Missed": progress["sessions_missed"],
            "Recordings Posted": progress["recordings_posted"],
            "Posted Within 24h": progress["posted_within_24h"],
            "Total Uploads By Managed Tutors": progress["total_uploads"],
            "Total Recordings By Managed Tutors": progress["total_recordings"],
            "Total Assignments By Managed Tutors": progress["total_assignments"],
            "Learner Views Under Managed Tutors": progress["total_views"],
            "Submissions Received": progress["total_submissions"],
            "Marked Submissions": progress["total_marked"],
            "Unmarked Submissions": progress["total_unmarked"],
            "Total Attendance Logs": progress["total_attendance_logs"],
            "Total Assigned Sessions": progress["total_assigned_sessions"],
            "Average Manager Rating": progress["avg_manager_rating"] if progress["avg_manager_rating"] is not None else "",
            "Recommendations": ", ".join(progress["recommendations"]) if progress["recommendations"] else "On track"
        })

    export_rows = sorted(
        export_rows,
        key=lambda x: (x["Manager Score %"], x["Tutor Manager"] or "")
    )

    wb = Workbook()
    ws = wb.active
    ws.title = "Manager Work Progress"

    headers = [
        "Tutor Manager",
        "Phone",
        "Month",
        "Manager Score %",
        "Status",
        "Assigned Tutors",
        "Tutors Followed Up",
        "Follow-Up Coverage %",
        "Avg Managed Tutor Progress %",
        "Managed Tutors On Track",
        "Managed Tutors Needs Attention",
        "Managed Tutors High Risk",
        "Tracker Logs",
        "Manager Comments",
        "Sessions Held",
        "Sessions Missed",
        "Recordings Posted",
        "Posted Within 24h",
        "Total Uploads By Managed Tutors",
        "Total Recordings By Managed Tutors",
        "Total Assignments By Managed Tutors",
        "Learner Views Under Managed Tutors",
        "Submissions Received",
        "Marked Submissions",
        "Unmarked Submissions",
        "Total Attendance Logs",
        "Total Assigned Sessions",
        "Average Manager Rating",
        "Recommendations"
    ]

    last_col = len(headers)

    ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=last_col)
    ws.cell(row=1, column=1).value = f"Tutor Manager Work Progress - {month}"
    ws.cell(row=1, column=1).font = Font(size=14, bold=True, color="FFFFFF")
    ws.cell(row=1, column=1).fill = PatternFill("solid", fgColor="1B5E20")
    ws.cell(row=1, column=1).alignment = Alignment(horizontal="center")

    ws.merge_cells(start_row=2, start_column=1, end_row=2, end_column=last_col)
    ws.cell(row=2, column=1).value = f"Filters: Search={q or 'All'} | Status={status_filter or 'All'}"
    ws.cell(row=2, column=1).font = Font(italic=True, color="64748B")
    ws.cell(row=2, column=1).alignment = Alignment(horizontal="center")

    header_row = 4

    for col, header in enumerate(headers, start=1):
        cell = ws.cell(row=header_row, column=col)
        cell.value = header
        cell.font = Font(bold=True, color="FFFFFF")
        cell.fill = PatternFill("solid", fgColor="166534")
        cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)

    for row_index, row_data in enumerate(export_rows, start=5):
        for col_index, header in enumerate(headers, start=1):
            cell = ws.cell(row=row_index, column=col_index)
            cell.value = row_data.get(header, "")
            cell.alignment = Alignment(vertical="top", wrap_text=True)

            if header == "Status":
                status = str(row_data.get(header, ""))

                if status == "On Track":
                    cell.fill = PatternFill("solid", fgColor="DCFCE7")
                elif status == "Needs Attention":
                    cell.fill = PatternFill("solid", fgColor="FEF3C7")
                elif status == "High Risk":
                    cell.fill = PatternFill("solid", fgColor="FEE2E2")

    thin = Side(border_style="thin", color="CBD5E1")

    for row in ws.iter_rows(min_row=4, max_row=ws.max_row, min_col=1, max_col=last_col):
        for cell in row:
            cell.border = Border(top=thin, left=thin, right=thin, bottom=thin)

    widths = {
        1: 26,
        2: 18,
        3: 12,
        4: 18,
        5: 18,
        6: 16,
        7: 18,
        8: 20,
        9: 26,
        10: 22,
        11: 26,
        12: 22,
        13: 16,
        14: 18,
        15: 16,
        16: 16,
        17: 18,
        18: 18,
        19: 26,
        20: 28,
        21: 28,
        22: 30,
        23: 20,
        24: 20,
        25: 20,
        26: 20,
        27: 22,
        28: 22,
        29: 50
    }

    for col_index, width in widths.items():
        ws.column_dimensions[get_column_letter(col_index)].width = width

    ws.freeze_panes = "A5"
    ws.auto_filter.ref = f"A4:{get_column_letter(last_col)}{ws.max_row}"

    # ================= TOP 10 SUMMARY SHEET =================
    top_ws = wb.create_sheet("Top 10 Summary")

    top_ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=8)
    top_ws.cell(row=1, column=1).value = f"Top 10 Tutor Manager Summary - {month}"
    top_ws.cell(row=1, column=1).font = Font(size=14, bold=True, color="FFFFFF")
    top_ws.cell(row=1, column=1).fill = PatternFill("solid", fgColor="1B5E20")
    top_ws.cell(row=1, column=1).alignment = Alignment(horizontal="center")

    top_performers = sorted(
        export_rows,
        key=lambda x: (
            -int(x.get("Manager Score %") or 0),
            -int(x.get("Follow-Up Coverage %") or 0),
            -int(x.get("Avg Managed Tutor Progress %") or 0),
            x.get("Tutor Manager") or ""
        )
    )[:10]

    support_needed = sorted(
        export_rows,
        key=lambda x: (
            int(x.get("Manager Score %") or 0),
            int(x.get("Follow-Up Coverage %") or 0),
            int(x.get("Avg Managed Tutor Progress %") or 0),
            x.get("Tutor Manager") or ""
        )
    )[:10]

    def write_manager_top_section(sheet, start_row, title, data_rows):
        sheet.merge_cells(start_row=start_row, start_column=1, end_row=start_row, end_column=8)
        sheet.cell(row=start_row, column=1).value = title
        sheet.cell(row=start_row, column=1).font = Font(size=12, bold=True, color="FFFFFF")
        sheet.cell(row=start_row, column=1).fill = PatternFill("solid", fgColor="166534")
        sheet.cell(row=start_row, column=1).alignment = Alignment(horizontal="center")

        top_headers = [
            "Rank",
            "Tutor Manager",
            "Manager Score %",
            "Status",
            "Assigned Tutors",
            "Follow-Up Coverage %",
            "High-Risk Tutors",
            "Recommendation"
        ]

        header_row = start_row + 1

        for col, header in enumerate(top_headers, start=1):
            cell = sheet.cell(row=header_row, column=col)
            cell.value = header
            cell.font = Font(bold=True, color="FFFFFF")
            cell.fill = PatternFill("solid", fgColor="1B5E20")
            cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)

        for i, row_data in enumerate(data_rows, start=1):
            row_num = header_row + i

            sheet.cell(row=row_num, column=1).value = i
            sheet.cell(row=row_num, column=2).value = row_data.get("Tutor Manager", "")
            sheet.cell(row=row_num, column=3).value = row_data.get("Manager Score %", "")
            sheet.cell(row=row_num, column=4).value = row_data.get("Status", "")
            sheet.cell(row=row_num, column=5).value = row_data.get("Assigned Tutors", "")
            sheet.cell(row=row_num, column=6).value = row_data.get("Follow-Up Coverage %", "")
            sheet.cell(row=row_num, column=7).value = row_data.get("Managed Tutors High Risk", "")
            sheet.cell(row=row_num, column=8).value = row_data.get("Recommendations", "")

            status_cell = sheet.cell(row=row_num, column=4)
            status = str(row_data.get("Status", ""))

            if status == "On Track":
                status_cell.fill = PatternFill("solid", fgColor="DCFCE7")
            elif status == "Needs Attention":
                status_cell.fill = PatternFill("solid", fgColor="FEF3C7")
            elif status == "High Risk":
                status_cell.fill = PatternFill("solid", fgColor="FEE2E2")

        thin = Side(border_style="thin", color="CBD5E1")

        for row in sheet.iter_rows(
            min_row=header_row,
            max_row=header_row + len(data_rows),
            min_col=1,
            max_col=8
        ):
            for cell in row:
                cell.border = Border(top=thin, left=thin, right=thin, bottom=thin)
                cell.alignment = Alignment(vertical="top", wrap_text=True)

        return header_row + len(data_rows) + 3

    next_row = write_manager_top_section(
        top_ws,
        3,
        "Top 10 Performing Tutor Managers",
        top_performers
    )

    write_manager_top_section(
        top_ws,
        next_row,
        "Top 10 Tutor Managers Needing Support",
        support_needed
    )

    top_widths = {
        1: 8,
        2: 28,
        3: 18,
        4: 18,
        5: 18,
        6: 22,
        7: 20,
        8: 55
    }

    for col_index, width in top_widths.items():
        top_ws.column_dimensions[get_column_letter(col_index)].width = width

    top_ws.freeze_panes = "A5"

    output = io.BytesIO()
    wb.save(output)
    output.seek(0)

    safe_month = month.replace("-", "_")
    filename = f"CAO_Tutor_Manager_Work_Progress_{safe_month}.xlsx"

    return send_file(
        output,
        as_attachment=True,
        download_name=filename,
        mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    )    
    
    
@app.get('/cao/aqm')
def cao_aqm_team():

    r = require_cao_permission("cao_aqm_enabled", "AQM team")
    if r:
        return r

    month = cao_selected_month()
    q = request.args.get("q", "").strip()
    page_num = cao_page_num()

    per_page = 15
    offset = (page_num - 1) * per_page

    where = []
    params = []

    if q:
        search = f"%{q}%"
        where.append("(aqm.full_name LIKE ? OR aqm.phone LIKE ?)")
        params += [search, search]

    where_sql = "WHERE " + " AND ".join(where) if where else ""

    conn = get_db()
    cur = conn.cursor()

    cur.execute(f"SELECT COUNT(*) AS c FROM academic_quality_managers aqm {where_sql}", params)
    total = cur.fetchone()["c"] or 0
    total_pages = max(1, (total + per_page - 1) // per_page)

    data_params = list(params)
    data_params.extend([per_page, offset])

    cur.execute(f"""
        SELECT aqm.*
        FROM academic_quality_managers aqm
        {where_sql}
        ORDER BY aqm.full_name
        LIMIT ? OFFSET ?
    """, data_params)

    aqms = cur.fetchall()

    cur.execute("""
        SELECT COUNT(*) AS c
        FROM aqm_student_marks
        WHERE month=?
    """, (month,))
    aqm_marks_this_month = cur.fetchone()["c"] or 0

    cur.execute("""
        SELECT COUNT(*) AS c
        FROM academic_report_marks
        WHERE month=?
    """, (month,))
    academic_report_marks_this_month = cur.fetchone()["c"] or 0

    conn.close()

    rows = ""

    for a in aqms:
        rows += f"""
        <tr>
            <td>
                <strong>{escape(a['full_name'])}</strong>
                <div class="mini muted">ID: {a['id']}</div>
            </td>
            <td>{escape(a['phone'] or '—')}</td>
            <td>{escape((a['created_at'] or '')[:16].replace('T',' '))}</td>
        </tr>
        """

    body = f"""
    {cao_nav()}

    <section class="card">
        <h1>Academic Quality Managers</h1>

        <form method="get" class="toolbar">
            <input type="month" name="month" value="{escape(month)}">
            <input name="q" value="{escape(q)}" placeholder="Search AQM name or phone">
            <button class="btn mini">Search</button>
            <a class="btn mini secondary" href="{url_for('cao_aqm_team')}">Clear</a>
        </form>

        <div class="stats" style="margin-top:12px">
            {stat("Month", month)}
            {stat("AQM Marks Captured", aqm_marks_this_month)}
            {stat("Academic Report Marks", academic_report_marks_this_month)}
        </div>

        <div class="mini muted" style="margin:10px 0">
            Showing {len(aqms)} of {total} AQM(s).
        </div>

        {pagination_controls("/cao/aqm", page_num, total_pages, {"month": month, "q": q})}

        <div class="scroll-x">
            <table>
                <thead>
                    <tr>
                        <th>AQM</th>
                        <th>Phone</th>
                        <th>Created</th>
                    </tr>
                </thead>
                <tbody>
                    {rows or "<tr><td colspan='3'>No AQMs found.</td></tr>"}
                </tbody>
            </table>
        </div>

        {pagination_controls("/cao/aqm", page_num, total_pages, {"month": month, "q": q})}
    </section>
    """

    return page("CAO AQM Team", body)
    
    
@app.get('/cao/tutor-rankings')
def cao_tutor_rankings():
    r = require_cao_permission("cao_performance_enabled", "weekly tutor rankings")
    if r:
        return r

    month = request.args.get("month", "").strip() or cao_selected_month()
    week_raw = request.args.get("week", "").strip()
    q = request.args.get("q", "").strip()

    try:
        week_no = int(week_raw) if week_raw else None
    except Exception:
        week_no = None

    if week_no not in (None, 1, 2, 3, 4):
        week_no = None

    conn = get_db()
    cur = conn.cursor()
    where = ["r.month=?"]
    params = [month]

    if week_no is not None:
        where.append("r.week_no=?")
        params.append(week_no)

    if q:
        search = "%" + q + "%"
        where.append("""
            (t.full_name LIKE ? OR tm.full_name LIKE ? OR s.name LIKE ? OR s.grade LIKE ?)
        """)
        params.extend([search, search, search, search])

    cur.execute(f"""
        SELECT
            r.id, r.manager_id, r.tutor_id, r.month, r.week_no,
            r.rank_position, r.total_ranked, r.created_at, r.updated_at,
            t.full_name AS tutor_name,
            tm.full_name AS manager_name,
            GROUP_CONCAT(DISTINCT (s.grade || ' - ' || s.name)) AS subjects
        FROM tutor_weekly_rankings r
        JOIN tutors t ON t.id=r.tutor_id
        JOIN tutor_managers tm ON tm.id=r.manager_id
        LEFT JOIN tutor_subjects ts ON ts.tutor_id=t.id
        LEFT JOIN subjects s ON s.id=ts.subject_id
        WHERE {' AND '.join(where)}
        GROUP BY r.id
        ORDER BY r.week_no DESC, tm.full_name, r.rank_position, t.full_name
    """, params)

    rankings = cur.fetchall()
    conn.close()

    manager_ids = {int(row["manager_id"]) for row in rankings}
    tutor_ids = {int(row["tutor_id"]) for row in rankings}
    ranking_sets = {(int(row["manager_id"]), int(row["week_no"])) for row in rankings}

    scores = []
    for row in rankings:
        score = tutor_weekly_rank_score(row["rank_position"], row["total_ranked"])
        if score is not None:
            scores.append(score)

    avg_score = round(sum(scores) / len(scores), 1) if scores else 0
    rows = ""

    for row in rankings:
        score = tutor_weekly_rank_score(row["rank_position"], row["total_ranked"])
        rank_text = f"#{row['rank_position']} of {row['total_ranked']}"
        score_text = f"{score}%" if score is not None else "—"

        rows += f"""
        <tr>
            <td><span class="chip">Week {int(row['week_no'])}</span></td>
            <td><strong>{escape(row['manager_name'] or '')}</strong></td>
            <td>
                <strong>{escape(row['tutor_name'] or '')}</strong>
                <div class="mini muted">{escape(row['subjects'] or 'No subject assigned')}</div>
            </td>
            <td><span class="chip active">{escape(rank_text)}</span></td>
            <td>{escape(score_text)}</td>
            <td>{escape(str(row["updated_at"] or row["created_at"] or "")[:16].replace("T", " "))}</td>
        </tr>
        """

    week_options = "<option value=''>All Weeks</option>"
    for value in range(1, 5):
        selected = "selected" if week_no == value else ""
        week_options += f"<option value='{value}' {selected}>Week {value}</option>"

    body = f"""
    {cao_nav()}
    <section class="card">
        <h1>Weekly Tutor Rankings</h1>

        <form method="get" class="toolbar" style="align-items:end">
            <div>
                <label>Month</label>
                <input type="month" name="month" value="{escape(month)}">
            </div>
            <div>
                <label>Week</label>
                <select name="week">{week_options}</select>
            </div>
            <div>
                <label>Search</label>
                <input name="q" value="{escape(q, quote=True)}" placeholder="Tutor, manager, subject or grade">
            </div>
            <button class="btn mini">View</button>
            <a class="btn mini secondary" href="{url_for('cao_tutor_rankings')}?month={escape(month, quote=True)}">Clear</a>
        </form>

        <div class="stats" style="margin-top:14px">
            {stat("Ranking Entries", len(rankings))}
            {stat("Ranking Sets", len(ranking_sets))}
            {stat("Tutor Managers", len(manager_ids))}
            {stat("Tutors Ranked", len(tutor_ids))}
            {stat("Average Ranking Score", f"{avg_score}%")}
        </div>

        <div class="scroll-x" style="margin-top:14px">
            <table>
                <thead>
                    <tr>
                        <th>Week</th><th>Tutor Manager</th><th>Tutor</th>
                        <th>Rank</th><th>Ranking Score</th><th>Updated</th>
                    </tr>
                </thead>
                <tbody>{rows or "<tr><td colspan='6'>No weekly tutor rankings found for this selection.</td></tr>"}</tbody>
            </table>
        </div>
    </section>
    """

    return page("Weekly Tutor Rankings", body)


@app.get('/cao/tutor-performance')
def cao_tutor_performance():

    r = require_cao_permission("cao_performance_enabled", "tutor performance")
    if r:
        return r

    month = cao_selected_month()
    q = request.args.get("q", "").strip()
    grade = request.args.get("grade", "").strip()
    subject_id = request.args.get("subject_id", "").strip()
    progress_filter = request.args.get("progress", "").strip()
    page_num = cao_page_num()

    per_page = 15
    offset = (page_num - 1) * per_page

    where = ["1=1"]
    params = []

    if q:
        search = f"%{q}%"
        where.append("""
            (
                t.full_name LIKE ?
                OR t.phone LIKE ?
                OR s.name LIKE ?
                OR s.grade LIKE ?
            )
        """)
        params += [search, search, search, search]

    if grade:
        where.append("s.grade=?")
        params.append(grade)

    if subject_id:
        where.append("s.id=?")
        params.append(subject_id)

    where_sql = "WHERE " + " AND ".join(where)

    conn = get_db()
    cur = conn.cursor()

    # Get matching tutors first.
    cur.execute(f"""
        SELECT DISTINCT
            t.id,
            t.full_name,
            t.phone
        FROM tutors t
        LEFT JOIN tutor_subjects ts ON ts.tutor_id=t.id
        LEFT JOIN subjects s ON s.id=ts.subject_id
        {where_sql}
        ORDER BY t.full_name
    """, params)

    tutor_rows = cur.fetchall()

    # Subject filter options
    cur.execute("""
        SELECT id, name, grade
        FROM subjects
        ORDER BY CAST(REPLACE(grade,'G','') AS INTEGER), name
    """)

    subjects = cur.fetchall()
    conn.close()

    tutor_data = []

    for tutor in tutor_rows:

        progress = tutor_work_progress_data(tutor["id"], month)

        status_label = progress["overall_status"]
        status_class = progress["overall_class"]

        if progress_filter and status_label != progress_filter:
            continue

        risk_subjects = [
            x for x in progress["subject_rows"]
            if x["risk_level"] == "HIGH"
        ]

        medium_subjects = [
            x for x in progress["subject_rows"]
            if x["risk_level"] == "MEDIUM"
        ]

        subject_list = []

        for sub in progress["assigned_subjects"]:
            subject_list.append(
                f"{grade_label(sub['grade'])} - {sub['subject_name']}"
            )

        tutor_data.append({
            "id": tutor["id"],
            "full_name": tutor["full_name"],
            "phone": tutor["phone"],
            "overall_rate": progress["overall_rate"],
            "overall_status": status_label,
            "status_class": status_class,
            "assigned_subjects": len(progress["assigned_subjects"]),
            "subject_list": ", ".join(subject_list) if subject_list else "No assigned subjects",
            "total_uploads": progress["total_uploads"],
            "recordings_uploaded": progress["recordings_uploaded"],
            "assignments_uploaded": progress["assignments_uploaded"],
            "material_views": progress["material_views"],
            "submissions_received": progress["submissions_received"],
            "marked_submissions": progress["marked_submissions"],
            "unmarked_submissions": progress["unmarked_submissions"],
            "marking_rate": progress["marking_rate"],
            "attendance_logs": progress["attendance_logs"],
            "assigned_sessions": progress["assigned_sessions"],
            "attendance_log_rate": progress["attendance_log_rate"],
            "tracker_logs": progress["tracker_logs"],
            "tracker_completion_rate": progress["tracker_completion_rate"],
            "avg_manager_rating": progress["avg_manager_rating"],
            "weekly_ranking_entries": progress["weekly_ranking_entries"],
            "weekly_ranked_weeks": progress["weekly_ranked_weeks"],
            "avg_weekly_rank": progress["avg_weekly_rank"],
            "avg_weekly_rank_score": progress["avg_weekly_rank_score"],
            "latest_weekly_rank": progress["latest_weekly_rank"],
            "latest_weekly_rank_total": progress["latest_weekly_rank_total"],
            "latest_weekly_rank_week": progress["latest_weekly_rank_week"],
            "latest_weekly_rank_manager": progress["latest_weekly_rank_manager"],
            "messages_sent": progress["messages_sent"],
            "portal_hours_label": progress["portal_hours_label"],
            "high_risk_subjects": risk_subjects,
            "medium_subjects": medium_subjects,
            "recommendations": progress["recommendations"]
        })

    # Sort weak tutors first, like learner performance shows risks clearly.
    tutor_data = sorted(
        tutor_data,
        key=lambda x: (x["overall_rate"], x["full_name"] or "")
    )

    total = len(tutor_data)
    total_pages = max(1, (total + per_page - 1) // per_page)

    if page_num > total_pages:
        page_num = total_pages
        offset = (page_num - 1) * per_page

    tutors = tutor_data[offset:offset + per_page]

    # Summary calculations
    on_track_count = len([x for x in tutor_data if x["overall_status"] == "On Track"])
    attention_count = len([x for x in tutor_data if x["overall_status"] == "Needs Attention"])
    high_risk_count = len([x for x in tutor_data if x["overall_status"] == "High Risk"])

    avg_progress = round(sum([x["overall_rate"] for x in tutor_data]) / len(tutor_data)) if tutor_data else 0
    avg_attendance_logs = round(sum([min(100, x["attendance_log_rate"]) for x in tutor_data]) / len(tutor_data)) if tutor_data else 0
    avg_marking_rate = round(sum([x["marking_rate"] for x in tutor_data]) / len(tutor_data)) if tutor_data else 0
    avg_tracker_rate = round(sum([min(100, x["tracker_completion_rate"]) for x in tutor_data]) / len(tutor_data)) if tutor_data else 0

    ranked_tutors = [x for x in tutor_data if x["weekly_ranking_entries"] > 0]
    ranked_tutor_count = len(ranked_tutors)
    ranking_score_values = [
        float(x["avg_weekly_rank_score"])
        for x in ranked_tutors
        if x["avg_weekly_rank_score"] is not None
    ]
    avg_weekly_ranking_score = (
        round(sum(ranking_score_values) / len(ranking_score_values))
        if ranking_score_values else 0
    )

    total_uploads = sum([x["total_uploads"] for x in tutor_data])
    total_recordings = sum([x["recordings_uploaded"] for x in tutor_data])
    total_assignments = sum([x["assignments_uploaded"] for x in tutor_data])
    total_views = sum([x["material_views"] for x in tutor_data])
    total_unmarked = sum([x["unmarked_submissions"] for x in tutor_data])
    total_tracker_logs = sum([x["tracker_logs"] for x in tutor_data])

    # Subject risk summary
    subject_risk_map = {}

    for tutor in tutor_data:
        for sub in tutor["high_risk_subjects"]:
            label = f"{grade_label(sub['grade'])} - {sub['subject_name']}"
            subject_risk_map[label] = subject_risk_map.get(label, 0) + 1

    subject_risk_labels = list(subject_risk_map.keys())[:8]
    subject_risk_values = [subject_risk_map[x] for x in subject_risk_labels]

    rows = ""

    for t in tutors:

        risk_subjects = ", ".join([
            f"{grade_label(x['grade'])} {x['subject_name']}"
            for x in t["high_risk_subjects"][:3]
        ]) or "None"

        recommendations = ", ".join(t["recommendations"][:3]) or "On track"

        avg_rating = t["avg_manager_rating"] if t["avg_manager_rating"] is not None else "—"

        if t["latest_weekly_rank"] is not None:
            weekly_rank_html = f"""
            <span class="chip active">#{t['latest_weekly_rank']} of {t['latest_weekly_rank_total']}</span>
            <div class="mini muted">Week {t['latest_weekly_rank_week']} · {t['weekly_ranked_weeks']} week(s) ranked</div>
            <div class="mini muted">Ranking score: {t['avg_weekly_rank_score'] if t['avg_weekly_rank_score'] is not None else '—'}%</div>
            """
        else:
            weekly_rank_html = "<span class='chip'>Not ranked</span>"

        rows += f"""
        <tr>
            <td>
                <strong>{escape(t['full_name'] or '—')}</strong>
                <div class="mini muted">{escape(t['phone'] or '—')}</div>
                <div class="mini muted">Subjects: {escape(t['subject_list'])}</div>
            </td>

            <td>
                <span class="chip {t['status_class']}">
                    {escape(t['overall_status'])}
                </span>
                <div class="mini muted">Overall: {t['overall_rate']}%</div>
            </td>

            <td>
                {t['total_uploads']}
                <div class="mini muted">
                    {t['recordings_uploaded']} recordings · {t['assignments_uploaded']} assignments
                </div>
            </td>

            <td>
                {t['material_views']}
                <div class="mini muted">Learner material views</div>
            </td>

            <td>
                {t['marked_submissions']} / {t['submissions_received']}
                <div class="mini muted">{t['marking_rate']}% marking rate</div>
            </td>

            <td>
                {t['attendance_logs']} / {t['assigned_sessions']}
                <div class="mini muted">{t['attendance_log_rate']}% attendance logs</div>
            </td>

            <td>
                {t['tracker_logs']}
                <div class="mini muted">{t['tracker_completion_rate']}% tracker completion</div>
            </td>

            <td>
                {escape(str(avg_rating))}
                <div class="mini muted">Manager rating</div>
            </td>

            <td>{weekly_rank_html}</td>

            <td>
                {escape(t['portal_hours_label'])}
                <div class="mini muted">{t['messages_sent']} message(s)</div>
            </td>

            <td>
                <div class="mini"><strong>Risk subjects:</strong> {escape(risk_subjects)}</div>
                <div class="mini muted"><strong>Improve:</strong> {escape(recommendations)}</div>
            </td>
        </tr>
        """

    grade_options = '<option value="">All Grades</option>'

    for g in ["G8", "G9", "G10", "G11", "G12", "G13"]:
        selected = "selected" if grade == g else ""
        grade_options += f"""
        <option value="{g}" {selected}>
            {grade_label(g)}
        </option>
        """

    subject_options = '<option value="">All Subjects</option>'

    for sub in subjects:
        selected = "selected" if subject_id == str(sub["id"]) else ""
        subject_options += f"""
        <option value="{sub["id"]}" {selected}>
            {grade_label(sub["grade"])} - {escape(sub["name"])}
        </option>
        """

    progress_options = f"""
        <option value="" {'selected' if progress_filter == '' else ''}>All Progress Levels</option>
        <option value="On Track" {'selected' if progress_filter == 'On Track' else ''}>On Track</option>
        <option value="Needs Attention" {'selected' if progress_filter == 'Needs Attention' else ''}>Needs Attention</option>
        <option value="High Risk" {'selected' if progress_filter == 'High Risk' else ''}>High Risk</option>
    """

    chart_payload = {
        "progressMix": {
            "labels": ["On Track", "Needs Attention", "High Risk"],
            "values": [on_track_count, attention_count, high_risk_count]
        },
        "workAreas": {
            "labels": ["Uploads", "Recordings", "Assignments", "Learner Views", "Tracker Logs"],
            "values": [total_uploads, total_recordings, total_assignments, total_views, total_tracker_logs]
        },
        "qualityAreas": {
            "labels": ["Overall Progress", "Attendance Logs", "Marking Rate", "Tracker Completion", "Manager Ranking"],
            "values": [avg_progress, avg_attendance_logs, avg_marking_rate, avg_tracker_rate, avg_weekly_ranking_score]
        },
        "subjectRisks": {
            "labels": subject_risk_labels,
            "values": subject_risk_values
        },
        "markingLoad": {
            "labels": ["Marked", "Unmarked"],
            "values": [
                sum([x["marked_submissions"] for x in tutor_data]),
                total_unmarked
            ]
        }
    }

    chart_json = json.dumps(chart_payload)

    body = f"""
    {cao_nav()}

    <section class="card">
        <h1>Tutor Work Progress Analytics</h1>

        <p class="muted">
            This view uses the upgraded tutor work progress data: LMS materials, recordings,
            assignments, learner engagement, marking progress, attendance logs, tracker logs,
            manager ratings, weekly tutor rankings, portal activity and risk subjects.
        </p>

        <form method="get" class="toolbar">
            <input type="month" name="month" value="{escape(month)}">

            <input name="q"
                   value="{escape(q)}"
                   placeholder="Search tutor, phone, subject or grade">

            <select name="grade">
                {grade_options}
            </select>

            <select name="subject_id">
                {subject_options}
            </select>

            <select name="progress">
                {progress_options}
            </select>

            <button class="btn mini">Search</button>

            <a class="btn mini secondary" href="{url_for('cao_tutor_performance')}">
                Clear
            </a>
            
            <a class="btn mini success"
               href="/cao/tutor-performance/export?month={escape(month)}&q={quote_from_bytes(q.encode())}&grade={escape(grade)}&subject_id={escape(subject_id)}&progress={quote_from_bytes(progress_filter.encode())}">
                Export Excel
            </a>
            
        </form>

        <div class="stats" style="margin-top:12px">
            {stat("Tutors Analysed", total)}
            {stat("Average Progress", f"{avg_progress}%")}
            {stat("Attendance Logs", f"{avg_attendance_logs}%")}
            {stat("Marking Rate", f"{avg_marking_rate}%")}
            {stat("Tracker Completion", f"{avg_tracker_rate}%")}
            {stat("Tutors Ranked", ranked_tutor_count)}
            {stat("Manager Ranking Score", f"{avg_weekly_ranking_score}%")}
            {stat("On Track", on_track_count)}
            {stat("Needs Attention", attention_count)}
            {stat("High Risk", high_risk_count)}
            {stat("Total Uploads", total_uploads)}
            {stat("Recordings", total_recordings)}
            {stat("Assignments", total_assignments)}
            {stat("Unmarked Scripts", total_unmarked)}
        </div>

        <div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:14px;margin-top:14px">

            <div class="card soft">
                <h2>Progress Status Mix</h2>
                <p class="mini muted">On track, needs attention and high-risk tutor split.</p>
                <div style="height:280px">
                    <canvas id="caoTutorProgressMixChart"></canvas>
                </div>
            </div>

            <div class="card soft">
                <h2>Academic Delivery Areas</h2>
                <p class="mini muted">Uploads, recordings, assignments, views and tracker logs.</p>
                <div style="height:280px">
                    <canvas id="caoTutorWorkAreasChart"></canvas>
                </div>
            </div>

        </div>

        <div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:14px;margin-top:14px">

            <div class="card soft">
                <h2>Quality Progress Areas</h2>
                <p class="mini muted">Average progress across quality indicators.</p>
                <div style="height:320px">
                    <canvas id="caoTutorQualityAreasChart"></canvas>
                </div>
            </div>

            <div class="card soft">
                <h2>Marking Load</h2>
                <p class="mini muted">Marked versus unmarked learner submissions.</p>
                <div style="height:320px">
                    <canvas id="caoTutorMarkingLoadChart"></canvas>
                </div>
            </div>

        </div>

        <div class="card soft" style="margin-top:14px">
            <h2>High-Risk Subjects</h2>
            <p class="mini muted">
                Subjects where tutors may need support with uploads, recordings, assignments,
                marking or attendance logging.
            </p>

            <div style="height:320px">
                <canvas id="caoTutorSubjectRiskChart"></canvas>
            </div>
        </div>

        <div class="card soft" style="margin-top:14px">
            <h2>Detailed Tutor Work Progress Table</h2>

            <div class="mini muted" style="margin:10px 0">
                Showing {len(tutors)} of {total} tutor(s).
            </div>

            {pagination_controls("/cao/tutor-performance", page_num, total_pages, {
                "month": month,
                "q": q,
                "grade": grade,
                "subject_id": subject_id,
                "progress": progress_filter
            })}

            <div class="scroll-x">
                <table>
                    <thead>
                        <tr>
                            <th>Tutor</th>
                            <th>Status</th>
                            <th>LMS Work</th>
                            <th>Learner Views</th>
                            <th>Marking</th>
                            <th>Attendance Logs</th>
                            <th>Tracker Logs</th>
                            <th>Avg Rating</th>
                            <th>Weekly Ranking</th>
                            <th>Portal Activity</th>
                            <th>Risk / Improvement</th>
                        </tr>
                    </thead>

                    <tbody>
                        {rows or "<tr><td colspan='11'>No tutor performance records found.</td></tr>"}
                    </tbody>
                </table>
            </div>

            {pagination_controls("/cao/tutor-performance", page_num, total_pages, {
                "month": month,
                "q": q,
                "grade": grade,
                "subject_id": subject_id,
                "progress": progress_filter
            })}
        </div>
    </section>

    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>

    <script>
        const tutorPerformanceCharts = {chart_json};

        function noDataPlugin(message) {{
            return {{
                id: "noData_" + Math.random().toString(36).slice(2),
                afterDraw(chart) {{
                    const dataValues = chart.data.datasets.flatMap(ds => ds.data || []);
                    const hasData = dataValues.some(v => Number(v) > 0);

                    if (!hasData) {{
                        const ctx = chart.ctx;
                        ctx.save();
                        ctx.textAlign = "center";
                        ctx.textBaseline = "middle";
                        ctx.font = "13px Arial";
                        ctx.fillStyle = "#64748b";
                        ctx.fillText(message || "No data available", chart.width / 2, chart.height / 2);
                        ctx.restore();
                    }}
                }}
            }};
        }}

        const commonTutorOptions = {{
            responsive: true,
            maintainAspectRatio: false,
            plugins: {{
                legend: {{
                    position: "bottom"
                }}
            }}
        }};

        new Chart(document.getElementById("caoTutorProgressMixChart"), {{
            type: "doughnut",
            data: {{
                labels: tutorPerformanceCharts.progressMix.labels,
                datasets: [{{
                    data: tutorPerformanceCharts.progressMix.values,
                    backgroundColor: ["#1b5e20", "#f59e0b", "#dc2626"]
                }}]
            }},
            options: commonTutorOptions,
            plugins: [noDataPlugin("No tutor progress status data")]
        }});

        new Chart(document.getElementById("caoTutorWorkAreasChart"), {{
            type: "bar",
            data: {{
                labels: tutorPerformanceCharts.workAreas.labels,
                datasets: [{{
                    label: "Total",
                    data: tutorPerformanceCharts.workAreas.values,
                    backgroundColor: "#1b5e20",
                    borderRadius: 10
                }}]
            }},
            options: {{
                ...commonTutorOptions,
                plugins: {{
                    legend: {{
                        display: false
                    }}
                }},
                scales: {{
                    y: {{
                        beginAtZero: true,
                        ticks: {{
                            precision: 0
                        }}
                    }}
                }}
            }},
            plugins: [noDataPlugin("No tutor work data")]
        }});

        new Chart(document.getElementById("caoTutorQualityAreasChart"), {{
            type: "bar",
            data: {{
                labels: tutorPerformanceCharts.qualityAreas.labels,
                datasets: [{{
                    label: "Average %",
                    data: tutorPerformanceCharts.qualityAreas.values,
                    backgroundColor: "#1b5e20",
                    borderRadius: 10
                }}]
            }},
            options: {{
                ...commonTutorOptions,
                plugins: {{
                    legend: {{
                        display: false
                    }}
                }},
                scales: {{
                    y: {{
                        beginAtZero: true,
                        max: 100,
                        ticks: {{
                            callback: function(value) {{
                                return value + "%";
                            }}
                        }}
                    }}
                }}
            }},
            plugins: [noDataPlugin("No quality progress data")]
        }});

        new Chart(document.getElementById("caoTutorMarkingLoadChart"), {{
            type: "pie",
            data: {{
                labels: tutorPerformanceCharts.markingLoad.labels,
                datasets: [{{
                    data: tutorPerformanceCharts.markingLoad.values,
                    backgroundColor: ["#1b5e20", "#dc2626"]
                }}]
            }},
            options: commonTutorOptions,
            plugins: [noDataPlugin("No marking data")]
        }});

        new Chart(document.getElementById("caoTutorSubjectRiskChart"), {{
            type: "bar",
            data: {{
                labels: tutorPerformanceCharts.subjectRisks.labels,
                datasets: [{{
                    label: "High-Risk Tutor Count",
                    data: tutorPerformanceCharts.subjectRisks.values,
                    backgroundColor: "#dc2626",
                    borderRadius: 10
                }}]
            }},
            options: {{
                ...commonTutorOptions,
                plugins: {{
                    legend: {{
                        display: false
                    }}
                }},
                scales: {{
                    y: {{
                        beginAtZero: true,
                        ticks: {{
                            precision: 0
                        }}
                    }}
                }}
            }},
            plugins: [noDataPlugin("No high-risk subject data")]
        }});
    </script>
    """

    return page("CAO Tutor Work Progress Analytics", body)   
    
    
@app.get('/cao/tutor-performance/export')
def cao_tutor_performance_export():

    r = require_cao_permission("cao_performance_enabled", "tutor performance export")
    if r:
        return r

    try:
        from openpyxl import Workbook
        from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
        from openpyxl.utils import get_column_letter
    except Exception:
        return page(
            "Export Error",
            card_msg("openpyxl is not installed. Please add openpyxl to requirements.txt and redeploy.")
        )

    month = request.args.get("month", "").strip() or cao_selected_month()
    q = request.args.get("q", "").strip()
    grade = request.args.get("grade", "").strip()
    subject_id = request.args.get("subject_id", "").strip()
    progress_filter = request.args.get("progress", "").strip()

    where = ["1=1"]
    params = []

    if q:
        search = f"%{q}%"
        where.append("""
            (
                t.full_name LIKE ?
                OR t.phone LIKE ?
                OR s.name LIKE ?
                OR s.grade LIKE ?
            )
        """)
        params += [search, search, search, search]

    if grade:
        where.append("s.grade=?")
        params.append(grade)

    if subject_id:
        where.append("s.id=?")
        params.append(subject_id)

    where_sql = "WHERE " + " AND ".join(where)

    conn = get_db()
    cur = conn.cursor()

    cur.execute(f"""
        SELECT DISTINCT
            t.id,
            t.full_name,
            t.phone
        FROM tutors t
        LEFT JOIN tutor_subjects ts ON ts.tutor_id=t.id
        LEFT JOIN subjects s ON s.id=ts.subject_id
        {where_sql}
        ORDER BY t.full_name
    """, params)

    tutor_rows = cur.fetchall()
    conn.close()

    export_rows = []

    for tutor in tutor_rows:

        progress = tutor_work_progress_data(tutor["id"], month)

        status_label = progress["overall_status"]

        if progress_filter and status_label != progress_filter:
            continue

        subject_list = []

        for sub in progress["assigned_subjects"]:
            subject_list.append(
                f"{grade_label(sub['grade'])} - {sub['subject_name']}"
            )

        risk_subjects = [
            f"{grade_label(x['grade'])} {x['subject_name']}"
            for x in progress["subject_rows"]
            if x["risk_level"] == "HIGH"
        ]

        medium_subjects = [
            f"{grade_label(x['grade'])} {x['subject_name']}"
            for x in progress["subject_rows"]
            if x["risk_level"] == "MEDIUM"
        ]

        recommendations = progress["recommendations"] or []

        export_rows.append({
            "Tutor Name": tutor["full_name"] or "",
            "Phone": tutor["phone"] or "",
            "Month": month,
            "Assigned Subjects Count": len(progress["assigned_subjects"]),
            "Assigned Subjects": ", ".join(subject_list) if subject_list else "No assigned subjects",
            "Overall Progress %": progress["overall_rate"],
            "Overall Status": progress["overall_status"],
            "Total Uploads": progress["total_uploads"],
            "Recordings Uploaded": progress["recordings_uploaded"],
            "Assignments Uploaded": progress["assignments_uploaded"],
            "Learner Material Views": progress["material_views"],
            "Submissions Received": progress["submissions_received"],
            "Marked Submissions": progress["marked_submissions"],
            "Unmarked Submissions": progress["unmarked_submissions"],
            "Marking Rate %": progress["marking_rate"],
            "Attendance Logs": progress["attendance_logs"],
            "Assigned Sessions": progress["assigned_sessions"],
            "Attendance Log Rate %": progress["attendance_log_rate"],
            "Tracker Logs": progress["tracker_logs"],
            "Tracker Completion Rate %": progress["tracker_completion_rate"],
            "Average Manager Rating": progress["avg_manager_rating"] if progress["avg_manager_rating"] is not None else "",
            "Weekly Ranking Entries": progress["weekly_ranking_entries"],
            "Weeks Ranked": progress["weekly_ranked_weeks"],
            "Average Weekly Rank": progress["avg_weekly_rank"] if progress["avg_weekly_rank"] is not None else "",
            "Manager Ranking Score %": progress["avg_weekly_rank_score"] if progress["avg_weekly_rank_score"] is not None else "",
            "Latest Weekly Rank": (
                f"#{progress['latest_weekly_rank']} of {progress['latest_weekly_rank_total']} (Week {progress['latest_weekly_rank_week']})"
                if progress["latest_weekly_rank"] is not None else ""
            ),
            "Messages Sent": progress["messages_sent"],
            "Portal Activity": progress["portal_hours_label"],
            "High Risk Subjects": ", ".join(risk_subjects) if risk_subjects else "None",
            "Medium Risk Subjects": ", ".join(medium_subjects) if medium_subjects else "None",
            "Recommendations": ", ".join(recommendations) if recommendations else "On track"
        })

    export_rows = sorted(
        export_rows,
        key=lambda x: (x["Overall Progress %"], x["Tutor Name"])
    )

    wb = Workbook()
    ws = wb.active
    ws.title = "Tutor Work Progress"

    title = f"Detailed Tutor Work Progress - {month}"
    ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=31)
    ws.cell(row=1, column=1).value = title
    ws.cell(row=1, column=1).font = Font(size=14, bold=True, color="FFFFFF")
    ws.cell(row=1, column=1).fill = PatternFill("solid", fgColor="1B5E20")
    ws.cell(row=1, column=1).alignment = Alignment(horizontal="center")

    filter_text = f"Filters: Search={q or 'All'} | Grade={grade or 'All'} | Subject={subject_id or 'All'} | Progress={progress_filter or 'All'}"
    ws.merge_cells(start_row=2, start_column=1, end_row=2, end_column=31)
    ws.cell(row=2, column=1).value = filter_text
    ws.cell(row=2, column=1).font = Font(italic=True, color="64748B")
    ws.cell(row=2, column=1).alignment = Alignment(horizontal="center")

    headers = [
        "Tutor Name",
        "Phone",
        "Month",
        "Assigned Subjects Count",
        "Assigned Subjects",
        "Overall Progress %",
        "Overall Status",
        "Total Uploads",
        "Recordings Uploaded",
        "Assignments Uploaded",
        "Learner Material Views",
        "Submissions Received",
        "Marked Submissions",
        "Unmarked Submissions",
        "Marking Rate %",
        "Attendance Logs",
        "Assigned Sessions",
        "Attendance Log Rate %",
        "Tracker Logs",
        "Tracker Completion Rate %",
        "Average Manager Rating",
        "Weekly Ranking Entries",
        "Weeks Ranked",
        "Average Weekly Rank",
        "Manager Ranking Score %",
        "Latest Weekly Rank",
        "Messages Sent",
        "Portal Activity",
        "High Risk Subjects",
        "Medium Risk Subjects",
        "Recommendations"
    ]

    header_row = 4

    for col, header in enumerate(headers, start=1):
        cell = ws.cell(row=header_row, column=col)
        cell.value = header
        cell.font = Font(bold=True, color="FFFFFF")
        cell.fill = PatternFill("solid", fgColor="166534")
        cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)

    for row_index, row_data in enumerate(export_rows, start=5):
        for col_index, header in enumerate(headers, start=1):
            cell = ws.cell(row=row_index, column=col_index)
            cell.value = row_data.get(header, "")
            cell.alignment = Alignment(vertical="top", wrap_text=True)

            if header == "Overall Status":
                status = str(row_data.get(header, ""))

                if status == "On Track":
                    cell.fill = PatternFill("solid", fgColor="DCFCE7")
                elif status == "Needs Attention":
                    cell.fill = PatternFill("solid", fgColor="FEF3C7")
                elif status == "High Risk":
                    cell.fill = PatternFill("solid", fgColor="FEE2E2")

    thin = Side(border_style="thin", color="CBD5E1")

    for row in ws.iter_rows(min_row=4, max_row=ws.max_row, min_col=1, max_col=len(headers)):
        for cell in row:
            cell.border = Border(top=thin, left=thin, right=thin, bottom=thin)

    column_widths = {
        1: 24,
        2: 18,
        3: 12,
        4: 18,
        5: 42,
        6: 18,
        7: 18,
        8: 14,
        9: 18,
        10: 18,
        11: 20,
        12: 20,
        13: 20,
        14: 20,
        15: 18,
        16: 16,
        17: 16,
        18: 20,
        19: 16,
        20: 22,
        21: 22,
        22: 18,
        23: 16,
        24: 20,
        25: 22,
        26: 24,
        27: 16,
        28: 18,
        29: 36,
        30: 36,
        31: 45
    }

    for col_index, width in column_widths.items():
        ws.column_dimensions[get_column_letter(col_index)].width = width

    ws.freeze_panes = "A5"
    ws.auto_filter.ref = f"A4:{get_column_letter(len(headers))}{ws.max_row}"
    
    # ================= TOP 10 SUMMARY SHEET =================
    top_ws = wb.create_sheet("Top 10 Summary")

    top_ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=8)
    top_ws.cell(row=1, column=1).value = f"Top 10 Tutor Work Progress Summary - {month}"
    top_ws.cell(row=1, column=1).font = Font(size=14, bold=True, color="FFFFFF")
    top_ws.cell(row=1, column=1).fill = PatternFill("solid", fgColor="1B5E20")
    top_ws.cell(row=1, column=1).alignment = Alignment(horizontal="center")

    # Top 10 best performing tutors
    top_performers = sorted(
        export_rows,
        key=lambda x: (
            -int(x.get("Overall Progress %") or 0),
            -int(x.get("Marking Rate %") or 0),
            -int(x.get("Attendance Log Rate %") or 0),
            x.get("Tutor Name") or ""
        )
    )[:10]

    # Top 10 tutors needing support
    support_needed = sorted(
        export_rows,
        key=lambda x: (
            int(x.get("Overall Progress %") or 0),
            int(x.get("Marking Rate %") or 0),
            int(x.get("Attendance Log Rate %") or 0),
            x.get("Tutor Name") or ""
        )
    )[:10]

    def write_top10_section(sheet, start_row, title, data_rows):
        sheet.merge_cells(start_row=start_row, start_column=1, end_row=start_row, end_column=8)
        sheet.cell(row=start_row, column=1).value = title
        sheet.cell(row=start_row, column=1).font = Font(size=12, bold=True, color="FFFFFF")
        sheet.cell(row=start_row, column=1).fill = PatternFill("solid", fgColor="166534")
        sheet.cell(row=start_row, column=1).alignment = Alignment(horizontal="center")

        headers_top = [
            "Rank",
            "Tutor Name",
            "Overall Progress %",
            "Status",
            "Assigned Subjects",
            "Marking Rate %",
            "Attendance Log Rate %",
            "Recommendation"
        ]

        header_row = start_row + 1

        for col, header in enumerate(headers_top, start=1):
            cell = sheet.cell(row=header_row, column=col)
            cell.value = header
            cell.font = Font(bold=True, color="FFFFFF")
            cell.fill = PatternFill("solid", fgColor="1B5E20")
            cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)

        for i, row_data in enumerate(data_rows, start=1):
            row_num = header_row + i

            recommendation = row_data.get("Recommendations") or "On track"

            sheet.cell(row=row_num, column=1).value = i
            sheet.cell(row=row_num, column=2).value = row_data.get("Tutor Name", "")
            sheet.cell(row=row_num, column=3).value = row_data.get("Overall Progress %", "")
            sheet.cell(row=row_num, column=4).value = row_data.get("Overall Status", "")
            sheet.cell(row=row_num, column=5).value = row_data.get("Assigned Subjects", "")
            sheet.cell(row=row_num, column=6).value = row_data.get("Marking Rate %", "")
            sheet.cell(row=row_num, column=7).value = row_data.get("Attendance Log Rate %", "")
            sheet.cell(row=row_num, column=8).value = recommendation

            status_cell = sheet.cell(row=row_num, column=4)
            status = str(row_data.get("Overall Status", ""))

            if status == "On Track":
                status_cell.fill = PatternFill("solid", fgColor="DCFCE7")
            elif status == "Needs Attention":
                status_cell.fill = PatternFill("solid", fgColor="FEF3C7")
            elif status == "High Risk":
                status_cell.fill = PatternFill("solid", fgColor="FEE2E2")

        thin = Side(border_style="thin", color="CBD5E1")

        for row in sheet.iter_rows(
            min_row=header_row,
            max_row=header_row + len(data_rows),
            min_col=1,
            max_col=8
        ):
            for cell in row:
                cell.border = Border(top=thin, left=thin, right=thin, bottom=thin)
                cell.alignment = Alignment(vertical="top", wrap_text=True)

        return header_row + len(data_rows) + 3

    next_row = write_top10_section(
        top_ws,
        3,
        "Top 10 Performing Tutors",
        top_performers
    )

    write_top10_section(
        top_ws,
        next_row,
        "Top 10 Tutors Needing Support",
        support_needed
    )

    top_widths = {
        1: 8,
        2: 26,
        3: 18,
        4: 18,
        5: 45,
        6: 18,
        7: 22,
        8: 50
    }

    for col_index, width in top_widths.items():
        top_ws.column_dimensions[get_column_letter(col_index)].width = width

    top_ws.freeze_panes = "A5"

    output = io.BytesIO()
    wb.save(output)
    output.seek(0)

    safe_month = month.replace("-", "_")
    filename = f"CAO_Tutor_Work_Progress_{safe_month}.xlsx"

    return send_file(
        output,
        as_attachment=True,
        download_name=filename,
        mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    )    
    
    
@app.get('/cao/sessions')
def cao_sessions():

    r = require_cao_permission("cao_attendance_enabled", "classes and sessions")
    if r:
        return r

    q = request.args.get("q", "").strip()
    page_num = cao_page_num()

    per_page = 15
    offset = (page_num - 1) * per_page

    where = ["se.active=1"]
    params = []

    if q:
        search = f"%{q}%"
        where.append("(t.full_name LIKE ? OR s.name LIKE ? OR s.grade LIKE ? OR se.meet_link LIKE ?)")
        params += [search, search, search, search]

    where_sql = "WHERE " + " AND ".join(where)

    conn = get_db()
    cur = conn.cursor()

    cur.execute(f"""
        SELECT COUNT(*) AS c
        FROM sessions se
        JOIN tutors t ON t.id=se.tutor_id
        JOIN subjects s ON s.id=se.subject_id
        {where_sql}
    """, params)

    total = cur.fetchone()["c"] or 0
    total_pages = max(1, (total + per_page - 1) // per_page)

    data_params = list(params)
    data_params.extend([per_page, offset])

    cur.execute(f"""
        SELECT
            se.*,
            t.full_name AS tutor_name,
            s.name AS subject_name,
            s.grade
        FROM sessions se
        JOIN tutors t ON t.id=se.tutor_id
        JOIN subjects s ON s.id=se.subject_id
        {where_sql}
        ORDER BY s.grade, s.name, se.day_of_week, se.start_time
        LIMIT ? OFFSET ?
    """, data_params)

    sessions_rows = cur.fetchall()
    conn.close()

    rows = ""

    for s in sessions_rows:
        day = DOW[int(s["day_of_week"] or 0)] if str(s["day_of_week"]).isdigit() else "—"

        rows += f"""
        <tr>
            <td>{grade_label(s['grade'])}</td>
            <td>{escape(s['subject_name'])}</td>
            <td>{escape(s['tutor_name'])}</td>
            <td>{escape(day)}</td>
            <td>{escape(s['start_time'])} - {escape(s['end_time'])}</td>
            <td>{escape(s['meet_link'] or '—')}</td>
        </tr>
        """

    body = f"""
    {cao_nav()}

    <section class="card">
        <h1>Classes & Sessions</h1>

        <form method="get" class="toolbar">
            <input name="q" value="{escape(q)}" placeholder="Search tutor, subject, grade or link">
            <button class="btn mini">Search</button>
            <a class="btn mini secondary" href="{url_for('cao_sessions')}">Clear</a>
        </form>

        <div class="mini muted" style="margin:10px 0">
            Showing {len(sessions_rows)} of {total} active session(s).
        </div>

        {pagination_controls("/cao/sessions", page_num, total_pages, {"q": q})}

        <div class="scroll-x">
            <table>
                <thead>
                    <tr>
                        <th>Grade</th>
                        <th>Subject</th>
                        <th>Tutor</th>
                        <th>Day</th>
                        <th>Time</th>
                        <th>Link</th>
                    </tr>
                </thead>
                <tbody>
                    {rows or "<tr><td colspan='6'>No sessions found.</td></tr>"}
                </tbody>
            </table>
        </div>

        {pagination_controls("/cao/sessions", page_num, total_pages, {"q": q})}
    </section>
    """

    return page("CAO Sessions", body)
    
    
@app.get('/cao/materials')
def cao_materials():

    r = require_cao_permission("cao_materials_enabled", "materials")
    if r:
        return r

    month = cao_selected_month()
    q = request.args.get("q", "").strip()
    kind = request.args.get("kind", "").strip()
    page_num = cao_page_num()

    per_page = 15
    offset = (page_num - 1) * per_page

    where = ["m.month LIKE ?"]
    params = [month + "%"]

    if q:
        search = f"%{q}%"
        where.append("(m.title LIKE ? OR t.full_name LIKE ? OR s.name LIKE ? OR s.grade LIKE ?)")
        params += [search, search, search, search]

    if kind == "recordings":
        where.append("m.youtube_url IS NOT NULL AND TRIM(m.youtube_url) != ''")
    elif kind == "documents":
        where.append("(m.youtube_url IS NULL OR TRIM(m.youtube_url) = '') AND COALESCE(m.is_assignment,0)=0 AND m.kind!='assignment'")

    where_sql = "WHERE " + " AND ".join(where)

    conn = get_db()
    cur = conn.cursor()

    cur.execute(f"""
        SELECT COUNT(*) AS c
        FROM materials m
        JOIN tutors t ON t.id=m.tutor_id
        JOIN subjects s ON s.id=m.subject_id
        {where_sql}
    """, params)

    total = cur.fetchone()["c"] or 0
    total_pages = max(1, (total + per_page - 1) // per_page)

    data_params = list(params)
    data_params.extend([per_page, offset])

    cur.execute(f"""
        SELECT
            m.*,
            t.full_name AS tutor_name,
            s.name AS subject_name,
            s.grade
        FROM materials m
        JOIN tutors t ON t.id=m.tutor_id
        JOIN subjects s ON s.id=m.subject_id
        {where_sql}
        ORDER BY m.created_at DESC
        LIMIT ? OFFSET ?
    """, data_params)

    materials_rows = cur.fetchall()
    conn.close()

    rows = ""

    for m in materials_rows:
        material_type = "Recording" if m["youtube_url"] else "Assignment" if (m["is_assignment"] == 1 or m["kind"] == "assignment") else "Document"

        link = "—"
        if m["youtube_url"]:
            link = f"<a target='_blank' href='{escape(m['youtube_url'])}'>Watch</a>"
        elif m["file_path"]:
            link = f"<a target='_blank' href='{escape(m['file_path'])}'>Download</a>"

        rows += f"""
        <tr>
            <td>
                <strong>{escape(m['title'])}</strong>
                <div class="mini muted">{escape(material_type)}</div>
            </td>
            <td>{grade_label(m['grade'])}</td>
            <td>{escape(m['subject_name'])}</td>
            <td>{escape(m['tutor_name'])}</td>
            <td>{link}</td>
            <td>{escape((m['created_at'] or '')[:16].replace('T',' '))}</td>
        </tr>
        """

    kind_options = f"""
        <option value="" {'selected' if kind == '' else ''}>All Materials</option>
        <option value="recordings" {'selected' if kind == 'recordings' else ''}>Recordings</option>
        <option value="documents" {'selected' if kind == 'documents' else ''}>Documents</option>
    """

    body = f"""
    {cao_nav()}

    <section class="card">
        <h1>Academic Materials</h1>

        <form method="get" class="toolbar">
            <input type="month" name="month" value="{escape(month)}">
            <input name="q" value="{escape(q)}" placeholder="Search title, tutor, subject or grade">
            <select name="kind">{kind_options}</select>
            <button class="btn mini">Search</button>
            <a class="btn mini secondary" href="{url_for('cao_materials')}">Clear</a>
        </form>

        <div class="mini muted" style="margin:10px 0">
            Showing {len(materials_rows)} of {total} material(s).
        </div>

        {pagination_controls("/cao/materials", page_num, total_pages, {"month": month, "q": q, "kind": kind})}

        <div class="scroll-x">
            <table>
                <thead>
                    <tr>
                        <th>Material</th>
                        <th>Grade</th>
                        <th>Subject</th>
                        <th>Tutor</th>
                        <th>File / Link</th>
                        <th>Uploaded</th>
                    </tr>
                </thead>
                <tbody>
                    {rows or "<tr><td colspan='6'>No materials found.</td></tr>"}
                </tbody>
            </table>
        </div>

        {pagination_controls("/cao/materials", page_num, total_pages, {"month": month, "q": q, "kind": kind})}
    </section>
    """

    return page("CAO Materials", body)
    
    
@app.get('/cao/assignments')
def cao_assignments():

    r = require_cao_permission("cao_assignments_enabled", "assignments")
    if r:
        return r

    month = cao_selected_month()
    q = request.args.get("q", "").strip()
    page_num = cao_page_num()

    per_page = 15
    offset = (page_num - 1) * per_page

    where = ["m.month LIKE ?", "(m.is_assignment=1 OR m.kind='assignment')"]
    params = [month + "%"]

    if q:
        search = f"%{q}%"
        where.append("(m.title LIKE ? OR t.full_name LIKE ? OR s.name LIKE ? OR s.grade LIKE ?)")
        params += [search, search, search, search]

    where_sql = "WHERE " + " AND ".join(where)

    conn = get_db()
    cur = conn.cursor()

    cur.execute(f"""
        SELECT COUNT(*) AS c
        FROM materials m
        JOIN tutors t ON t.id=m.tutor_id
        JOIN subjects s ON s.id=m.subject_id
        {where_sql}
    """, params)

    total = cur.fetchone()["c"] or 0
    total_pages = max(1, (total + per_page - 1) // per_page)

    data_params = list(params)
    data_params.extend([per_page, offset])

    cur.execute(f"""
        SELECT
            m.*,
            t.full_name AS tutor_name,
            s.name AS subject_name,
            s.grade,
            COUNT(sub.id) AS submission_count,
            COUNT(CASE WHEN sub.mark IS NOT NULL THEN 1 END) AS marked_count
        FROM materials m
        JOIN tutors t ON t.id=m.tutor_id
        JOIN subjects s ON s.id=m.subject_id
        LEFT JOIN submissions sub ON sub.material_id=m.id
        {where_sql}
        GROUP BY m.id
        ORDER BY m.created_at DESC
        LIMIT ? OFFSET ?
    """, data_params)

    assignments = cur.fetchall()
    conn.close()

    rows = ""

    for a in assignments:
        rows += f"""
        <tr>
            <td>
                <strong>{escape(a['title'])}</strong>
                <div class="mini muted">Due: {escape(a['due_date'] or '—')}</div>
            </td>
            <td>{grade_label(a['grade'])}</td>
            <td>{escape(a['subject_name'])}</td>
            <td>{escape(a['tutor_name'])}</td>
            <td>{a['submission_count'] or 0}</td>
            <td>{a['marked_count'] or 0}</td>
            <td>{a['max_points'] or 100}</td>
            <td>{escape((a['created_at'] or '')[:16].replace('T',' '))}</td>
        </tr>
        """

    body = f"""
    {cao_nav()}

    <section class="card">
        <h1>Assignments</h1>

        <form method="get" class="toolbar">
            <input type="month" name="month" value="{escape(month)}">
            <input name="q" value="{escape(q)}" placeholder="Search assignment, tutor, subject or grade">
            <button class="btn mini">Search</button>
            <a class="btn mini secondary" href="{url_for('cao_assignments')}">Clear</a>
        </form>

        <div class="mini muted" style="margin:10px 0">
            Showing {len(assignments)} of {total} assignment(s).
        </div>

        {pagination_controls("/cao/assignments", page_num, total_pages, {"month": month, "q": q})}

        <div class="scroll-x">
            <table>
                <thead>
                    <tr>
                        <th>Assignment</th>
                        <th>Grade</th>
                        <th>Subject</th>
                        <th>Tutor</th>
                        <th>Submissions</th>
                        <th>Marked</th>
                        <th>Max Points</th>
                        <th>Uploaded</th>
                    </tr>
                </thead>
                <tbody>
                    {rows or "<tr><td colspan='8'>No assignments found.</td></tr>"}
                </tbody>
            </table>
        </div>

        {pagination_controls("/cao/assignments", page_num, total_pages, {"month": month, "q": q})}
    </section>
    """

    return page("CAO Assignments", body)
    
    
@app.get('/cao/learner-performance')
def cao_learner_performance():

    r = require_cao_permission("cao_performance_enabled", "learner performance")
    if r:
        return r

    month = cao_selected_month()
    q = request.args.get("q", "").strip()
    grade = request.args.get("grade", "").strip()
    progress_filter = request.args.get("progress", "").strip()
    page_num = cao_page_num()

    per_page = 15
    offset = (page_num - 1) * per_page

    today = datetime.date.today().isoformat()

    where = ["e.month=?", "e.status='ACTIVE'"]
    params = [month]

    if q:
        search = f"%{q}%"
        where.append("""
            (
                st.full_name LIKE ?
                OR st.phone_whatsapp LIKE ?
                OR sub.name LIKE ?
                OR st.school LIKE ?
            )
        """)
        params += [search, search, search, search]

    if grade:
        where.append("st.grade=?")
        params.append(grade)

    where_sql = "WHERE " + " AND ".join(where)

    conn = get_db()
    cur = conn.cursor()

    # Count active learners matching search/filter
    cur.execute(f"""
        SELECT COUNT(DISTINCT st.id) AS c
        FROM students st
        JOIN enrollments e ON e.student_id=st.id
        JOIN subjects sub ON sub.id=e.subject_id
        {where_sql}
    """, params)

    total_base = cur.fetchone()["c"] or 0

    # Pull all matching learner IDs first so we can calculate academic progress properly.
    cur.execute(f"""
        SELECT DISTINCT st.id
        FROM students st
        JOIN enrollments e ON e.student_id=st.id
        JOIN subjects sub ON sub.id=e.subject_id
        {where_sql}
        ORDER BY st.full_name
    """, params)

    learner_ids = [row["id"] for row in cur.fetchall()]

    learner_data = []

    for student_id in learner_ids:

        cur.execute("""
            SELECT
                st.id,
                st.full_name,
                st.phone_whatsapp,
                st.grade,
                st.school,

                COUNT(DISTINCT e.subject_id) AS active_subjects,

                ROUND(AVG(arm.mark), 1) AS avg_report_mark,
                ROUND(AVG(aqm.mark), 1) AS avg_aqm_mark

            FROM students st
            JOIN enrollments e ON e.student_id=st.id
            LEFT JOIN academic_report_marks arm
                ON arm.student_id=st.id
               AND arm.month=?
            LEFT JOIN aqm_student_marks aqm
                ON aqm.student_id=st.id
               AND aqm.month=?
            WHERE st.id=?
              AND e.month=?
              AND e.status='ACTIVE'
            GROUP BY st.id
        """, (month, month, student_id, month))

        st = cur.fetchone()

        if not st:
            continue

        # Active subject IDs for this learner
        cur.execute("""
            SELECT DISTINCT subject_id
            FROM enrollments
            WHERE student_id=?
              AND month=?
              AND status='ACTIVE'
        """, (student_id, month))

        subject_ids = [str(x["subject_id"]) for x in cur.fetchall()]

        active_subjects = len(subject_ids)

        total_materials = 0
        viewed_materials = 0
        total_assignments = 0
        submitted_assignments = 0
        marked_assignments = 0
        due_assignments = 0
        overdue_assignments = 0
        total_attendance_sessions = 0
        attended_sessions = 0
        portal_seconds = 0

        high_risk_subjects = []
        improvement_notes = []

        if subject_ids:
            qmarks = ",".join("?" * len(subject_ids))

            # Materials uploaded for learner's active subjects
            cur.execute(f"""
                SELECT COUNT(DISTINCT id) AS c
                FROM materials
                WHERE subject_id IN ({qmarks})
                  AND month LIKE ?
            """, subject_ids + [month + "%"])

            total_materials = cur.fetchone()["c"] or 0

            # Materials viewed by learner
            cur.execute(f"""
                SELECT COUNT(DISTINCT mv.material_id) AS c
                FROM material_views mv
                JOIN materials m ON m.id=mv.material_id
                WHERE mv.student_id=?
                  AND m.subject_id IN ({qmarks})
                  AND m.month LIKE ?
            """, [student_id] + subject_ids + [month + "%"])

            viewed_materials = cur.fetchone()["c"] or 0

            # Assignment totals
            cur.execute(f"""
                SELECT COUNT(DISTINCT id) AS c
                FROM materials
                WHERE subject_id IN ({qmarks})
                  AND month LIKE ?
                  AND (is_assignment=1 OR kind='assignment')
            """, subject_ids + [month + "%"])

            total_assignments = cur.fetchone()["c"] or 0

            # Submitted assignments
            cur.execute(f"""
                SELECT COUNT(DISTINCT sub.id) AS c
                FROM submissions sub
                JOIN materials m ON m.id=sub.material_id
                WHERE sub.student_id=?
                  AND m.subject_id IN ({qmarks})
                  AND m.month LIKE ?
                  AND (m.is_assignment=1 OR m.kind='assignment')
            """, [student_id] + subject_ids + [month + "%"])

            submitted_assignments = cur.fetchone()["c"] or 0

            # Marked/published assignments
            cur.execute(f"""
                SELECT COUNT(DISTINCT sub.id) AS c
                FROM submissions sub
                JOIN materials m ON m.id=sub.material_id
                WHERE sub.student_id=?
                  AND m.subject_id IN ({qmarks})
                  AND m.month LIKE ?
                  AND (m.is_assignment=1 OR m.kind='assignment')
                  AND sub.is_published=1
                  AND (
                        sub.mark IS NOT NULL
                        OR sub.feedback IS NOT NULL
                        OR sub.marked_file_path IS NOT NULL
                  )
            """, [student_id] + subject_ids + [month + "%"])

            marked_assignments = cur.fetchone()["c"] or 0

            # Due but not submitted
            cur.execute(f"""
                SELECT COUNT(DISTINCT m.id) AS c
                FROM materials m
                LEFT JOIN submissions sub
                    ON sub.material_id=m.id
                   AND sub.student_id=?
                WHERE m.subject_id IN ({qmarks})
                  AND m.month LIKE ?
                  AND (m.is_assignment=1 OR m.kind='assignment')
                  AND m.due_date IS NOT NULL
                  AND TRIM(m.due_date) != ''
                  AND m.due_date >= ?
                  AND sub.id IS NULL
            """, [student_id] + subject_ids + [month + "%", today])

            due_assignments = cur.fetchone()["c"] or 0

            # Overdue and not submitted
            cur.execute(f"""
                SELECT COUNT(DISTINCT m.id) AS c
                FROM materials m
                LEFT JOIN submissions sub
                    ON sub.material_id=m.id
                   AND sub.student_id=?
                WHERE m.subject_id IN ({qmarks})
                  AND m.month LIKE ?
                  AND (m.is_assignment=1 OR m.kind='assignment')
                  AND m.due_date IS NOT NULL
                  AND TRIM(m.due_date) != ''
                  AND m.due_date < ?
                  AND sub.id IS NULL
            """, [student_id] + subject_ids + [month + "%", today])

            overdue_assignments = cur.fetchone()["c"] or 0

            # Attendance sessions expected
            cur.execute(f"""
                SELECT COUNT(DISTINCT ats.id) AS c
                FROM attendance_sessions ats
                WHERE ats.subject_id IN ({qmarks})
                  AND ats.month=?
            """, subject_ids + [month])

            total_attendance_sessions = cur.fetchone()["c"] or 0

            # Attendance sessions attended
            cur.execute(f"""
                SELECT COUNT(DISTINCT ats.id) AS c
                FROM attendance_sessions ats
                JOIN attendance a
                    ON a.session_id=ats.session_id
                   AND a.date=ats.date
                   AND a.student_id=?
                WHERE ats.subject_id IN ({qmarks})
                  AND ats.month=?
            """, [student_id] + subject_ids + [month])

            attended_sessions = cur.fetchone()["c"] or 0

            # Subject-level risk check
            for subject_id in subject_ids:
                cur.execute("""
                    SELECT name, grade
                    FROM subjects
                    WHERE id=?
                    LIMIT 1
                """, (subject_id,))

                subject = cur.fetchone()

                if not subject:
                    continue

                subject_label = f"{grade_label(subject['grade'])} {subject['name']}"

                cur.execute("""
                    SELECT COUNT(DISTINCT id) AS c
                    FROM materials
                    WHERE subject_id=?
                      AND month LIKE ?
                """, (subject_id, month + "%"))
                sm_total = cur.fetchone()["c"] or 0

                cur.execute("""
                    SELECT COUNT(DISTINCT mv.material_id) AS c
                    FROM material_views mv
                    JOIN materials m ON m.id=mv.material_id
                    WHERE mv.student_id=?
                      AND m.subject_id=?
                      AND m.month LIKE ?
                """, (student_id, subject_id, month + "%"))
                sm_viewed = cur.fetchone()["c"] or 0

                cur.execute("""
                    SELECT COUNT(DISTINCT id) AS c
                    FROM materials
                    WHERE subject_id=?
                      AND month LIKE ?
                      AND (is_assignment=1 OR kind='assignment')
                """, (subject_id, month + "%"))
                sa_total = cur.fetchone()["c"] or 0

                cur.execute("""
                    SELECT COUNT(DISTINCT sub.id) AS c
                    FROM submissions sub
                    JOIN materials m ON m.id=sub.material_id
                    WHERE sub.student_id=?
                      AND m.subject_id=?
                      AND m.month LIKE ?
                      AND (m.is_assignment=1 OR m.kind='assignment')
                """, (student_id, subject_id, month + "%"))
                sa_submitted = cur.fetchone()["c"] or 0

                cur.execute("""
                    SELECT COUNT(DISTINCT ats.id) AS c
                    FROM attendance_sessions ats
                    WHERE ats.subject_id=?
                      AND ats.month=?
                """, (subject_id, month))
                satt_total = cur.fetchone()["c"] or 0

                cur.execute("""
                    SELECT COUNT(DISTINCT ats.id) AS c
                    FROM attendance_sessions ats
                    JOIN attendance a
                        ON a.session_id=ats.session_id
                       AND a.date=ats.date
                       AND a.student_id=?
                    WHERE ats.subject_id=?
                      AND ats.month=?
                """, (student_id, subject_id, month))
                satt_present = cur.fetchone()["c"] or 0

                sm_rate = round((sm_viewed / sm_total) * 100) if sm_total else 100
                sa_rate = round((sa_submitted / sa_total) * 100) if sa_total else 100
                satt_rate = round((satt_present / satt_total) * 100) if satt_total else 100

                if sm_rate < 50 or sa_rate < 60 or satt_rate < 60:
                    high_risk_subjects.append(subject_label)

        # Portal activity
        cur.execute("""
            SELECT COALESCE(SUM(total_seconds),0) AS seconds
            FROM student_portal_activity
            WHERE student_id=?
              AND month=?
        """, (student_id, month))

        portal_seconds = cur.fetchone()["seconds"] or 0

        material_view_rate = round((viewed_materials / total_materials) * 100) if total_materials else 100
        assignment_completion_rate = round((submitted_assignments / total_assignments) * 100) if total_assignments else 100
        marking_rate = round((marked_assignments / submitted_assignments) * 100) if submitted_assignments else 0
        attendance_rate = round((attended_sessions / total_attendance_sessions) * 100) if total_attendance_sessions else 100

        # Overall academic progress score
        progress_parts = [
            material_view_rate,
            assignment_completion_rate,
            attendance_rate
        ]

        if submitted_assignments:
            progress_parts.append(marking_rate)

        overall_progress = round(sum(progress_parts) / len(progress_parts)) if progress_parts else 0

        risk_score = 0

        if material_view_rate < 50:
            risk_score += 1
            improvement_notes.append("View more learning materials")

        if assignment_completion_rate < 60:
            risk_score += 1
            improvement_notes.append("Submit outstanding assignments")

        if attendance_rate < 60:
            risk_score += 1
            improvement_notes.append("Improve class attendance")

        if overdue_assignments > 0:
            risk_score += 1
            improvement_notes.append("Overdue assignments need attention")

        if high_risk_subjects:
            risk_score += 1
            improvement_notes.append("Academic support needed in risk modules")

        if overall_progress >= 75 and risk_score == 0:
            progress_status = "GOOD"
            status_class = "active"
        elif overall_progress >= 50 and risk_score <= 2:
            progress_status = "WATCH"
            status_class = "pending"
        else:
            progress_status = "HIGH RISK"
            status_class = "lapsed"

        learner_data.append({
            "id": st["id"],
            "full_name": st["full_name"],
            "phone_whatsapp": st["phone_whatsapp"],
            "grade": st["grade"],
            "school": st["school"],
            "active_subjects": active_subjects,
            "avg_report_mark": st["avg_report_mark"],
            "avg_aqm_mark": st["avg_aqm_mark"],
            "total_materials": total_materials,
            "viewed_materials": viewed_materials,
            "material_view_rate": material_view_rate,
            "total_assignments": total_assignments,
            "submitted_assignments": submitted_assignments,
            "assignment_completion_rate": assignment_completion_rate,
            "marked_assignments": marked_assignments,
            "marking_rate": marking_rate,
            "due_assignments": due_assignments,
            "overdue_assignments": overdue_assignments,
            "attendance_rate": attendance_rate,
            "attended_sessions": attended_sessions,
            "total_attendance_sessions": total_attendance_sessions,
            "portal_minutes": round(portal_seconds / 60),
            "high_risk_subjects": high_risk_subjects,
            "risk_score": risk_score,
            "overall_progress": overall_progress,
            "progress_status": progress_status,
            "status_class": status_class,
            "improvement_notes": improvement_notes
        })

    # Optional progress filter
    if progress_filter:
        learner_data = [
            x for x in learner_data
            if x["progress_status"] == progress_filter
        ]

    total = len(learner_data)
    total_pages = max(1, (total + per_page - 1) // per_page)

    if page_num > total_pages:
        page_num = total_pages
        offset = (page_num - 1) * per_page

    learners = learner_data[offset:offset + per_page]

    # Summary values
    good_count = len([x for x in learner_data if x["progress_status"] == "GOOD"])
    watch_count = len([x for x in learner_data if x["progress_status"] == "WATCH"])
    risk_count = len([x for x in learner_data if x["progress_status"] == "HIGH RISK"])

    avg_progress = round(sum([x["overall_progress"] for x in learner_data]) / len(learner_data)) if learner_data else 0
    avg_material_views = round(sum([x["material_view_rate"] for x in learner_data]) / len(learner_data)) if learner_data else 0
    avg_assignment_completion = round(sum([x["assignment_completion_rate"] for x in learner_data]) / len(learner_data)) if learner_data else 0
    avg_attendance = round(sum([x["attendance_rate"] for x in learner_data]) / len(learner_data)) if learner_data else 0

    total_overdue = sum([x["overdue_assignments"] for x in learner_data])
    total_due = sum([x["due_assignments"] for x in learner_data])

    # Grade breakdown
    grade_map = {}

    for x in learner_data:
        g = grade_label(x["grade"])
        grade_map.setdefault(g, {"learners": 0, "progress_sum": 0, "risk": 0})
        grade_map[g]["learners"] += 1
        grade_map[g]["progress_sum"] += x["overall_progress"]

        if x["progress_status"] == "HIGH RISK":
            grade_map[g]["risk"] += 1

    grade_labels = []
    grade_progress = []
    grade_risk = []

    for g, values in sorted(grade_map.items()):
        grade_labels.append(g)
        grade_progress.append(round(values["progress_sum"] / values["learners"]) if values["learners"] else 0)
        grade_risk.append(values["risk"])

    rows = ""

    for l in learners:
        risk_modules = ", ".join(l["high_risk_subjects"][:3]) or "None"
        notes = ", ".join(l["improvement_notes"][:3]) or "On track"

        rows += f"""
        <tr>
            <td>
                <strong>{escape(l['full_name'] or '—')}</strong>
                <div class="mini muted">{escape(l['phone_whatsapp'] or '—')}</div>
                <div class="mini muted">School: {escape(l['school'] or '—')}</div>
            </td>

            <td>{grade_label(l['grade'])}</td>

            <td>
                <span class="chip {l['status_class']}">{escape(l['progress_status'])}</span>
                <div class="mini muted">Overall: {l['overall_progress']}%</div>
            </td>

            <td>
                {l['viewed_materials']} / {l['total_materials']}
                <div class="mini muted">{l['material_view_rate']}% viewed</div>
            </td>

            <td>
                {l['submitted_assignments']} / {l['total_assignments']}
                <div class="mini muted">{l['assignment_completion_rate']}% submitted</div>
            </td>

            <td>
                {l['marked_assignments']} marked
                <div class="mini muted">{l['marking_rate']}% marking feedback</div>
            </td>

            <td>
                {l['attendance_rate']}%
                <div class="mini muted">{l['attended_sessions']} / {l['total_attendance_sessions']} sessions</div>
            </td>

            <td>
                <span class="chip pending">Due: {l['due_assignments']}</span>
                <span class="chip lapsed">Overdue: {l['overdue_assignments']}</span>
            </td>

            <td>
                {l['portal_minutes']} min
                <div class="mini muted">Portal activity</div>
            </td>

            <td>
                <div class="mini"><strong>Risk modules:</strong> {escape(risk_modules)}</div>
                <div class="mini muted"><strong>Improve:</strong> {escape(notes)}</div>
            </td>
        </tr>
        """

    grade_options = '<option value="">All Grades</option>'

    for g in ["G8", "G9", "G10", "G11", "G12", "G13"]:
        selected = "selected" if grade == g else ""
        grade_options += f"<option value='{g}' {selected}>{grade_label(g)}</option>"

    progress_options = f"""
        <option value="" {'selected' if progress_filter == '' else ''}>All Progress Levels</option>
        <option value="GOOD" {'selected' if progress_filter == 'GOOD' else ''}>Good</option>
        <option value="WATCH" {'selected' if progress_filter == 'WATCH' else ''}>Watch</option>
        <option value="HIGH RISK" {'selected' if progress_filter == 'HIGH RISK' else ''}>High Risk</option>
    """

    chart_payload = {
        "progressMix": {
            "labels": ["Good", "Watch", "High Risk"],
            "values": [good_count, watch_count, risk_count]
        },
        "academicAreas": {
            "labels": ["Material Views", "Assignment Completion", "Attendance", "Overall Progress"],
            "values": [avg_material_views, avg_assignment_completion, avg_attendance, avg_progress]
        },
        "gradeProgress": {
            "labels": grade_labels,
            "progress": grade_progress,
            "risk": grade_risk
        },
        "workload": {
            "labels": ["Due Assignments", "Overdue Assignments"],
            "values": [total_due, total_overdue]
        }
    }

    chart_json = json.dumps(chart_payload)

    body = f"""
    {cao_nav()}

    <section class="card">
        <h1>Learner Academic Progress Analytics</h1>

        <p class="muted">
            This view uses the upgraded student academic progress data: material views, assignment completion,
            marked feedback, attendance rate, portal activity, pending work and high-risk modules.
        </p>

        <form method="get" class="toolbar">
            <input type="month" name="month" value="{escape(month)}">

            <input name="q"
                   value="{escape(q)}"
                   placeholder="Search learner, phone, school or subject">

            <select name="grade">
                {grade_options}
            </select>

            <select name="progress">
                {progress_options}
            </select>

            <button class="btn mini">Search</button>
            <a class="btn mini secondary" href="{url_for('cao_learner_performance')}">Clear</a>
        </form>

        <div class="stats" style="margin-top:12px">
            {stat("Learners Analysed", total)}
            {stat("Average Progress", f"{avg_progress}%")}
            {stat("Material View Rate", f"{avg_material_views}%")}
            {stat("Assignment Completion", f"{avg_assignment_completion}%")}
            {stat("Attendance Rate", f"{avg_attendance}%")}
            {stat("Good", good_count)}
            {stat("Watch", watch_count)}
            {stat("High Risk", risk_count)}
            {stat("Due Assignments", total_due)}
            {stat("Overdue Assignments", total_overdue)}
        </div>

        <div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:14px;margin-top:14px">

            <div class="card soft">
                <h2>Progress Status Mix</h2>
                <p class="mini muted">Good, watch and high-risk learner split.</p>
                <div style="height:280px">
                    <canvas id="caoProgressMixChart"></canvas>
                </div>
            </div>

            <div class="card soft">
                <h2>Academic Progress Areas</h2>
                <p class="mini muted">Average performance across the main progress areas.</p>
                <div style="height:280px">
                    <canvas id="caoAcademicAreasChart"></canvas>
                </div>
            </div>

        </div>

        <div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:14px;margin-top:14px">

            <div class="card soft">
                <h2>Progress by Grade</h2>
                <p class="mini muted">Average progress and high-risk learner count per grade.</p>
                <div style="height:320px">
                    <canvas id="caoGradeProgressChart"></canvas>
                </div>
            </div>

            <div class="card soft">
                <h2>Assignment Workload</h2>
                <p class="mini muted">Due versus overdue assignments.</p>
                <div style="height:320px">
                    <canvas id="caoWorkloadChart"></canvas>
                </div>
            </div>

        </div>

        <div class="card soft" style="margin-top:14px">
            <h2>Detailed Learner Progress Table</h2>

            <div class="mini muted" style="margin:10px 0">
                Showing {len(learners)} of {total} learner(s).
            </div>

            {pagination_controls("/cao/learner-performance", page_num, total_pages, {
                "month": month,
                "q": q,
                "grade": grade,
                "progress": progress_filter
            })}

            <div class="scroll-x">
                <table>
                    <thead>
                        <tr>
                            <th>Learner</th>
                            <th>Grade</th>
                            <th>Status</th>
                            <th>Materials</th>
                            <th>Assignments</th>
                            <th>Marked Feedback</th>
                            <th>Attendance</th>
                            <th>Pending Work</th>
                            <th>Portal Time</th>
                            <th>Risk / Improvement</th>
                        </tr>
                    </thead>

                    <tbody>
                        {rows or "<tr><td colspan='10'>No learner progress records found.</td></tr>"}
                    </tbody>
                </table>
            </div>

            {pagination_controls("/cao/learner-performance", page_num, total_pages, {
                "month": month,
                "q": q,
                "grade": grade,
                "progress": progress_filter
            })}
        </div>
    </section>

    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>

    <script>
        const learnerProgressCharts = {chart_json};

        const ebtaColors = [
            "#1b5e20",
            "#43a047",
            "#f59e0b",
            "#dc2626",
            "#64748b",
            "#0f172a"
        ];

        function noDataPlugin(message) {{
            return {{
                id: "noData_" + Math.random().toString(36).slice(2),
                afterDraw(chart) {{
                    const dataValues = chart.data.datasets.flatMap(ds => ds.data || []);
                    const hasData = dataValues.some(v => Number(v) > 0);

                    if (!hasData) {{
                        const ctx = chart.ctx;
                        ctx.save();
                        ctx.textAlign = "center";
                        ctx.textBaseline = "middle";
                        ctx.font = "13px Arial";
                        ctx.fillStyle = "#64748b";
                        ctx.fillText(message || "No data available", chart.width / 2, chart.height / 2);
                        ctx.restore();
                    }}
                }}
            }};
        }}

        const commonOptions = {{
            responsive: true,
            maintainAspectRatio: false,
            plugins: {{
                legend: {{
                    position: "bottom"
                }}
            }}
        }};

        new Chart(document.getElementById("caoProgressMixChart"), {{
            type: "doughnut",
            data: {{
                labels: learnerProgressCharts.progressMix.labels,
                datasets: [{{
                    data: learnerProgressCharts.progressMix.values,
                    backgroundColor: ["#1b5e20", "#f59e0b", "#dc2626"]
                }}]
            }},
            options: commonOptions,
            plugins: [noDataPlugin("No progress status data")]
        }});

        new Chart(document.getElementById("caoAcademicAreasChart"), {{
            type: "bar",
            data: {{
                labels: learnerProgressCharts.academicAreas.labels,
                datasets: [{{
                    label: "Average %",
                    data: learnerProgressCharts.academicAreas.values,
                    backgroundColor: "#1b5e20",
                    borderRadius: 10
                }}]
            }},
            options: {{
                ...commonOptions,
                plugins: {{
                    legend: {{
                        display: false
                    }}
                }},
                scales: {{
                    y: {{
                        beginAtZero: true,
                        max: 100,
                        ticks: {{
                            callback: function(value) {{
                                return value + "%";
                            }}
                        }}
                    }}
                }}
            }},
            plugins: [noDataPlugin("No academic progress data")]
        }});

        new Chart(document.getElementById("caoGradeProgressChart"), {{
            type: "bar",
            data: {{
                labels: learnerProgressCharts.gradeProgress.labels,
                datasets: [
                    {{
                        label: "Average Progress %",
                        data: learnerProgressCharts.gradeProgress.progress,
                        backgroundColor: "#1b5e20",
                        borderRadius: 8
                    }},
                    {{
                        label: "High Risk Learners",
                        data: learnerProgressCharts.gradeProgress.risk,
                        backgroundColor: "#dc2626",
                        borderRadius: 8
                    }}
                ]
            }},
            options: {{
                ...commonOptions,
                scales: {{
                    y: {{
                        beginAtZero: true,
                        ticks: {{
                            precision: 0
                        }}
                    }}
                }}
            }},
            plugins: [noDataPlugin("No grade progress data")]
        }});

        new Chart(document.getElementById("caoWorkloadChart"), {{
            type: "pie",
            data: {{
                labels: learnerProgressCharts.workload.labels,
                datasets: [{{
                    data: learnerProgressCharts.workload.values,
                    backgroundColor: ["#f59e0b", "#dc2626"]
                }}]
            }},
            options: commonOptions,
            plugins: [noDataPlugin("No due or overdue work")]
        }});
    </script>
    """

    conn.close()

    return page("CAO Learner Progress Analytics", body)
    
    
@app.get('/cao/attendance')
def cao_attendance():

    r = require_cao_permission("cao_attendance_enabled", "attendance trends")
    if r:
        return r

    month = cao_selected_month()
    q = request.args.get("q", "").strip()
    page_num = cao_page_num()

    per_page = 15
    offset = (page_num - 1) * per_page

    where = ["ats.month=?"]
    params = [month]

    if q:
        search = f"%{q}%"
        where.append("(t.full_name LIKE ? OR s.name LIKE ? OR s.grade LIKE ?)")
        params += [search, search, search]

    where_sql = "WHERE " + " AND ".join(where)

    conn = get_db()
    cur = conn.cursor()

    cur.execute(f"""
        SELECT COUNT(*) AS c
        FROM attendance_sessions ats
        JOIN tutors t ON t.id=ats.tutor_id
        JOIN subjects s ON s.id=ats.subject_id
        {where_sql}
    """, params)

    total = cur.fetchone()["c"] or 0
    total_pages = max(1, (total + per_page - 1) // per_page)

    data_params = list(params)
    data_params.extend([per_page, offset])

    cur.execute(f"""
        SELECT
            ats.*,
            t.full_name AS tutor_name,
            s.name AS subject_name,
            s.grade,
            COUNT(a.id) AS attendance_count
        FROM attendance_sessions ats
        JOIN tutors t ON t.id=ats.tutor_id
        JOIN subjects s ON s.id=ats.subject_id
        LEFT JOIN attendance a ON a.session_id=ats.session_id AND a.date=ats.date
        {where_sql}
        GROUP BY ats.id
        ORDER BY ats.date DESC
        LIMIT ? OFFSET ?
    """, data_params)

    att_rows = cur.fetchall()
    conn.close()

    rows = ""

    for a in att_rows:
        rows += f"""
        <tr>
            <td>{escape(a['date'])}</td>
            <td>{grade_label(a['grade'])}</td>
            <td>{escape(a['subject_name'])}</td>
            <td>{escape(a['tutor_name'])}</td>
            <td>{a['attendance_count'] or 0}</td>
            <td>{escape((a['created_at'] or '')[:16].replace('T',' '))}</td>
        </tr>
        """

    body = f"""
    {cao_nav()}

    <section class="card">
        <h1>Attendance Trends</h1>

        <form method="get" class="toolbar">
            <input type="month" name="month" value="{escape(month)}">
            <input name="q" value="{escape(q)}" placeholder="Search tutor, subject or grade">
            <button class="btn mini">Search</button>
            <a class="btn mini secondary" href="{url_for('cao_attendance')}">Clear</a>
        </form>

        <div class="mini muted" style="margin:10px 0">
            Showing {len(att_rows)} of {total} attendance session(s).
        </div>

        {pagination_controls("/cao/attendance", page_num, total_pages, {"month": month, "q": q})}

        <div class="scroll-x">
            <table>
                <thead>
                    <tr>
                        <th>Date</th>
                        <th>Grade</th>
                        <th>Subject</th>
                        <th>Tutor</th>
                        <th>Attendance Count</th>
                        <th>Logged</th>
                    </tr>
                </thead>
                <tbody>
                    {rows or "<tr><td colspan='6'>No attendance records found.</td></tr>"}
                </tbody>
            </table>
        </div>

        {pagination_controls("/cao/attendance", page_num, total_pages, {"month": month, "q": q})}
    </section>
    """

    return page("CAO Attendance", body)
   


@app.get('/cao/view-report/<int:rid>')
def cao_view_student_report(rid):

    r = require_cao_permission("cao_student_reports_enabled", "student reports")
    if r:
        return r

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT id, file_path, file_name
        FROM student_reports
        WHERE id=?
        LIMIT 1
    """, (rid,))

    row = cur.fetchone()
    conn.close()

    if not row:
        return page(
            "Report Not Found",
            f"""
            {cao_nav()}
            <section class="card">
                <h1>Report Not Found</h1>
                <p class="muted">The selected student report could not be found.</p>
                <a class="btn secondary" href="{url_for('cao_student_reports')}">Back to Student Reports</a>
            </section>
            """
        )

    raw_path = row["file_path"] or ""

    if not raw_path:
        return page(
            "Missing File Path",
            f"""
            {cao_nav()}
            <section class="card">
                <h1>Missing File Path</h1>
                <p class="muted">This report record exists, but no file path was saved.</p>
                <a class="btn secondary" href="{url_for('cao_student_reports')}">Back to Student Reports</a>
            </section>
            """
        )

    file_path = Path(raw_path)

    if not file_path.is_absolute():
        file_path = (Path(BASE_DATA_DIR) / raw_path).resolve()
    else:
        file_path = file_path.resolve()

    reports_root = REPORTS_DIR.resolve()

    if not str(file_path).startswith(str(reports_root)):
        return page(
            "Invalid Report Path",
            f"""
            {cao_nav()}
            <section class="card">
                <h1>Invalid Report Path</h1>
                <p class="muted">This report file is not inside the approved reports folder.</p>
                <a class="btn secondary" href="{url_for('cao_student_reports')}">Back to Student Reports</a>
            </section>
            """
        )

    if not file_path.exists():
        return page(
            "File Missing",
            f"""
            {cao_nav()}
            <section class="card">
                <h1>File Missing</h1>
                <p class="muted">
                    The report record exists, but the actual file is missing from storage.
                </p>
                <a class="btn secondary" href="{url_for('cao_student_reports')}">Back to Student Reports</a>
            </section>
            """
        )

    return send_from_directory(
        str(file_path.parent),
        file_path.name,
        as_attachment=False
    )
   
    
@app.get('/cao/student-reports')
def cao_student_reports():

    r = require_cao_permission("cao_student_reports_enabled", "student reports")
    if r:
        return r

    month = cao_selected_month()
    q = request.args.get("q", "").strip()
    grade = request.args.get("grade", "").strip()
    page_num = cao_page_num()

    per_page = 15
    offset = (page_num - 1) * per_page

    where = ["substr(sr.upload_date,1,7)=?"]
    params = [month]

    if q:
        search = f"%{q}%"
        where.append("(st.full_name LIKE ? OR st.phone_whatsapp LIKE ? OR sr.file_name LIKE ?)")
        params += [search, search, search]

    if grade:
        where.append("sr.grade=?")
        params.append(grade)

    where_sql = "WHERE " + " AND ".join(where)

    conn = get_db()
    cur = conn.cursor()

    cur.execute(f"""
        SELECT COUNT(*) AS c
        FROM student_reports sr
        JOIN students st ON st.id=sr.student_id
        {where_sql}
    """, params)

    total = cur.fetchone()["c"] or 0
    total_pages = max(1, (total + per_page - 1) // per_page)

    data_params = list(params)
    data_params.extend([per_page, offset])

    cur.execute(f"""
        SELECT
            sr.*,
            st.full_name,
            st.phone_whatsapp
        FROM student_reports sr
        JOIN students st ON st.id=sr.student_id
        {where_sql}
        ORDER BY sr.upload_date DESC
        LIMIT ? OFFSET ?
    """, data_params)

    reports = cur.fetchall()
    conn.close()

    rows = ""

    for r0 in reports:
        file_link = f"<a target='_blank' href='{url_for('cao_view_student_report', rid=r0['id'])}'>Open</a>" if r0["file_path"] else "—"

        rows += f"""
        <tr>
            <td>
                <strong>{escape(r0['full_name'])}</strong>
                <div class="mini muted">{escape(r0['phone_whatsapp'] or '—')}</div>
            </td>
            <td>{grade_label(r0['grade'] or '')}</td>
            <td>{escape(r0['term'] or '—')}</td>
            <td>{escape(r0['file_name'])}</td>
            <td>{escape(r0['file_type'])}</td>
            <td>{file_link}</td>
            <td>{escape((r0['upload_date'] or '')[:16].replace('T',' '))}</td>
        </tr>
        """

    grade_options = "".join([
        f"<option value='{g}' {'selected' if grade == g else ''}>{grade_label(g)}</option>"
        for g in ["G8","G9","G10","G11","G12","G13"]
    ])

    body = f"""
    {cao_nav()}

    <section class="card">
        <h1>Student Reports</h1>

        <form method="get" class="toolbar">
            <input type="month" name="month" value="{escape(month)}">
            <input name="q" value="{escape(q)}" placeholder="Search learner, phone or file">
            <select name="grade">
                <option value="">All Grades</option>
                {grade_options}
            </select>
            <button class="btn mini">Search</button>
            <a class="btn mini secondary" href="{url_for('cao_student_reports')}">Clear</a>
        </form>

        <div class="mini muted" style="margin:10px 0">
            Showing {len(reports)} of {total} report(s).
        </div>

        {pagination_controls("/cao/student-reports", page_num, total_pages, {"month": month, "q": q, "grade": grade})}

        <div class="scroll-x">
            <table>
                <thead>
                    <tr>
                        <th>Learner</th>
                        <th>Grade</th>
                        <th>Term</th>
                        <th>File</th>
                        <th>Type</th>
                        <th>Open</th>
                        <th>Uploaded</th>
                    </tr>
                </thead>
                <tbody>
                    {rows or "<tr><td colspan='7'>No student reports found.</td></tr>"}
                </tbody>
            </table>
        </div>

        {pagination_controls("/cao/student-reports", page_num, total_pages, {"month": month, "q": q, "grade": grade})}
    </section>
    """

    return page("CAO Student Reports", body)
    
    
@app.get('/cao/learner-movement')
def cao_learner_movement():

    r = require_cao_permission("cao_performance_enabled", "learner movement")
    if r:
        return r

    month = cao_selected_month()
    page_num = cao_page_num()

    per_page = 15
    offset = (page_num - 1) * per_page

    prev_month_dt = datetime.datetime.strptime(month + "-01", "%Y-%m-%d") - datetime.timedelta(days=1)
    prev_month = prev_month_dt.strftime("%Y-%m")

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT COUNT(DISTINCT student_id) AS c
        FROM enrollments
        WHERE month=? AND status='ACTIVE'
    """, (month,))
    active_now = cur.fetchone()["c"] or 0

    cur.execute("""
        SELECT COUNT(DISTINCT student_id) AS c
        FROM enrollments
        WHERE month=? AND status='ACTIVE'
    """, (prev_month,))
    active_prev = cur.fetchone()["c"] or 0

    cur.execute("""
        SELECT COUNT(DISTINCT e1.student_id) AS c
        FROM enrollments e1
        WHERE e1.month=? AND e1.status='ACTIVE'
          AND e1.student_id NOT IN (
              SELECT DISTINCT student_id FROM enrollments WHERE month=?
          )
    """, (prev_month, month))
    lost = cur.fetchone()["c"] or 0

    cur.execute("""
        SELECT COUNT(DISTINCT e1.student_id) AS c
        FROM enrollments e1
        WHERE e1.month=? AND e1.status='ACTIVE'
          AND e1.student_id IN (
              SELECT DISTINCT student_id FROM enrollments WHERE month=?
          )
    """, (month, prev_month))
    returning = cur.fetchone()["c"] or 0

    cur.execute("""
        SELECT COUNT(DISTINCT e.student_id) AS c
        FROM enrollments e
        JOIN students st ON st.id=e.student_id
        WHERE e.month=? AND e.status='ACTIVE'
          AND substr(st.created_at,1,7)=?
    """, (month, month))
    new_learners = cur.fetchone()["c"] or 0

    cur.execute("""
        SELECT COUNT(DISTINCT st.id) AS c
        FROM students st
        JOIN enrollments e ON e.student_id=st.id
        WHERE e.month=? AND e.status='ACTIVE'
    """, (month,))
    total = cur.fetchone()["c"] or 0

    total_pages = max(1, (total + per_page - 1) // per_page)

    cur.execute("""
        SELECT
            st.id,
            st.full_name,
            st.phone_whatsapp,
            st.grade,
            st.created_at,
            COUNT(DISTINCT e.subject_id) AS active_subjects,
            CASE
                WHEN substr(st.created_at,1,7)=? THEN 'NEW'
                WHEN st.id IN (SELECT DISTINCT student_id FROM enrollments WHERE month=? AND status='ACTIVE') THEN 'RETURNING'
                ELSE 'ACTIVE'
            END AS movement_status
        FROM students st
        JOIN enrollments e ON e.student_id=st.id
        WHERE e.month=? AND e.status='ACTIVE'
        GROUP BY st.id
        ORDER BY st.full_name
        LIMIT ? OFFSET ?
    """, (month, prev_month, month, per_page, offset))

    learners = cur.fetchall()
    conn.close()

    rows = ""

    for l in learners:
        rows += f"""
        <tr>
            <td>
                <strong>{escape(l['full_name'])}</strong>
                <div class="mini muted">{escape(l['phone_whatsapp'] or '—')}</div>
            </td>
            <td>{grade_label(l['grade'])}</td>
            <td>{l['active_subjects'] or 0}</td>
            <td>{cao_status_chip(l['movement_status'])}</td>
            <td>{escape((l['created_at'] or '')[:16].replace('T',' '))}</td>
        </tr>
        """

    body = f"""
    {cao_nav()}

    <section class="card">
        <h1>Learner Movement</h1>

        <form method="get" class="toolbar">
            <input type="month" name="month" value="{escape(month)}">
            <button class="btn mini">View Month</button>
        </form>

        <div class="stats" style="margin-top:12px">
            {stat("Current Month", month)}
            {stat("Previous Month", prev_month)}
            {stat("Active Now", active_now)}
            {stat("Active Previous Month", active_prev)}
            {stat("New Learners", new_learners)}
            {stat("Returning Learners", returning)}
            {stat("Learners Lost", lost)}
        </div>

        <div class="mini muted" style="margin:10px 0">
            Showing {len(learners)} of {total} active learner movement record(s).
        </div>

        {pagination_controls("/cao/learner-movement", page_num, total_pages, {"month": month})}

        <div class="scroll-x">
            <table>
                <thead>
                    <tr>
                        <th>Learner</th>
                        <th>Grade</th>
                        <th>Active Subjects</th>
                        <th>Movement</th>
                        <th>Joined</th>
                    </tr>
                </thead>
                <tbody>
                    {rows or "<tr><td colspan='5'>No learner movement records found.</td></tr>"}
                </tbody>
            </table>
        </div>

        {pagination_controls("/cao/learner-movement", page_num, total_pages, {"month": month})}
    </section>
    """

    return page("CAO Learner Movement", body)


