@app.post('/ceo/login')
def ceo_login_post():

    phone = request.form.get("phone", "").strip()
    pin = request.form.get("pin", "").strip()

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT *
        FROM ceos
        WHERE phone=?
          AND pin=?
          AND is_active=1
        LIMIT 1
    """, (phone, pin))

    ceo = cur.fetchone()
    conn.close()

    if not ceo:
        return page("Login Failed", card_msg("Invalid CEO login details or inactive account."))

    session.clear()
    session["ceo_id"] = ceo["id"]
    session["ceo_name"] = ceo["full_name"]

    return redirect(url_for("ceo_dashboard"))


@app.get('/ceo/logout')
def ceo_logout():

    session.pop("ceo_id", None)
    session.pop("ceo_name", None)

    return redirect(url_for("ceo_login"))
    
    
@app.get('/admin/ceos')
def admin_ceos():

    r = require_admin()
    if r:
        return r

    if not is_high_admin():
        return page("Access Denied", card_msg("Only High Admin can manage CEO accounts."))

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT *
        FROM ceos
        ORDER BY is_active DESC, full_name
    """)

    rows = cur.fetchall()
    conn.close()

    ceo_rows = ""

    for c in rows:
        status = "<span class='chip active'>Active</span>" if c["is_active"] == 1 else "<span class='chip lapsed'>Inactive</span>"
        form_id = f"ceo_edit_{c['id']}"

        ceo_rows += f"""
        <tr>
            <td>
                <input
                    form="{form_id}"
                    name="full_name"
                    value="{escape(c['full_name'] or '')}"
                    required
                    style="width:100%;min-width:170px;"
                >

                <div style="margin-top:6px;">
                    <input
                        form="{form_id}"
                        name="email"
                        value="{escape(c['email'] or '')}"
                        placeholder="Email"
                        style="width:100%;min-width:170px;"
                    >
                </div>
            </td>

            <td>
                <input
                    form="{form_id}"
                    name="phone"
                    value="{escape(c['phone'] or '')}"
                    required
                    style="width:150px;"
                >
            </td>

            <td>
                <input
                    form="{form_id}"
                    name="pin"
                    value="{escape(c['pin'] or '')}"
                    required
                    style="width:100px;"
                >
            </td>

            <td>{status}</td>

            <td style="white-space:nowrap;">
                <form
                    id="{form_id}"
                    method="post"
                    action="{url_for('admin_ceo_edit', ceo_id=c['id'])}"
                    style="display:inline"
                ></form>

                <button
                    form="{form_id}"
                    class="btn mini success"
                    onclick="return confirm('Save changes for this CEO account?')"
                >
                    Save
                </button>

                <form method="post" action="{url_for('admin_ceo_toggle', ceo_id=c['id'])}" style="display:inline">
                    <button class="btn mini secondary">
                        {'Deactivate' if c['is_active'] == 1 else 'Activate'}
                    </button>
                </form>

                <form method="post" action="{url_for('admin_ceo_reset_pin', ceo_id=c['id'])}" style="display:inline">
                    <button class="btn mini warn"
                            onclick="return confirm('Reset this CEO PIN?')">
                        Reset PIN
                    </button>
                </form>
            </td>
        </tr>
        """

    body = f"""
    {admin_nav()}

    <section class="card">
        <h1>CEO Management</h1>

        <div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:14px">

            <div class="card soft">
                <h2>Add CEO</h2>

                <form method="post" action="{url_for('admin_ceo_add')}">
                    <label>Full Name</label>
                    <input name="full_name" required>

                    <label>Phone</label>
                    <input name="phone" required>

                    <label>Email</label>
                    <input name="email">

                    <label>PIN</label>
                    <input name="pin" required>

                    <button class="btn success" style="margin-top:10px">
                        Add CEO
                    </button>
                </form>
            </div>

            <div class="card soft">
                <h2>Existing CEO Accounts</h2>

                <div class="scroll-x">
                    <table>
                        <thead>
                            <tr>
                                <th>CEO Details</th>
                                <th>Phone</th>
                                <th>PIN</th>
                                <th>Status</th>
                                <th>Actions</th>
                            </tr>
                        </thead>

                        <tbody>
                            {ceo_rows or "<tr><td colspan='5'>No CEO accounts yet.</td></tr>"}
                        </tbody>
                    </table>
                </div>
            </div>

        </div>
    </section>
    """

    return page("CEO Management", body)


@app.post('/admin/ceos/add')
def admin_ceo_add():

    r = require_admin()
    if r:
        return r

    if not is_high_admin():
        return page("Access Denied", card_msg("Only High Admin can add CEO accounts."))

    full_name = request.form.get("full_name", "").strip()
    phone = request.form.get("phone", "").strip()
    email = request.form.get("email", "").strip()
    pin = request.form.get("pin", "").strip()

    if not full_name or not phone or not pin:
        return page("Missing Information", card_msg("Full name, phone and PIN are required."))

    conn = get_db()
    cur = conn.cursor()

    try:
        cur.execute("""
            INSERT INTO ceos(
                full_name, phone, email, pin, is_active, created_at, updated_at
            )
            VALUES(?,?,?,?,?,?,?)
        """, (
            full_name,
            phone,
            email,
            pin,
            1,
            now_utc_iso(),
            now_utc_iso()
        ))

        conn.commit()

    except sqlite3.IntegrityError:
        conn.close()
        return page("Duplicate Phone", card_msg("A CEO account with this phone number already exists."))

    conn.close()

    return redirect(url_for("admin_ceos"))
    
    
