@app.get('/ceo')
def ceo_dashboard():

    r = require_ceo()
    if r:
        return r

    month = request.args.get("month") or get_setting("current_month")
    year = month[:4] if month else str(datetime.date.today().year)

    conn = get_db()
    cur = conn.cursor()

    # Operational
    cur.execute("SELECT COUNT(*) AS c FROM enrollments WHERE month=?", (month,))
    total_enrollments = cur.fetchone()["c"] or 0

    cur.execute("SELECT COUNT(*) AS c FROM enrollments WHERE month=? AND status='ACTIVE'", (month,))
    active_enrollments = cur.fetchone()["c"] or 0

    cur.execute("SELECT COUNT(*) AS c FROM enrollments WHERE month=? AND status='PENDING'", (month,))
    pending_enrollments = cur.fetchone()["c"] or 0

    cur.execute("SELECT COUNT(DISTINCT student_id) AS c FROM enrollments WHERE month=?", (month,))
    total_students = cur.fetchone()["c"] or 0

    # Academic
    cur.execute("SELECT COUNT(*) AS c FROM tutors")
    total_tutors = cur.fetchone()["c"] or 0

    cur.execute("SELECT COUNT(*) AS c FROM materials WHERE month LIKE ?", (month + "%",))
    academic_uploads = cur.fetchone()["c"] or 0

    cur.execute("SELECT COUNT(*) AS c FROM attendance_sessions WHERE month=?", (month,))
    attendance_logs = cur.fetchone()["c"] or 0

    cur.execute("SELECT COUNT(*) AS c FROM student_reports WHERE substr(upload_date,1,7)=?", (month,))
    student_reports = cur.fetchone()["c"] or 0

    # Finance
    cur.execute("""
        SELECT ROUND(SUM(
            COALESCE(e.amount_paid, 0) * 1.0 / (
                SELECT COUNT(*)
                FROM enrollments e2
                WHERE e2.student_id = e.student_id
                  AND e2.month = e.month
                  AND e2.status = 'ACTIVE'
            )
        ), 2) AS total
        FROM enrollments e
        WHERE e.month=?
          AND e.status='ACTIVE'
    """, (month,))
    total_income = float(cur.fetchone()["total"] or 0)

    cur.execute("""
        SELECT COALESCE(SUM(amount),0) AS total
        FROM finance_records
        WHERE month=? AND record_type='EXPENSE'
    """, (month,))
    total_expenses = float(cur.fetchone()["total"] or 0)

    net_position = total_income - total_expenses

    cur.execute("""
        SELECT COALESCE(SUM(amount),0) AS total
        FROM finance_payment_schedule
        WHERE month=? AND status='PENDING'
    """, (month,))
    pending_payments = float(cur.fetchone()["total"] or 0)

    # CEO reports
    cur.execute("""
        SELECT COUNT(*) AS c
        FROM ceo_monthly_reports
        WHERE report_month=?
    """, (month,))
    monthly_reports = cur.fetchone()["c"] or 0

    cur.execute("""
        SELECT COUNT(*) AS c
        FROM ceo_monthly_reports
        WHERE report_month=? AND status='SUBMITTED'
    """, (month,))
    reports_to_review = cur.fetchone()["c"] or 0

    # Risks and goals
    cur.execute("SELECT COUNT(*) AS c FROM ceo_risks WHERE status IN ('OPEN','IN_PROGRESS')")
    open_risks = cur.fetchone()["c"] or 0

    cur.execute("SELECT COUNT(*) AS c FROM ceo_risks WHERE risk_level IN ('HIGH','CRITICAL') AND status IN ('OPEN','IN_PROGRESS')")
    high_risks = cur.fetchone()["c"] or 0

    cur.execute("SELECT COUNT(*) AS c FROM ceo_goals WHERE target_year=? AND status IN ('PLANNED','IN_PROGRESS')", (year,))
    active_goals = cur.fetchone()["c"] or 0

    cur.execute("SELECT COUNT(*) AS c FROM ceo_awards_plans WHERE award_year=?", (year,))
    awards_plans = cur.fetchone()["c"] or 0

    # Chart breakdowns
    cur.execute("""
        SELECT status, COUNT(*) AS c
        FROM enrollments
        WHERE month=?
        GROUP BY status
    """, (month,))
    enrollment_status_rows = cur.fetchall()

    cur.execute("""
        SELECT risk_level, COUNT(*) AS c
        FROM ceo_risks
        WHERE status IN ('OPEN','IN_PROGRESS')
        GROUP BY risk_level
    """)
    risk_rows = cur.fetchall()

    cur.execute("""
        SELECT category, COALESCE(SUM(planned_amount),0) AS planned, COALESCE(SUM(actual_amount),0) AS actual
        FROM ceo_budget_plans
        WHERE budget_year=?
        GROUP BY category
        ORDER BY planned DESC
        LIMIT 8
    """, (year,))
    budget_rows = cur.fetchall()

    cur.execute("""
        SELECT submitted_by_role, COUNT(*) AS c
        FROM ceo_monthly_reports
        WHERE report_month=?
        GROUP BY submitted_by_role
    """, (month,))
    report_rows = cur.fetchall()

    conn.close()

    chart_payload = {
        "enrollmentStatus": {
            "labels": [r["status"] or "UNKNOWN" for r in enrollment_status_rows],
            "values": [r["c"] or 0 for r in enrollment_status_rows]
        },
        "finance": {
            "labels": ["Income", "Expenses", "Net Position", "Pending Payments"],
            "values": [total_income, total_expenses, net_position, pending_payments]
        },
        "academicOps": {
            "labels": ["Tutors", "Academic Uploads", "Attendance Logs", "Student Reports"],
            "values": [total_tutors, academic_uploads, attendance_logs, student_reports]
        },
        "risks": {
            "labels": [r["risk_level"] or "UNKNOWN" for r in risk_rows],
            "values": [r["c"] or 0 for r in risk_rows]
        },
        "budget": {
            "labels": [r["category"] for r in budget_rows],
            "planned": [float(r["planned"] or 0) for r in budget_rows],
            "actual": [float(r["actual"] or 0) for r in budget_rows]
        },
        "reports": {
            "labels": [r["submitted_by_role"] or "UNKNOWN" for r in report_rows],
            "values": [r["c"] or 0 for r in report_rows]
        }
    }

    chart_json = json.dumps(chart_payload)

    net_chip = "active" if net_position >= 0 else "lapsed"

    body = f"""
    {ceo_nav()}

    <section class="card">
        <h1>CEO Executive Dashboard</h1>

        <p class="muted">
            A simplified executive view of EBTA operations, academic activity, finance, risks,
            mitigations, goals, reports and awards planning.
        </p>

        <form method="get" class="toolbar">
            <input type="month" name="month" value="{escape(month)}">
            <button class="btn mini">View Month</button>
        </form>

        <div class="stats" style="margin-top:12px">
            {stat("Current Month", month)}
            {stat("Total Enrollments", total_enrollments)}
            {stat("Active Enrollments", active_enrollments)}
            {stat("Students", total_students)}
            {stat("Academic Uploads", academic_uploads)}
            {stat("Attendance Logs", attendance_logs)}
            {stat("Monthly Reports", monthly_reports)}
            {stat("Reports to Review", reports_to_review)}
            {stat("Income", f"R{total_income:,.2f}")}
            {stat("Expenses", f"R{total_expenses:,.2f}")}
            {stat("Net Position", f"R{net_position:,.2f}")}
            {stat("High Risks", high_risks)}
        </div>

        <div class="card soft" style="border-left:5px solid #1b5e20;margin-top:14px">
            <h2>Executive Snapshot</h2>

            <div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px">
                <div class="card soft">
                    <h3>Operations</h3>
                    <p class="muted">Enrollment and student activity for the month.</p>
                    <span class="chip active">{total_enrollments} enrollment record(s)</span>

                    <div style="margin-top:10px">
                        <a class="btn mini success"
                           href="{url_for('ceo_students')}?month={escape(month)}">
                            View Students
                        </a>
                    </div>
                </div>

                <div class="card soft">
                    <h3>Finance</h3>
                    <p class="muted">Income minus expenditure for the selected month.</p>
                    <span class="chip {net_chip}">Net: R{net_position:,.2f}</span>
                </div>

                <div class="card soft">
                    <h3>Risk & Mitigation</h3>
                    <p class="muted">Open risks requiring leadership attention.</p>
                    <span class="chip pending">{open_risks} open risk(s)</span>
                </div>

                <div class="card soft">
                    <h3>Goals & Awards</h3>
                    <p class="muted">Active yearly goals and awards preparation.</p>
                    <span class="chip">{active_goals} goal(s), {awards_plans} award plan(s)</span>
                </div>
            </div>
        </div>

        <div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:14px;margin-top:14px">
            <div class="card soft">
                <h2>Enrollment Status</h2>
                <div style="height:280px"><canvas id="ceoEnrollmentChart"></canvas></div>
            </div>

            <div class="card soft">
                <h2>Monthly Reports</h2>
                <div style="height:280px"><canvas id="ceoReportsChart"></canvas></div>
            </div>
        </div>

        <div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:14px;margin-top:14px">
            <div class="card soft">
                <h2>Finance Analysis</h2>
                <div style="height:320px"><canvas id="ceoFinanceChart"></canvas></div>
            </div>

            <div class="card soft">
                <h2>Academic & Operational Activity</h2>
                <div style="height:320px"><canvas id="ceoAcademicOpsChart"></canvas></div>
            </div>
        </div>

        <div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:14px;margin-top:14px">
            <div class="card soft">
                <h2>Risk Levels</h2>
                <div style="height:300px"><canvas id="ceoRisksChart"></canvas></div>
            </div>

            <div class="card soft">
                <h2>Yearly Budget Plan</h2>
                <div style="height:300px"><canvas id="ceoBudgetChart"></canvas></div>
            </div>
        </div>
    </section>

    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
    <script>
        const ceoCharts = {chart_json};

        const ebtaColors = [
            "#1b5e20", "#2e7d32", "#43a047", "#66bb6a",
            "#a5d6a7", "#f59e0b", "#64748b", "#0f172a"
        ];

        function moneyLabel(value) {{
            return "R" + Number(value || 0).toLocaleString("en-ZA", {{
                minimumFractionDigits: 2,
                maximumFractionDigits: 2
            }});
        }}

        function noDataPlugin(message) {{
            return {{
                id: "noData_" + Math.random().toString(36).slice(2),
                afterDraw(chart) {{
                    const values = chart.data.datasets.flatMap(ds => ds.data || []);
                    const hasData = values.some(v => Number(v) !== 0);

                    if (!hasData) {{
                        const ctx = chart.ctx;
                        ctx.save();
                        ctx.textAlign = "center";
                        ctx.textBaseline = "middle";
                        ctx.font = "13px Arial";
                        ctx.fillStyle = "#64748b";
                        ctx.fillText(message || "No data available", chart.width / 2, chart.height / 2);
                        ctx.restore();
                    }}
                }}
            }};
        }}

        const commonOptions = {{
            responsive:true,
            maintainAspectRatio:false,
            plugins: {{
                legend: {{
                    position:"bottom"
                }}
            }}
        }};

        new Chart(document.getElementById("ceoEnrollmentChart"), {{
            type:"doughnut",
            data: {{
                labels: ceoCharts.enrollmentStatus.labels,
                datasets:[{{ data: ceoCharts.enrollmentStatus.values, backgroundColor: ebtaColors }}]
            }},
            options: commonOptions,
            plugins:[noDataPlugin("No enrollment data yet")]
        }});

        new Chart(document.getElementById("ceoReportsChart"), {{
            type:"pie",
            data: {{
                labels: ceoCharts.reports.labels,
                datasets:[{{ data: ceoCharts.reports.values, backgroundColor: ebtaColors }}]
            }},
            options: commonOptions,
            plugins:[noDataPlugin("No CEO reports yet")]
        }});

        new Chart(document.getElementById("ceoFinanceChart"), {{
            type:"bar",
            data: {{
                labels: ceoCharts.finance.labels,
                datasets:[{{
                    label:"Amount",
                    data: ceoCharts.finance.values,
                    backgroundColor:"#1b5e20",
                    borderRadius:10
                }}]
            }},
            options: {{
                ...commonOptions,
                plugins: {{
                    legend: {{ display:false }},
                    tooltip: {{
                        callbacks: {{
                            label: function(context) {{
                                return moneyLabel(context.parsed.y || 0);
                            }}
                        }}
                    }}
                }},
                scales: {{
                    y: {{
                        ticks: {{
                            callback: function(value) {{
                                return moneyLabel(value);
                            }}
                        }}
                    }}
                }}
            }},
            plugins:[noDataPlugin("No finance data yet")]
        }});

        new Chart(document.getElementById("ceoAcademicOpsChart"), {{
            type:"bar",
            data: {{
                labels: ceoCharts.academicOps.labels,
                datasets:[{{
                    label:"Count",
                    data: ceoCharts.academicOps.values,
                    backgroundColor:"#2e7d32",
                    borderRadius:10
                }}]
            }},
            options: {{
                ...commonOptions,
                plugins: {{ legend: {{ display:false }} }},
                scales: {{
                    y: {{
                        beginAtZero:true,
                        ticks: {{ precision:0 }}
                    }}
                }}
            }},
            plugins:[noDataPlugin("No activity data yet")]
        }});

        new Chart(document.getElementById("ceoRisksChart"), {{
            type:"doughnut",
            data: {{
                labels: ceoCharts.risks.labels,
                datasets:[{{ data: ceoCharts.risks.values, backgroundColor: ebtaColors }}]
            }},
            options: commonOptions,
            plugins:[noDataPlugin("No risk data yet")]
        }});

        new Chart(document.getElementById("ceoBudgetChart"), {{
            type:"bar",
            data: {{
                labels: ceoCharts.budget.labels,
                datasets:[
                    {{
                        label:"Planned",
                        data: ceoCharts.budget.planned,
                        backgroundColor:"#1b5e20",
                        borderRadius:8
                    }},
                    {{
                        label:"Actual",
                        data: ceoCharts.budget.actual,
                        backgroundColor:"#f59e0b",
                        borderRadius:8
                    }}
                ]
            }},
            options: {{
                ...commonOptions,
                scales: {{
                    y: {{
                        beginAtZero:true,
                        ticks: {{
                            callback: function(value) {{
                                return moneyLabel(value);
                            }}
                        }}
                    }}
                }}
            }},
            plugins:[noDataPlugin("No budget data yet")]
        }});
    </script>
    """

    return page("CEO Dashboard", body)
    
    

@app.get('/ceo/students')
def ceo_students():
    r = require_ceo()
    if r:
        return r

    month = (
        request.args.get("month", "").strip()
        or get_setting("current_month")
    )
    q = request.args.get("q", "").strip()
    grade = request.args.get("grade", "").strip()
    status = request.args.get("status", "").strip()

    try:
        page_num = max(
            1,
            int(request.args.get("page", "1"))
        )
    except Exception:
        page_num = 1

    per_page = 20
    offset = (page_num - 1) * per_page

    where = ["1=1"]
    params = []

    if q:
        search = f"%{q}%"
        where.append("""
            (
                st.full_name LIKE ?
                OR st.phone_whatsapp LIKE ?
                OR st.guardian_name LIKE ?
                OR st.guardian_phone LIKE ?
                OR st.email LIKE ?
                OR st.school LIKE ?
                OR st.province LIKE ?
                OR sub.name LIKE ?
            )
        """)
        params.extend([search] * 8)

    if grade:
        where.append("st.grade=?")
        params.append(grade)

    if status == "NO_ENROLLMENT":
        where.append("""
            NOT EXISTS (
                SELECT 1
                FROM enrollments e2
                WHERE e2.student_id=st.id
                  AND e2.month=?
            )
        """)
        params.append(month)

    elif status:
        where.append("""
            EXISTS (
                SELECT 1
                FROM enrollments e2
                WHERE e2.student_id=st.id
                  AND e2.month=?
                  AND e2.status=?
            )
        """)
        params.extend([month, status])

    where_sql = "WHERE " + " AND ".join(where)

    conn = get_db()
    cur = conn.cursor()

    cur.execute(f"""
        SELECT COUNT(DISTINCT st.id) AS c
        FROM students st
        LEFT JOIN enrollments e
               ON e.student_id=st.id
              AND e.month=?
        LEFT JOIN subjects sub
               ON sub.id=e.subject_id
        {where_sql}
    """, [month] + params)

    total = int(cur.fetchone()["c"] or 0)
    total_pages = max(
        1,
        (total + per_page - 1) // per_page
    )

    if page_num > total_pages:
        page_num = total_pages
        offset = (page_num - 1) * per_page

    cur.execute(f"""
        SELECT
            st.id,
            st.full_name,
            st.phone_whatsapp,
            st.guardian_name,
            st.guardian_phone,
            st.email,
            st.grade,
            COALESCE(st.school,'') AS school,
            COALESCE(st.province,'') AS province,
            st.created_at,

            COUNT(DISTINCT e.id) AS enrollment_count,

            SUM(
                CASE WHEN e.status='ACTIVE'
                THEN 1 ELSE 0 END
            ) AS active_count,

            SUM(
                CASE WHEN e.status='PENDING'
                THEN 1 ELSE 0 END
            ) AS pending_count,

            SUM(
                CASE WHEN e.status='LAPSED'
                THEN 1 ELSE 0 END
            ) AS lapsed_count,

            GROUP_CONCAT(
                DISTINCT
                CASE
                    WHEN sub.id IS NOT NULL
                    THEN sub.grade || ' - ' || sub.name ||
                         ' (' || e.status || ')'
                    ELSE NULL
                END
            ) AS subjects_list

        FROM students st

        LEFT JOIN enrollments e
               ON e.student_id=st.id
              AND e.month=?

        LEFT JOIN subjects sub
               ON sub.id=e.subject_id

        {where_sql}

        GROUP BY st.id
        ORDER BY st.created_at DESC, st.full_name ASC
        LIMIT ? OFFSET ?
    """, [month] + params + [per_page, offset])

    rows = cur.fetchall()

    cur.execute("SELECT COUNT(*) AS c FROM students")
    all_students_total = int(
        cur.fetchone()["c"] or 0
    )

    cur.execute("""
        SELECT COUNT(DISTINCT student_id) AS c
        FROM enrollments
        WHERE month=?
    """, (month,))
    students_this_month = int(
        cur.fetchone()["c"] or 0
    )

    cur.execute("""
        SELECT COUNT(DISTINCT student_id) AS c
        FROM enrollments
        WHERE month=? AND status='ACTIVE'
    """, (month,))
    active_students = int(
        cur.fetchone()["c"] or 0
    )

    cur.execute("""
        SELECT COUNT(DISTINCT student_id) AS c
        FROM enrollments
        WHERE month=? AND status='PENDING'
    """, (month,))
    pending_students = int(
        cur.fetchone()["c"] or 0
    )

    conn.close()

    grade_options = ""

    for grade_value in (
        "G8", "G9", "G10",
        "G11", "G12", "G13"
    ):
        selected = (
            "selected"
            if grade == grade_value
            else ""
        )
        grade_options += f"""
        <option value="{grade_value}" {selected}>
            {grade_label(grade_value)}
        </option>
        """

    status_options = ""

    for status_value in (
        "ACTIVE",
        "PENDING",
        "LAPSED",
        "DECLINED",
        "NO_ENROLLMENT"
    ):
        selected = (
            "selected"
            if status == status_value
            else ""
        )

        status_label = (
            "No Enrollment This Month"
            if status_value == "NO_ENROLLMENT"
            else status_value
        )

        status_options += f"""
        <option value="{status_value}" {selected}>
            {status_label}
        </option>
        """

    trs = ""

    for student in rows:
        active_count = int(
            student["active_count"] or 0
        )
        pending_count = int(
            student["pending_count"] or 0
        )
        lapsed_count = int(
            student["lapsed_count"] or 0
        )
        enrollment_count = int(
            student["enrollment_count"] or 0
        )

        if active_count > 0:
            month_status = "ACTIVE"
        elif pending_count > 0:
            month_status = "PENDING"
        elif lapsed_count > 0:
            month_status = "LAPSED"
        elif enrollment_count > 0:
            month_status = "OTHER"
        else:
            month_status = "No Enrollment"

        if month_status == "No Enrollment":
            status_html = (
                "<span class='chip'>No Enrollment</span>"
            )
        else:
            status_html = coo_status_chip(
                month_status
            )

        subjects = (
            student["subjects_list"]
            or "No subjects for selected month"
        )

        trs += f"""
        <tr>
            <td>
                <strong>
                    {escape(student['full_name'] or '—')}
                </strong>
                <div class="mini muted">
                    Student ID: {student['id']}
                </div>
            </td>

            <td>
                <div>
                    {escape(student['phone_whatsapp'] or '—')}
                </div>
                <div class="mini muted">
                    {escape(student['email'] or '—')}
                </div>
            </td>

            <td>
                <div>
                    {escape(student['guardian_name'] or '—')}
                </div>
                <div class="mini muted">
                    {escape(student['guardian_phone'] or '—')}
                </div>
            </td>

            <td>
                {grade_label(student['grade'] or '')}
            </td>

            <td>
                <div>{escape(student['school'] or '—')}</div>
                <div class="mini muted">
                    {escape(student['province'] or '—')}
                </div>
            </td>

            <td>{status_html}</td>

            <td style="min-width:260px">
                {escape(subjects)}
            </td>
        </tr>
        """

    body = f"""
    {ceo_nav()}

    <section class="card">
        <div style="
            display:flex;
            justify-content:space-between;
            align-items:flex-start;
            gap:12px;
            flex-wrap:wrap
        ">
            <div>
                <h1>Students</h1>
                <p class="muted">
                    View learner records and enrollment activity for
                    {pretty_month_label(month)}.
                </p>
            </div>

            <span class="chip active">
                CEO View
            </span>
        </div>

        <form method="get"
              class="toolbar"
              style="margin-top:12px">

            <input type="month"
                   name="month"
                   value="{escape(month)}">

            <input name="q"
                   value="{escape(q)}"
                   placeholder="Search student, phone, guardian, email, school or subject">

            <select name="grade">
                <option value="">All Grades</option>
                {grade_options}
            </select>

            <select name="status">
                <option value="">All Month Statuses</option>
                {status_options}
            </select>

            <button class="btn mini">Search</button>

            <a class="btn mini secondary"
               href="{url_for('ceo_students')}">
                Clear
            </a>
        </form>

        <div class="card soft"
             style="border-left:5px solid #1b5e20;margin-top:14px">
            <h2>Compare & Export</h2>

            <p class="mini muted">
                Compare learner movement between two months and download the Excel file.
            </p>

            <form method="get"
                  action="{url_for('ceo_students_compare_export')}"
                  style="display:flex;gap:8px;align-items:end;flex-wrap:wrap">

                <div>
                    <label>Previous</label>
                    <input type="month"
                           name="prev"
                           required>
                </div>

                <div>
                    <label>Current</label>
                    <input type="month"
                           name="curr"
                           required>
                </div>

                <button class="btn success mini">
                    Compare & Export
                </button>
            </form>
        </div>

        <div class="stats" style="margin-top:14px">
            {stat("All Students", all_students_total)}
            {stat("Students This Month", students_this_month)}
            {stat("Active Students", active_students)}
            {stat("Pending Students", pending_students)}
            {stat("Filtered Results", total)}
        </div>

        <div class="mini muted" style="margin:10px 0">
            Showing {len(rows)} of {total} student(s).
        </div>

        {pagination_controls(
            "/ceo/students",
            page_num,
            total_pages,
            {
                "month": month,
                "q": q,
                "grade": grade,
                "status": status
            }
        )}

        <div class="scroll-x">
            <table>
                <thead>
                    <tr>
                        <th>Student</th>
                        <th>Contact</th>
                        <th>Guardian</th>
                        <th>Grade</th>
                        <th>School</th>
                        <th>Month Status</th>
                        <th>Subjects for Month</th>
                    </tr>
                </thead>

                <tbody>
                    {
                        trs
                        or
                        "<tr><td colspan='7'>No students found.</td></tr>"
                    }
                </tbody>
            </table>
        </div>

        {pagination_controls(
            "/ceo/students",
            page_num,
            total_pages,
            {
                "month": month,
                "q": q,
                "grade": grade,
                "status": status
            }
        )}
    </section>
    """

    return page("CEO Students", body)


