@app.get('/admin/analytics/export')
@require_high_admin
def admin_analytics_export():

    r = require_admin()
    if r:
        return r

    try:
        from openpyxl import Workbook
        from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
        from openpyxl.utils import get_column_letter
    except Exception:
        return page(
            "Export Error",
            card_msg("openpyxl is not installed. Please add openpyxl to requirements.txt and redeploy.")
        )

    month = request.args.get("month", "").strip() or get_admin_active_month()
    data = admin_analytics_data(month)
    summary = data["summary"]

    wb = Workbook()

    header_fill = PatternFill("solid", fgColor="166534")
    title_fill = PatternFill("solid", fgColor="1B5E20")
    white_font = Font(color="FFFFFF", bold=True)
    thin = Side(border_style="thin", color="CBD5E1")

    def style_sheet(ws):
        for row in ws.iter_rows():
            for cell in row:
                cell.alignment = Alignment(vertical="top", wrap_text=True)
                cell.border = Border(top=thin, left=thin, right=thin, bottom=thin)

        for col in range(1, ws.max_column + 1):
            ws.column_dimensions[get_column_letter(col)].width = 22

    def write_title(ws, title, last_col):
        ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=last_col)
        cell = ws.cell(row=1, column=1)
        cell.value = title
        cell.font = Font(size=14, bold=True, color="FFFFFF")
        cell.fill = title_fill
        cell.alignment = Alignment(horizontal="center")

    def write_headers(ws, headers, row_num=3):
        for col, header in enumerate(headers, start=1):
            cell = ws.cell(row=row_num, column=col)
            cell.value = header
            cell.font = white_font
            cell.fill = header_fill
            cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)

    # ================= SUMMARY SHEET =================
    ws = wb.active
    ws.title = "Summary"

    summary_headers = ["Metric", pretty_month_label(summary["prev_month"]), pretty_month_label(month), "Change", "Change %"]
    write_title(ws, f"High Admin Analytics Summary - {pretty_month_label(month)}", len(summary_headers))
    write_headers(ws, summary_headers)

    summary_rows = [
        ["Revenue", summary["previous_revenue"], summary["revenue"], summary["revenue_change"], summary["revenue_change_pct"]],
        ["Enrollments", summary["previous_enrollments"], summary["total_enrollments"], summary["enrollment_change"], summary["enrollment_change_pct"]],
        ["Active Enrollments", summary["previous_active"], summary["active"], summary["active_change"], summary["active_change_pct"]],
        ["Unique Students", summary["previous_unique_students"], summary["unique_students"], summary["unique_student_change"], summary["unique_student_change_pct"]],
        ["Pending", "", summary["pending"], "", ""],
        ["Lapsed", "", summary["lapsed"], "", ""],
        ["New Students", "", summary["new_students"], "", ""],
        ["Returning Students", "", summary["returning_students"], "", ""]
    ]

    for r_idx, row in enumerate(summary_rows, start=4):
        for c_idx, value in enumerate(row, start=1):
            ws.cell(row=r_idx, column=c_idx).value = value

    style_sheet(ws)

    # ================= MONTHLY TREND SHEET =================
    ws = wb.create_sheet("Monthly Trend")
    headers = ["Month", "Revenue", "Enrollments", "Active", "Unique Students", "New Students", "Returning Students", "Pending", "Lapsed"]
    write_title(ws, "Previous 3 Months Trend", len(headers))
    write_headers(ws, headers)

    for r_idx, row in enumerate(data["monthly_trend"], start=4):
        values = [
            row["month"],
            row["revenue"],
            row["enrollments"],
            row["active"],
            row["unique_students"],
            row["new_students"],
            row["returning_students"],
            row["pending"],
            row["lapsed"]
        ]

        for c_idx, value in enumerate(values, start=1):
            ws.cell(row=r_idx, column=c_idx).value = value

    style_sheet(ws)

    # ================= SUBJECT COMPARISON SHEET =================
    ws = wb.create_sheet("Subject Comparison")
    headers = [
        "Subject",
        "Previous Active",
        "Current Active",
        "Active Difference",
        "Previous Revenue",
        "Current Revenue",
        "Revenue Difference"
    ]

    write_title(ws, "Subject Comparison", len(headers))
    write_headers(ws, headers)

    for r_idx, row in enumerate(data["subject_comparison"], start=4):
        values = [
            row["subject"],
            row["previous_active"],
            row["current_active"],
            row["active_difference"],
            row["previous_revenue"],
            row["current_revenue"],
            row["revenue_difference"]
        ]

        for c_idx, value in enumerate(values, start=1):
            ws.cell(row=r_idx, column=c_idx).value = value

    style_sheet(ws)

    # ================= CRITICAL DECLINE SHEET =================
    ws = wb.create_sheet("Critical Decline")
    headers = [
        "Subject",
        summary["month_3"],
        summary["month_2"],
        summary["prev_month"],
        summary["month"]
    ]

    write_title(ws, "Critical 4-Month Decline", len(headers))
    write_headers(ws, headers)

    for r_idx, row in enumerate(data["critical_decline"], start=4):
        values = [
            row["subject"],
            row.get(summary["month_3"], 0),
            row.get(summary["month_2"], 0),
            row.get(summary["prev_month"], 0),
            row.get(summary["month"], 0)
        ]

        for c_idx, value in enumerate(values, start=1):
            ws.cell(row=r_idx, column=c_idx).value = value

    style_sheet(ws)

    # ================= DAILY REVENUE SHEET =================
    ws = wb.create_sheet("Daily Revenue")
    headers = ["Day", "Revenue"]
    write_title(ws, "Daily Revenue", len(headers))
    write_headers(ws, headers)

    for r_idx, row in enumerate(data["revenue_daily"], start=4):
        ws.cell(row=r_idx, column=1).value = row["day"]
        ws.cell(row=r_idx, column=2).value = row["revenue"]

    style_sheet(ws)

    # ================= ATTENDANCE SHEET =================
    ws = wb.create_sheet("Attendance")
    headers = ["Day", "Attendance Records"]
    write_title(ws, "Daily Attendance", len(headers))
    write_headers(ws, headers)

    for r_idx, row in enumerate(data["attendance_daily"], start=4):
        ws.cell(row=r_idx, column=1).value = row["day"]
        ws.cell(row=r_idx, column=2).value = row["attendance_count"]

    style_sheet(ws)

    # ================= TOP TUTORS SHEET =================
    ws = wb.create_sheet("Tutor Ratings")
    headers = ["Tutor", "Average Rating", "Number of Ratings"]
    write_title(ws, "Top Tutor Ratings", len(headers))
    write_headers(ws, headers)

    for r_idx, row in enumerate(data["top_tutors"], start=4):
        ws.cell(row=r_idx, column=1).value = row["full_name"]
        ws.cell(row=r_idx, column=2).value = row["avg_rating"]
        ws.cell(row=r_idx, column=3).value = row["rating_count"]

    style_sheet(ws)

    # ================= MANAGER RATINGS SHEET =================
    ws = wb.create_sheet("Manager Ratings")
    headers = ["Tutor Manager", "Average Rating", "Number of Ratings"]
    write_title(ws, "Tutor Manager Ratings", len(headers))
    write_headers(ws, headers)

    for r_idx, row in enumerate(data["manager_ratings"], start=4):
        ws.cell(row=r_idx, column=1).value = row["full_name"]
        ws.cell(row=r_idx, column=2).value = row["avg_rating"]
        ws.cell(row=r_idx, column=3).value = row["rating_count"]

    style_sheet(ws)

    # Freeze panes and filters
    for sheet in wb.worksheets:
        sheet.freeze_panes = "A4"

        if sheet.max_row >= 3 and sheet.max_column >= 1:
            sheet.auto_filter.ref = f"A3:{get_column_letter(sheet.max_column)}{sheet.max_row}"

    output = io.BytesIO()
    wb.save(output)
    output.seek(0)

    safe_month = month.replace("-", "_")
    filename = f"High_Admin_Analytics_{safe_month}.xlsx"

    return send_file(
        output,
        as_attachment=True,
        download_name=filename,
        mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    )

    
ASSESSMENT_ALLOWED_EXTENSIONS = {
    "jpg", "jpeg", "png", "gif", "webp",
    "pdf",
    "doc", "docx",
    "ppt", "pptx",
    "xls", "xlsx",
    "txt", "csv",
    "zip"
}

def clean_upload_filename(filename):
    filename = os.path.basename(filename or "").strip()
    filename = filename.replace(" ", "_")

    safe = ""

    for ch in filename:
        if ch.isalnum() or ch in ["_", "-", "."]:
            safe += ch

    return safe or f"file_{secrets.token_hex(6)}"


def assessment_file_allowed(filename):
    if not filename or "." not in filename:
        return False

    ext = filename.rsplit(".", 1)[-1].lower()
    return ext in ASSESSMENT_ALLOWED_EXTENSIONS


def save_assessment_upload(file_obj, folder_name):
    """
    Saves assessment-related uploads safely.
    folder_name examples:
    - tutor_questions
    - student_answers
    """

    if not file_obj or not file_obj.filename:
        return None

    original_name = clean_upload_filename(file_obj.filename)

    if not assessment_file_allowed(original_name):
        return None

    target_dir = ASSESSMENT_FILES_DIR / folder_name
    target_dir.mkdir(parents=True, exist_ok=True)

    ext = original_name.rsplit(".", 1)[-1].lower()
    stored_name = f"{secrets.token_hex(12)}.{ext}"
    stored_path = target_dir / stored_name

    file_obj.save(stored_path)

    return {
        "file_path": str(stored_path),
        "file_name": original_name,
        "file_type": ext
    }    
    
    
def assessment_status_chip(status):
    status = (status or "").upper()

    if status == "MARKED":
        return "<span class='chip active'>Marked</span>"

    if status == "SUBMITTED":
        return "<span class='chip pending'>Submitted</span>"

    if status == "IN_PROGRESS":
        return "<span class='chip'>In Progress</span>"

    return f"<span class='chip'>{escape(status or 'Unknown')}</span>"


def assessment_is_open(assessment):
    """
    Checks if assessment is currently open using South African local time.
    """
    now = datetime.datetime.now(ZoneInfo("Africa/Johannesburg")).replace(tzinfo=None)

    opens_at = assessment["opens_at"]
    closes_at = assessment["closes_at"]

    if opens_at:
        try:
            open_dt = datetime.datetime.fromisoformat(opens_at).replace(tzinfo=None)
            if now < open_dt:
                return False
        except Exception:
            pass

    if closes_at:
        try:
            close_dt = datetime.datetime.fromisoformat(closes_at).replace(tzinfo=None)
            if now > close_dt:
                return False
        except Exception:
            pass

    return True


def student_can_access_assessment(student_id, assessment_id):
    """
    Student can only access assessments for active enrolled subjects.
    """
    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT 1
        FROM assessments a
        JOIN enrollments e ON e.subject_id = a.subject_id
        WHERE a.id=?
          AND e.student_id=?
          AND e.status='ACTIVE'
          AND e.month = a.month
          AND a.is_published=1
        LIMIT 1
    """, (assessment_id, student_id))

    allowed = cur.fetchone() is not None

    conn.close()
    return allowed


def tutor_owns_assessment(tutor_id, assessment_id):
    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT 1
        FROM assessments
        WHERE id=?
          AND tutor_id=?
        LIMIT 1
    """, (assessment_id, tutor_id))

    allowed = cur.fetchone() is not None

    conn.close()
    return allowed
    
def assessment_delete_lock_reason(tutor_id, subject_id):
    """
    Returns a lock reason if the tutor is not allowed to delete assessments
    for the selected tutor/subject combination.
    Returns None if deletion is allowed.
    """

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT grade
        FROM subjects
        WHERE id=?
        LIMIT 1
    """, (subject_id,))

    subject = cur.fetchone()

    grade = subject["grade"] if subject else ""

    # 1. All subjects locked
    cur.execute("""
        SELECT reason
        FROM assessment_delete_locks
        WHERE is_active=1
          AND lock_scope='ALL'
        ORDER BY id DESC
        LIMIT 1
    """)

    row = cur.fetchone()

    if row:
        conn.close()
        return row["reason"] or "Assessment deletion is locked for all subjects."

    # 2. Specific tutor + subject locked
    cur.execute("""
        SELECT reason
        FROM assessment_delete_locks
        WHERE is_active=1
          AND lock_scope='TUTOR_SUBJECT'
          AND tutor_id=?
          AND subject_id=?
        ORDER BY id DESC
        LIMIT 1
    """, (tutor_id, subject_id))

    row = cur.fetchone()

    if row:
        conn.close()
        return row["reason"] or "Assessment deletion is locked for this tutor and subject."

    # 3. Specific subject locked
    cur.execute("""
        SELECT reason
        FROM assessment_delete_locks
        WHERE is_active=1
          AND lock_scope='SUBJECT'
          AND subject_id=?
        ORDER BY id DESC
        LIMIT 1
    """, (subject_id,))

    row = cur.fetchone()

    if row:
        conn.close()
        return row["reason"] or "Assessment deletion is locked for this subject."

    # 4. Grade locked
    cur.execute("""
        SELECT reason
        FROM assessment_delete_locks
        WHERE is_active=1
          AND lock_scope='GRADE'
          AND grade=?
        ORDER BY id DESC
        LIMIT 1
    """, (grade,))

    row = cur.fetchone()

    conn.close()

    if row:
        return row["reason"] or f"Assessment deletion is locked for {grade_label(grade)}."

    return None


def assessment_attempt_count(conn, assessment_id):
    cur = conn.cursor()

    cur.execute("""
        SELECT COUNT(*) AS c
        FROM assessment_attempts
        WHERE assessment_id=?
    """, (assessment_id,))

    return cur.fetchone()["c"] or 0


def assessment_total_points(conn, assessment_id):
    cur = conn.cursor()

    cur.execute("""
        SELECT COALESCE(SUM(points),0) AS total
        FROM assessment_questions
        WHERE assessment_id=?
    """, (assessment_id,))

    return float(cur.fetchone()["total"] or 0)
    
    
def recalculate_assessment_attempt_totals(conn, attempt_id):
    """
    Recalculates the correct total marks for an assessment attempt
    based on the points set by the tutor on each question.
    """

    cur = conn.cursor()

    cur.execute("""
        SELECT assessment_id
        FROM assessment_attempts
        WHERE id=?
        LIMIT 1
    """, (attempt_id,))

    attempt = cur.fetchone()

    if not attempt:
        return 0

    assessment_id = attempt["assessment_id"]

    cur.execute("""
        SELECT COALESCE(SUM(points), 0) AS total_points
        FROM assessment_questions
        WHERE assessment_id=?
    """, (assessment_id,))

    total_points = float(cur.fetchone()["total_points"] or 0)

    cur.execute("""
        UPDATE assessment_attempts
        SET total_points=?
        WHERE id=?
    """, (total_points, attempt_id))

    return total_points


def parse_datetime_local(value):
    """
    Converts datetime-local input to ISO string.
    Empty values stay None.
    """
    value = (value or "").strip()

    if not value:
        return None

    try:
        return datetime.datetime.fromisoformat(value).isoformat()
    except Exception:
        return value    

