@app.post('/tutor/assessments/new')
def tutor_create_assessment():

    r = require_tutor()
    if r:
        return r

    tid = is_tutor()

    subject_id = request.form.get("subject_id", "").strip()
    month = request.form.get("month", "").strip()
    title = request.form.get("title", "").strip()
    description = request.form.get("description", "").strip()
    instructions = request.form.get("instructions", "").strip()

    try:
        duration_minutes = int(request.form.get("duration_minutes", 30))
    except Exception:
        duration_minutes = 30

    if duration_minutes < 5:
        duration_minutes = 5
        
    try:
        max_attempts = int(request.form.get("max_attempts", 1))
    except Exception:
        max_attempts = 1

    if max_attempts < 1:
        max_attempts = 1

    if max_attempts > 10:
        max_attempts = 10

    opens_at = parse_datetime_local(request.form.get("opens_at"))
    closes_at = parse_datetime_local(request.form.get("closes_at"))

    shuffle_questions = 1 if request.form.get("shuffle_questions") else 0
    lockdown_required = 1 if request.form.get("lockdown_required") else 0
    show_results = 1 if request.form.get("show_results") else 0

    if not subject_id or not month or not title:
        return page("Error", card_msg("Subject, month and title are required."))

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT 1
        FROM tutor_subjects
        WHERE tutor_id=? AND subject_id=?
        LIMIT 1
    """, (tid, subject_id))

    if not cur.fetchone():
        conn.close()
        return page("Error", card_msg("This subject is not assigned to you."))

    cur.execute("""
        INSERT INTO assessments(
            subject_id,
            tutor_id,
            month,
            title,
            description,
            instructions,
            duration_minutes,
            max_attempts,
            opens_at,
            closes_at,
            shuffle_questions,
            show_results,
            lockdown_required,
            created_at,
            updated_at
        )
        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
    """, (
        subject_id,
        tid,
        month,
        title,
        description,
        instructions,
        duration_minutes,
        max_attempts,
        opens_at,
        closes_at,
        shuffle_questions,
        show_results,
        lockdown_required,
        now_utc_iso(),
        now_utc_iso()
    ))

    assessment_id = cur.lastrowid

    conn.commit()
    conn.close()

    return redirect(url_for("tutor_assessment_builder", assessment_id=assessment_id))
    
    
