@app.post('/tutor/assessments/<int:assessment_id>/edit')
def tutor_update_assessment(assessment_id):

    r = require_tutor()
    if r:
        return r

    tid = is_tutor()

    title = request.form.get("title", "").strip()
    description = request.form.get("description", "").strip()
    instructions = request.form.get("instructions", "").strip()

    try:
        duration_minutes = int(request.form.get("duration_minutes", 30))
    except Exception:
        duration_minutes = 30

    if duration_minutes < 5:
        duration_minutes = 5

    if duration_minutes > 240:
        duration_minutes = 240
        
    try:
        max_attempts = int(request.form.get("max_attempts", 1))
    except Exception:
        max_attempts = 1

    if max_attempts < 1:
        max_attempts = 1

    if max_attempts > 10:
        max_attempts = 10

    opens_at = parse_datetime_local(request.form.get("opens_at"))
    closes_at = parse_datetime_local(request.form.get("closes_at"))

    shuffle_questions = 1 if request.form.get("shuffle_questions") else 0
    lockdown_required = 1 if request.form.get("lockdown_required") else 0
    show_results = 1 if request.form.get("show_results") else 0

    if not title:
        return page("Error", card_msg("Assessment title is required."))

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT id
        FROM assessments
        WHERE id=?
          AND tutor_id=?
        LIMIT 1
    """, (assessment_id, tid))

    if not cur.fetchone():
        conn.close()
        return page("Not Found", card_msg("Assessment not found or not owned by you."))

    cur.execute("""
        UPDATE assessments
        SET title=?,
            description=?,
            instructions=?,
            duration_minutes=?,
            max_attempts=?,
            opens_at=?,
            closes_at=?,
            shuffle_questions=?,
            show_results=?,
            lockdown_required=?,
            updated_at=?
        WHERE id=?
          AND tutor_id=?
    """, (
        title,
        description,
        instructions,
        duration_minutes,
        max_attempts,
        opens_at,
        closes_at,
        shuffle_questions,
        show_results,
        lockdown_required,
        now_utc_iso(),
        assessment_id,
        tid
    ))

    conn.commit()
    conn.close()

    return redirect(url_for("tutor_assessment_builder", assessment_id=assessment_id))
    
   
@app.get('/tutor/assessments/<int:assessment_id>/builder')
def tutor_assessment_builder(assessment_id):

    r = require_tutor()
    if r:
        return r

    tid = is_tutor()

    if not tutor_owns_assessment(tid, assessment_id):
        return page("Access Denied", card_msg("You cannot manage this assessment."))

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT a.*, s.name AS subject_name, s.grade
        FROM assessments a
        JOIN subjects s ON s.id=a.subject_id
        WHERE a.id=?
    """, (assessment_id,))

    a = cur.fetchone()

    cur.execute("""
        SELECT *
        FROM assessment_questions
        WHERE assessment_id=?
        ORDER BY question_order ASC, id ASC
    """, (assessment_id,))

    questions = cur.fetchall()

    attempts = assessment_attempt_count(conn, assessment_id)
    lock_reason = assessment_delete_lock_reason(tid, a["subject_id"])

    conn.close()

    question_rows = ""

    for q in questions:
        options_html = ""

        if q["question_type"] == "MCQ":
            try:
                options = json.loads(q["options_json"] or "[]")
            except Exception:
                options = []

            option_lines = []

            for i, opt in enumerate(options):
                correct = "✅" if q["correct_index"] == i else ""
                option_lines.append(f"{chr(65+i)}. {math_render_html(opt)} {correct}")

            options_html = "<br>".join(option_lines)
        else:
            options_html = f"<span class='muted'>Long question. Tutor marks manually.</span>"

        question_file_html = ""

        if q["question_file_path"]:
            question_file_html = f"""
            <div class="mini" style="margin-top:8px">
                Attached file:
                <a class="links"
                   target="_blank"
                   href="/assessment-file/question/{q['id']}">
                    {escape(q['question_file_name'] or 'Open file')}
                </a>
            </div>
            """
        
        question_rows += f"""
        <tr>
            <td>{q['question_order']}</td>
            <td>{escape(q['question_type'])}</td>
            <td style="min-width:260px">
                {math_render_html(q['question_text'], tag='div', style='white-space:pre-wrap')}
                {question_file_html}
            </td>
            <td>{options_html}</td>
            <td>{q['points']}</td>
            <td>
                <a class="btn mini secondary"
                   href="/tutor/assessments/{assessment_id}/question/{q['id']}/edit">
                    Edit
                </a>
            </td>
        </tr>
        """

    publish_button = ""

    if questions:
        publish_button = f"""
        <form method="post" action="/tutor/assessments/{assessment_id}/publish" style="display:inline">
            <button class="btn mini success">
                {"Unpublish" if a["is_published"] else "Publish"}
            </button>
        </form>
        """
        
    delete_button = ""

    if lock_reason:
        delete_button = f"""
        <button class="btn mini danger" disabled title="{escape(lock_reason)}">
            Delete Locked
        </button>
        """

    elif attempts > 0:
        delete_button = """
        <button class="btn mini danger" disabled title="This assessment already has learner attempts.">
            Cannot Delete
        </button>
        """

    else:
        delete_button = f"""
        <form method="post"
              action="/tutor/assessments/{assessment_id}/delete"
              style="display:inline"
              onsubmit="return confirm('Delete this assessment permanently?')">
            <button class="btn mini danger">
                Delete Assessment
            </button>
        </form>
        """
    

    body = f"""
    <section class="card">
        <div class="toolbar">
            <a class="btn mini secondary" href="/tutor/assessments">
                ← Back
            </a>
            
            <a class="btn mini success" href="/tutor/assessments/{assessment_id}/edit">
                Edit Assessment Settings
            </a>

            {publish_button}
            {delete_button}
        </div>

        <h1>{escape(a['title'])}</h1>

        <p class="muted">
            {grade_label(a['grade'])} - {escape(a['subject_name'])} |
            Duration: {a['duration_minutes']} minutes |
            Status: {"Published" if a["is_published"] else "Draft"}
        </p>

        <div class="card soft" style="margin-top:14px">
            <h2>Add Question</h2>

            <form method="post"
                  action="/tutor/assessments/{assessment_id}/question/add"
                  enctype="multipart/form-data"
                  class="grid"
                  style="grid-template-columns:1fr 1fr;gap:12px">

                <div>
                    <label>Question Type</label>
                    <select name="question_type" required>
                        <option value="MCQ">Multiple Choice</option>
                        <option value="LONG">Long Question</option>
                    </select>
                </div>

                <div>
                    <label>Points</label>
                    <input type="number" name="points" value="1" min="1" max="100">
                </div>

                <div style="grid-column:1/-1">
                    <label>Question</label>
                    <textarea name="question_text" rows="4" required></textarea>
                </div>

                <div style="grid-column:1/-1">
                    {math_helper_box()}
                </div>

                <div style="grid-column:1/-1">
                    <label>MCQ Options</label>
                    <p class="mini muted">
                        For multiple-choice questions only. Put each option on a new line.
                        The first line is option A, second line is option B, and so on.
                    </p>
                    <textarea name="options_text" rows="5"
                              placeholder="Option A&#10;Option B&#10;Option C&#10;Option D"></textarea>
                </div>

                <div>
                    <label>Correct Option for MCQ</label>
                    <select name="correct_index">
                        <option value="0">A</option>
                        <option value="1">B</option>
                        <option value="2">C</option>
                        <option value="3">D</option>
                        <option value="4">E</option>
                    </select>
                </div>

                <div style="grid-column:1/-1">
                    <label>Memo / Marking Guide</label>
                    <textarea name="memo" rows="4"></textarea>
                </div>
                
                <div style="grid-column:1/-1">
                    <label>Optional Question File</label>
                    <input type="file"
                           name="question_file"
                           accept=".jpg,.jpeg,.png,.gif,.webp,.pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.txt,.csv,.zip">
                    <div class="mini muted">
                        Optional. Use only when the question needs an attached file, screenshot, diagram or document.
                    </div>
                </div>

                <div style="grid-column:1/-1">
                    <button class="btn success">
                        Add Question
                    </button>
                </div>
            </form>
        </div>

        <div class="card soft" style="margin-top:14px">
            <h2>Questions</h2>

            <div class="scroll-x">
                <table>
                    <thead>
                        <tr>
                            <th>#</th>
                            <th>Type</th>
                            <th>Question</th>
                            <th>Options / Details</th>
                            <th>Points</th>
                            <th>Action</th>
                        </tr>
                    </thead>

                    <tbody>
                        {question_rows or "<tr><td colspan='6'>No questions added yet.</td></tr>"}
                    </tbody>
                </table>
            </div>
        </div>
    </section>
    """

    return page("Assessment Builder", body)


@app.post('/tutor/assessments/<int:assessment_id>/question/add')
def tutor_add_assessment_question(assessment_id):

    r = require_tutor()
    if r:
        return r

    tid = is_tutor()

    if not tutor_owns_assessment(tid, assessment_id):
        return page("Access Denied", card_msg("You cannot edit this assessment."))

    question_type = request.form.get("question_type", "MCQ").strip().upper()
    question_text = request.form.get("question_text", "").strip()
    options_text = request.form.get("options_text", "").strip()
    memo = request.form.get("memo", "").strip()

    try:
        points = int(request.form.get("points", 1))
    except Exception:
        points = 1

    try:
        correct_index = int(request.form.get("correct_index", 0))
    except Exception:
        correct_index = 0

    if points < 1:
        points = 1

    if question_type not in ["MCQ", "LONG"]:
        question_type = "MCQ"

    if not question_text:
        return page("Error", card_msg("Question text is required."))

    options_json = None

    if question_type == "MCQ":
        options = [
            x.strip()
            for x in options_text.splitlines()
            if x.strip()
        ]

        if len(options) < 2:
            return page("Error", card_msg("Multiple-choice questions need at least two options."))

        if correct_index < 0 or correct_index >= len(options):
            correct_index = 0

        options_json = json.dumps(options)
    else:
        correct_index = None
        options_json = None

    question_file_data = save_assessment_upload(
        request.files.get("question_file"),
        "tutor_questions"
    )

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT COALESCE(MAX(question_order),0) + 1 AS next_order
        FROM assessment_questions
        WHERE assessment_id=?
    """, (assessment_id,))

    question_order = cur.fetchone()["next_order"] or 1

    cur.execute("""
        INSERT INTO assessment_questions(
            assessment_id,
            question_type,
            question_text,
            options_json,
            correct_index,
            memo,
            points,
            question_order,
            created_at,
            question_file_path,
            question_file_name,
            question_file_type,
            question_file_uploaded_at
        )
        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)
    """, (
        assessment_id,
        question_type,
        question_text,
        options_json,
        correct_index,
        memo,
        points,
        question_order,
        now_utc_iso(),
        question_file_data["file_path"] if question_file_data else None,
        question_file_data["file_name"] if question_file_data else None,
        question_file_data["file_type"] if question_file_data else None,
        now_utc_iso() if question_file_data else None
    ))

    conn.commit()
    conn.close()

    return redirect(url_for("tutor_assessment_builder", assessment_id=assessment_id))


