def one_on_one_tutor_options(selected_id="", subject_id=None):
    """Build tutor options with each tutor's active one-on-one availability visible."""
    conn = get_db()
    cur = conn.cursor()

    if subject_id:
        cur.execute("""
            SELECT t.id, t.full_name,
                   GROUP_CONCAT(DISTINCT COALESCE(a.available_day,'Day TBC') || ' ' ||
                       COALESCE(a.available_start_time,'') ||
                       CASE WHEN COALESCE(a.available_end_time,'')<>'' THEN '-'||a.available_end_time ELSE '' END
                   ) AS availability_summary
            FROM tutors t
            JOIN tutor_subjects ts ON ts.tutor_id=t.id
            LEFT JOIN one_on_one_tutor_availability a
                   ON a.tutor_id=t.id AND COALESCE(a.is_active,1)=1
            WHERE ts.subject_id=? AND COALESCE(t.is_active,1)=1
            GROUP BY t.id, t.full_name
            ORDER BY t.full_name
        """, (subject_id,))
    else:
        cur.execute("""
            SELECT t.id, t.full_name,
                   GROUP_CONCAT(DISTINCT COALESCE(a.available_day,'Day TBC') || ' ' ||
                       COALESCE(a.available_start_time,'') ||
                       CASE WHEN COALESCE(a.available_end_time,'')<>'' THEN '-'||a.available_end_time ELSE '' END
                   ) AS availability_summary
            FROM tutors t
            LEFT JOIN one_on_one_tutor_availability a
                   ON a.tutor_id=t.id AND COALESCE(a.is_active,1)=1
            WHERE COALESCE(t.is_active,1)=1
            GROUP BY t.id, t.full_name
            ORDER BY t.full_name
        """)

    rows = cur.fetchall()
    conn.close()

    html = "<option value=''>Not assigned yet</option>"
    for row in rows:
        sel = "selected" if str(row["id"]) == str(selected_id or "") else ""
        availability = (row["availability_summary"] or "No availability captured").replace(",", "; ")
        label = f"{row['full_name']} | Availability: {availability}"
        html += f"<option value='{row['id']}' {sel}>{escape(label)}</option>"

    return html


def one_on_one_tutor_availability_html(tutor_id=None, subject=None, empty_message="No tutor availability captured yet."):
    """Return a compact availability table for one tutor or all active tutors."""
    conn = get_db()
    cur = conn.cursor()
    where = ["COALESCE(a.is_active,1)=1", "COALESCE(t.is_active,1)=1"]
    params = []
    if tutor_id:
        where.append("a.tutor_id=?")
        params.append(tutor_id)
    if subject:
        where.append("(a.subject IS NULL OR TRIM(a.subject)='' OR LOWER(a.subject)=LOWER(?))")
        params.append(subject)

    cur.execute(f"""
        SELECT a.*, t.full_name AS tutor_name
        FROM one_on_one_tutor_availability a
        JOIN tutors t ON t.id=a.tutor_id
        WHERE {' AND '.join(where)}
        ORDER BY t.full_name, a.available_day, a.available_start_time
    """, params)
    rows = cur.fetchall()
    conn.close()

    if not rows:
        return f"<div class='card soft mini muted'>{escape(empty_message)}</div>"

    body = "".join(
        f"<tr><td>{escape(r['tutor_name'])}</td>"
        f"<td><strong>{escape(r['available_day'] or 'Day TBC')}</strong></td>"
        f"<td>{escape(r['available_start_time'] or 'Time TBC')} - {escape(r['available_end_time'] or 'Time TBC')}</td>"
        f"<td>{escape(r['grade_level'] or 'Any')}</td>"
        f"<td>{escape(r['subject'] or 'General')}</td>"
        f"<td>{escape(r['notes'] or '—')}</td></tr>"
        for r in rows
    )
    return f"""
        <div class='scroll-x'>
            <table>
                <thead><tr><th>Tutor</th><th>Available Day</th><th>Available Time</th><th>Grade</th><th>Subject</th><th>Notes</th></tr></thead>
                <tbody>{body}</tbody>
            </table>
        </div>
    """



def one_on_one_all_tutors_availability_html():
    """List every active tutor eligible for one-on-one tutoring, including tutors without availability."""
    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT
            t.id,
            t.full_name,
            t.phone,
            GROUP_CONCAT(
                DISTINCT CASE
                    WHEN COALESCE(ts.delivery_mode, 'GROUP') IN ('ONE_ON_ONE', 'BOTH')
                    THEN grade_label_placeholder
                END
            ) AS unused_placeholder
        FROM tutors t
        LEFT JOIN tutor_subjects ts ON ts.tutor_id=t.id
        WHERE COALESCE(t.is_active,1)=1
          AND EXISTS (
              SELECT 1
              FROM tutor_subjects eligible_ts
              WHERE eligible_ts.tutor_id=t.id
                AND COALESCE(eligible_ts.delivery_mode,'GROUP') IN ('ONE_ON_ONE','BOTH')
          )
        GROUP BY t.id, t.full_name, t.phone
        ORDER BY t.full_name
    """.replace("grade_label_placeholder", "''"))
    tutors = cur.fetchall()

    tutor_rows = []
    for tutor in tutors:
        cur.execute("""
            SELECT s.name, s.grade, COALESCE(ts.delivery_mode,'GROUP') AS delivery_mode
            FROM tutor_subjects ts
            JOIN subjects s ON s.id=ts.subject_id
            WHERE ts.tutor_id=?
              AND COALESCE(ts.delivery_mode,'GROUP') IN ('ONE_ON_ONE','BOTH')
            ORDER BY CAST(REPLACE(s.grade,'G','') AS INTEGER), s.name
        """, (tutor["id"],))
        subject_rows = cur.fetchall()

        cur.execute("""
            SELECT available_day, available_start_time, available_end_time,
                   grade_level, subject, notes
            FROM one_on_one_tutor_availability
            WHERE tutor_id=? AND COALESCE(is_active,1)=1
            ORDER BY available_day, available_start_time
        """, (tutor["id"],))
        availability_rows = cur.fetchall()

        subjects_html = "<br>".join(
            f"<span class='mini'><strong>{escape(grade_label(s['grade']))}</strong> — {escape(s['name'])} "
            f"<span class='badge'>{escape('Both' if s['delivery_mode']=='BOTH' else 'One-on-One')}</span></span>"
            for s in subject_rows
        ) or "<span class='mini muted'>No one-on-one subjects assigned.</span>"

        if availability_rows:
            availability_html = "<br>".join(
                f"<span class='mini'><strong>{escape(a['available_day'] or 'Day TBC')}</strong>: "
                f"{escape(a['available_start_time'] or 'Time TBC')} - {escape(a['available_end_time'] or 'Time TBC')}"
                f" | {escape(a['grade_level'] or 'Any grade')} | {escape(a['subject'] or 'General')}"
                f"{(' | ' + escape(a['notes'])) if a['notes'] else ''}</span>"
                for a in availability_rows
            )
            availability_status = "<span class='badge success'>Availability captured</span>"
        else:
            availability_html = "<span class='mini muted'>This tutor has not captured one-on-one availability yet.</span>"
            availability_status = "<span class='badge warning'>Not captured</span>"

        tutor_rows.append(f"""
            <tr>
                <td><strong>{escape(tutor['full_name'])}</strong><div class='mini muted'>{escape(tutor['phone'] or 'No phone captured')}</div></td>
                <td>{subjects_html}</td>
                <td>{availability_html}</td>
                <td>{availability_status}</td>
            </tr>
        """)

    conn.close()

    if not tutor_rows:
        return "<div class='card soft mini muted'>No active tutors are currently assigned for one-on-one tutoring.</div>"

    return f"""
        <div class='scroll-x'>
            <table>
                <thead>
                    <tr><th>Tutor</th><th>One-on-One Subjects</th><th>Availability</th><th>Status</th></tr>
                </thead>
                <tbody>{''.join(tutor_rows)}</tbody>
            </table>
        </div>
    """

