def one_on_one_admin_rows(q="", status="", payment_status="", grade="", subject_id="", package_type="", session_type=""):
    where = ["1=1"]
    params = []

    if q:
        like = f"%{q}%"
        where.append("(r.learner_name LIKE ? OR r.student_phone LIKE ? OR r.parent_name LIKE ? OR r.parent_phone LIKE ? OR r.topic_or_problem_area LIKE ?)")
        params.extend([like, like, like, like, like])
    if status:
        where.append("r.request_status=?")
        params.append(status)
    if payment_status:
        where.append("r.payment_status=?")
        params.append(payment_status)
    if grade:
        where.append("r.grade=?")
        params.append(grade)
    if subject_id:
        where.append("r.subject_id=?")
        params.append(subject_id)
    if package_type:
        where.append("r.package_type=?")
        params.append(package_type)
    if session_type:
        where.append("r.session_type=?")
        params.append(session_type)

    conn = get_db()
    cur = conn.cursor()
    cur.execute(f"""
        SELECT r.*, t.full_name AS tutor_name, tm.full_name AS manager_name,
               (SELECT COUNT(*) FROM one_on_one_bookings b WHERE b.request_id=r.id) AS booking_count,
               (SELECT COUNT(*) FROM one_on_one_bookings b WHERE b.request_id=r.id AND b.booking_status='Completed') AS completed_count
        FROM one_on_one_requests r
        LEFT JOIN tutors t ON t.id=r.assigned_tutor_id
        LEFT JOIN tutor_managers tm ON tm.id=r.assigned_tutor_manager_id
        WHERE {' AND '.join(where)}
        ORDER BY r.created_at DESC
        LIMIT 400
    """, params)
    rows = cur.fetchall()
    conn.close()
    return rows


def require_one_on_one_operations():
    """
    Allows one-on-one operational access to Admin, Admission, AQM and One-on-One Support Manager roles.
    """
    if is_admin() or is_admission_coordinator() or is_academic_quality_manager() or is_one_on_one_manager():
        return None

    if request.path.startswith("/one-on-one-manager"):
        return redirect(url_for("one_on_one_manager_login"))

    if request.path.startswith("/aqm/one-on-one"):
        return redirect(url_for("aqm_login"))

    if request.path.startswith("/admission/one-on-one"):
        return redirect(url_for("admission_login"))

    return redirect(url_for("admin_login"))


def one_on_one_operations_nav():
    """
    Shows the correct navigation for the person currently managing one-on-one requests.
    """
    if is_one_on_one_manager():
        return one_on_one_manager_nav()
    if is_academic_quality_manager() and not is_admin():
        return aqm_nav()
    if is_admission_coordinator() and not is_admin():
        return admission_nav()
    return admin_nav()


def one_on_one_operations_base_path():
    if is_one_on_one_manager():
        return "/one-on-one-manager"
    if is_academic_quality_manager() and not is_admin():
        return "/aqm/one-on-one"
    if is_admission_coordinator() and not is_admin():
        return "/admission/one-on-one"
    return "/admin/one-on-one"


def one_on_one_operations_actor_label():
    if is_one_on_one_manager():
        return "One-on-One Support Manager: " + str(session.get("one_on_one_manager_name", "One-on-One Support Manager"))

    if is_academic_quality_manager() and not is_admin():
        return "AQM: " + str(session.get("aqm_name", "Academic Quality Manager"))

    if is_admission_coordinator() and not is_admin():
        return "Admission Coordinator: " + str(session.get("admission_coordinator_name", "Admission Coordinator"))

    if is_admin():
        admin_name = session.get("admin_username") or "Admin"
        admin_role = session.get("admin_role") or "ADMIN"
        return f"{admin_role} Admin: {admin_name}"

    return "EBTA Operations"



@app.get('/one-on-one-manager/tutors')
def one_on_one_manager_tutors():
    r = require_one_on_one_manager()
    if r:
        return r

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT COUNT(DISTINCT t.id) AS c
        FROM tutors t
        JOIN tutor_subjects ts ON ts.tutor_id=t.id
        WHERE COALESCE(t.is_active,1)=1
          AND COALESCE(ts.delivery_mode,'GROUP') IN ('ONE_ON_ONE','BOTH')
    """)
    total_tutors = cur.fetchone()["c"] or 0

    cur.execute("""
        SELECT COUNT(DISTINCT ta.tutor_id) AS c
        FROM one_on_one_tutor_availability ta
        JOIN tutors t ON t.id=ta.tutor_id
        JOIN tutor_subjects ts ON ts.tutor_id=t.id
        WHERE COALESCE(t.is_active,1)=1
          AND COALESCE(ta.is_active,1)=1
          AND COALESCE(ts.delivery_mode,'GROUP') IN ('ONE_ON_ONE','BOTH')
    """)
    tutors_with_availability = cur.fetchone()["c"] or 0

    cur.execute("""
        SELECT COUNT(*) AS c
        FROM one_on_one_tutor_availability ta
        JOIN tutors t ON t.id=ta.tutor_id
        WHERE COALESCE(t.is_active,1)=1
          AND COALESCE(ta.is_active,1)=1
    """)
    active_slots = cur.fetchone()["c"] or 0
    conn.close()

    missing_availability = max(total_tutors - tutors_with_availability, 0)

    body = f"""
    {one_on_one_manager_nav()}
    <section class="card">
        <div class="ooo-page-intro">
            <div>
                <div class="ooo-page-kicker">Tutor capacity</div>
                <h1>One-on-One Tutors & Availability</h1>
                <p class="muted">
                    Review every tutor assigned to individual sessions, their subjects and the times they have made available.
                </p>
            </div>
            <a class="btn secondary" href="/one-on-one-manager">← Dashboard</a>
        </div>

        <div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px">
            {stat("Eligible Tutors", str(total_tutors))}
            {stat("Availability Captured", str(tutors_with_availability))}
            {stat("Missing Availability", str(missing_availability))}
            {stat("Active Time Slots", str(active_slots))}
        </div>

        <div class="ooo-quick-grid">
            <a class="ooo-quick-card" href="/one-on-one-manager?status=Pending">
                <b>Match pending learners</b>
                <span>Use tutor subjects and available times to allocate new requests.</span>
            </a>
            <a class="ooo-quick-card" href="/one-on-one-manager?status=Assigned">
                <b>Review assigned requests</b>
                <span>Confirm that allocated tutors and learner times align.</span>
            </a>
            <a class="ooo-quick-card" href="/one-on-one-manager?status=Confirmed">
                <b>Check confirmed sessions</b>
                <span>Monitor scheduled individual sessions and completion progress.</span>
            </a>
            <a class="ooo-quick-card" href="/one-on-one-manager">
                <b>Return to operations</b>
                <span>View the complete one-on-one workflow and all requests.</span>
            </a>
        </div>
    </section>

    <section class="card">
        <div class="ooo-section-header">
            <div>
                <h2>Tutor Directory</h2>
                <p class="muted" style="margin:5px 0 0">Tutors appear here before any learner request is submitted.</p>
            </div>
        </div>
        {one_on_one_all_tutors_availability_html()}
    </section>
    """
    return page("One-on-One Tutors & Availability", body)


